local H70_GREEN_TOTAL = 886   -- 803 (the full harness-68 suite) + section-0k (24) + CO1-CO4 (54) + 1
local H71_GREEN_TOTAL = 1068  -- the harness-71 suite count (its own final print is 1065: + the find-count check)
local H72_GREEN_TOTAL = 1124  -- the harness-72 suite count (its own final print is 1120: its find check is inside the suite)
local H73_GREEN_TOTAL = 1198  -- the harness-73 suite count (its own final print is 1194 + the find check)
