      { name = "unreadable", uid = 9005, owns = { W_VTB }, wavering_raises = true },
    }, cards = { { id = "9004", state = "active", vis = true }, { id = "9005", state = "active", vis = true } },
       bar = { { id = "b1", key = W_HYV }, { id = "b2", key = W_VTB } } })
