    local b = (count_log(W, "reason: wavering (self)") == 0)
    check(TAG .. "N4b: no wavering-self reason was ever emitted [live log]", lg(TAG, b))
    note90(W, TAG); tally(W)
    return a and lg(TAG, b)
  end

