  local function world_p10(PATH, TAG)
    local W = make_world({ can_perform = true, units = {
      { name = "chaos", uid = 9391, owns = { LOV }, melee = true, wavering = false },
    }, cards = { { id = "9391", state = "active", vis = true } }, bar = { { id = "b1", key = LOV } } })
    print("== " .. TAG .. "P10. MELEE_UNWAVERING member: in melee -> FIRES (locus_of_virulence) == ")
    if not boot92(W, PATH, TAG, 9391, "locus_of_virulence", "P10") then return nil end
    polln(W, 1)
    local caster = unit_of(W, 9391)
    local a = (#W.fires == 1 and W.fires[1].uid == 9391 and W.fires[1].key == LOV)
    check(TAG .. "P10a: the in-melee unit fired locus_of_virulence once (" .. fire_detail(W) .. ")", a)
    local b = (fire_target_for(W, 9391) == caster)
    check(TAG .. "P10b: the cast target is the OWNER itself (self-cast)", b)
    local c = (count_log(W, "reason: in melee, morale not wavering") == 1)
    check(TAG .. "P10c: the shared in-melee-self reason is used [live log]", lg(TAG, c))
    note92(W, TAG); tally(W)
    return a and b and lg(TAG, c)
  end

  print()
  print("== HARNESS 92 - the final roster build: two new ally-heal triggers + four melee entries ==")
  local p01a = world_p1(ANN, "[annotated] ");  local p01b = world_p1(LIVE, "[live] ")
  local p02a = world_p2(ANN, "[annotated] ");  local p02b = world_p2(LIVE, "[live] ")
  local p03a = world_p3(ANN, "[annotated] ");  local p03b = world_p3(LIVE, "[live] ")
  local p04a = world_p4(ANN, "[annotated] ");  local p04b = world_p4(LIVE, "[live] ")
  local p05a = world_p5(ANN, "[annotated] ");  local p05b = world_p5(LIVE, "[live] ")
  local p06a = world_p6(ANN, "[annotated] ");  local p06b = world_p6(LIVE, "[live] ")
  local p07a = world_p7(ANN, "[annotated] ");  local p07b = world_p7(LIVE, "[live] ")
  local p08a = world_p8(ANN, "[annotated] ");  local p08b = world_p8(LIVE, "[live] ")
  local p09a = world_p9(ANN, "[annotated] ");  local p09b = world_p9(LIVE, "[live] ")
  local p10a = world_p10(ANN, "[annotated] "); local p10b = world_p10(LIVE, "[live] ")

  local results = { p01a, p01b, p02a, p02b, p03a, p03b, p04a, p04b, p05a, p05b,
                    p06a, p06b, p07a, p07b, p08a, p08b, p09a, p09b, p10a, p10b }
  local n_ok = 0
  for _, r in ipairs(results) do if posv(r) then n_ok = n_ok + 1 end end

  check("every ui tick ran clean across the HARNESS-92 worlds (" .. RED92.ui .. " failures)", RED92.ui == 0)

  if not RED_MODE then
    check("the HARNESS-92 worlds all behaved (live+annotated: P1..P10) - " .. n_ok .. "/20", n_ok == 20)
    check("HEADLINE (harness 92): THE FINAL ROSTER BUILD ships the SIX built individual abilities from the "
      .. "remaining-abilities triage - TWO NEW ally-heal triggers, each its own evaluator (blood_sacrifice: cast "
      .. "on the lowest-health ally in range at or below 75%; eat_da_runts: cast on self at or below 75%, else the "
      .. "lowest-health ally in range) plus FOUR in-melee-self entries riding the EXISTING melee_unwavering "
      .. "evaluator (Locus of Virulence, The Dance of Dreaming, The Waltz of Lethargy, Ultimate Verdict). Each new "
      .. "trigger casts on the CHOSEN ALLY, uses the 70% named range constant (70 m), and RE-CHECKS the gap "
      .. "and the ally's health before the cast (skip on drift). The table grows 642 -> 579 entries (682 -> 605 "
      .. "keys); melee_unwavering 477 -> 480 (Accusation moved to enemy_engaged_or_shot); no new chunk locals.", n_ok == 20)
  else
    check("RED CONTROL (harness 92): N/A for the harness-94 round - the harness-94 red snapshot (the shipped "
      .. "harness-92 build) already carries the round-92 roster, so the grown-table pins and every P-world pass - "
      .. n_ok
      .. "/20 world results pass (want 20), fires " .. RED92.fires .. ", claims " .. RED92.claims, n_ok == 20)
  end
end
if not LIGHT then run_h92() end

-- ============================================================================
-- HARNESS 93 (this round): THE PER-ABILITY TOOLTIP LINE.
--   The mod appended ONE generic sentence to every implemented ability's
--   tooltip: "Automatic: this ability fires by itself while the unit charges
--   - click the M/A badge ...". That described a CHARGE behaviour most
--   abilities do not have, so it was wrong for the bulk-added entries (which
--   ride a handful of evaluators). THE FIX: the appended line is now ONE
--   SHORT clause describing the TRIGGER the entry actually rides, COMPOSED at
--   load from the entry's own trigger field (FOURTH.TRIGGER_TIP[trigger] ->
--   ability.tip). The old generic sentence is REMOVED from the twui.xml.
--
--   This harness proves, against the LIVE source and the ANNOTATED copy:
--     0q: the FOURTH.TRIGGER_TIP wording map exists; the wiring assigns
--         ability.tip from the entry's trigger; the old generic sentence is
--         gone from the source.
--     D1: the WHOLE ABILITIES table (captured through the ipairs hook) carries
--         a NON-EMPTY tooltip line on EVERY implemented entry.
--     D2: every entry's line EQUALS the allowed wording for its actual trigger
--         (data-driven over all entries - not a sample).
--     D3: no entry is left unmatched, and every trigger used in the table has
--         a wording entry.
--     D4: the shipped twui.xml carries the new short line and NOT the old
--         generic sentence.
--
--   RED CONTROL: with H93_LIVE / H93_ANN / H93_TWUI pointing at the pre-edit
--   snapshot (the shipped harness-93 build: 579 entries, NO TRIGGER_TIP, the
--   old twui.xml sentence) the 0q map+wiring tokens, the D1/D2 per-entry
--   lines and the D4 twui old-sentence check fail; the table-size and
--   trigger-wording-coverage checks still pass (the snapshot has the same
--   table and the same triggers).
-- ============================================================================
function run_h93()
  -- the allowed wording table - MUST match FOURTH.TRIGGER_TIP in the source.
  local TIP = {
    charge = "When armed, fires when this unit charges or is in melee",
    tired = "When armed, fires when this unit is tired or worse",
    melee = "When armed, fires when this unit is in melee",
    melee_low_morale = "When armed, fires when this unit is in melee and wavering",
    melee_unwavering = "When armed, fires when this unit is in melee",
    barrier_broken = "When armed, fires when this unit's barrier breaks",
    charge_or_melee = "When armed, fires when this unit charges or is in melee",
    ushoran_health = "When armed, fires when this unit is at or below 75% health",
    glorious_death = "When armed, fires when a Slayer ally in range is in melee",
    verminking_wavering = "When armed, fires when an ally in range is wavering",
    melee_health75 = "When armed, fires when this unit is in melee and at or below 75% health",
    metallurgy_melee = "When armed, fires when this unit or an ally in range is in melee",
    charge_only = "When armed, fires when this unit charges",
    wavering_self = "When armed, fires when this unit is wavering",
    wavering_self_or_ally = "When armed, fires when this unit or an ally in range is wavering",
    charge_or_wavering = "When armed, fires when this unit charges or is wavering",
    wavering_ally_range = "When armed, fires when an ally in range is wavering",
    blood_sacrifice = "When armed, fires on the lowest-health ally in range when it is at or below 75% health",
    eat_da_runts = "When armed, fires when this unit is at or below 75% health, otherwise on the lowest-health ally in range",
    enemy_engaged_or_shot = "When armed, fires when an enemy unit in range is in melee or under missile fire",
    enemy_melee = "When armed, fires on the closest enemy unit in range that is fighting in melee",
    enemy_ground_area = "When armed, fires when an enemy in range is in melee or under missile fire and the area hex is placed on its ground",
    enemy_ground_melee = "When armed, fires when an enemy in range is fighting in melee and the summon is placed on its ground",
    self_summon_melee = "When armed, fires when this unit itself is fighting in melee and the summon is cast on it",
    enemy_low_health_noncommander = "When armed, fires on the lowest-health enemy in range that is below 20% health and is not a Lord or Hero",
    enemy_melee_noncommander = "When armed, fires on the closest enemy in range that is fighting in melee and is not a Lord or Hero",
    ally_heal = "When armed, fires on the lowest-health ally in range when it is at or below 75% health",
    ally_heal_melee = "When armed, fires when this unit is in melee, on the lowest-health ally in range at or below 75% health",
    ally_wavering = "When armed, fires on a wavering ally in range",
    ally_melee_buff = "When armed, fires when this unit is in melee, on an ally in range",
    ally_overseer = "When armed, fires on a non-commander, non-large ally in range",
    ally_beast = "When armed, fires on a beast ally in range",
    ally_broken = "When armed, fires on a broken-morale ally in range",
    ally_missile = "When armed, fires on a missile-capable ally in range",
    ally_warmachine_heal = "When armed, fires on the lowest-health war machine ally in range that is at or below 75% health",
    ally_hellforged_heal = "When armed, fires on the lowest-health Hell-Forged ally in range that is at or below 75% health",
    ally_monster_heal = "When armed, fires on the lowest-health monster ally in range that is at or below 75% health",
    ally_construct_heal = "When armed, fires on the lowest-health construct ally in range that is at or below 75% health",
    ally_infinite_buff = "When armed, fires on an ally anywhere on the field (infinite range), cast on that ally",
    ally_winds = "When armed, fires on the ally with the most hit points remaining, cast on that ally",
    melee_skip_commanders = "When armed, fires when this unit is in melee, unless every enemy it is fighting is a Lord or Hero",
    enemy_ground_melee_infantry = "When armed, fires on the closest infantry unit in range that is fighting in melee",
    air_drop_on_infantry = "When armed, fires when the nearest enemy unit with more than 10 models comes within 6 m of this unit's centre, and casts immediately on that evaluation - no delay at all - airborne where the ability requires it",
    health_aura_ground = "When armed, fires when this unit or a friendly unit in its area is at or below 75% health, placed on the ground under it",
    health_aura_ally = "When armed, fires when this unit or a friendly unit in range is at or below 75% health, cast on it",
    health_aura_self = "When armed, fires when this unit or a friendly unit in its aura is at or below 75% health, cast on itself",
    health_below_15 = "When armed, fires when this unit is below 15% health",
  }
  local OLD_LINE = "this ability fires by itself while the unit charges"
  local NEW_LINE = "Automatic: click the M/A badge to switch automatic use on or off"
  local TWUI_PATH = os.getenv("H93_TWUI")
    or "C:/Users/vlady/Desktop/WH3_mod/mod_source/ui/common ui/special_ability_tooltip.twui.xml"
  local n_words = 0
  for _ in pairs(TIP) do n_words = n_words + 1 end

  local live_src93 = read_file(LIVE)
  local ann_src93  = read_file(ANN)
  local twui_src   = read_file(TWUI_PATH)

  -- --------------------------------------------------- 0q: source tokens (both)
  print("== HARNESS 93 - section 0q: the per-ability tooltip line in the source (BOTH files) ==")
  for _, f in ipairs({ { name = "live", src = live_src93 }, { name = "ann", src = ann_src93 } }) do
    local nm, s = f.name, f.src
    check("0q " .. nm .. ": the FOURTH.TRIGGER_TIP wording map exists",
      raw_find(s, "FOURTH.TRIGGER_TIP = {", 1, true) ~= nil)
    check("0q " .. nm .. ": the wiring sets ability.tip from the entry's trigger",
      raw_find(s, "ability.tip = FOURTH.TRIGGER_TIP[ability.trigger]", 1, true) ~= nil)
    check("0q " .. nm .. ": the old generic tooltip sentence is GONE from the source",
      raw_find(s, OLD_LINE, 1, true) == nil)
    -- every required wording is present verbatim
    local miss = 0
    for _, want in pairs(TIP) do
      if raw_find(s, want, 1, true) == nil then miss = miss + 1 end
    end
    check("0q " .. nm .. ": all " .. tostring(n_words) .. " required wording strings are present verbatim", miss == 0)
  end

  -- --------------------------------------------------- D1-D3: the whole table
  print("== HARNESS 93 - the per-ability tooltip line: EVERY implemented entry ==")
  if OH77.cap == nil then
    local Wfallback = make_world({ can_perform = true, units = {} })
    pcall(load_world, Wfallback, LIVE)
  end
  local total, nonempty, matched = 0, 0, 0
  local unmatched = {}
  local used = {}
  if OH77.cap ~= nil then
    for _, e in ipairs(OH77.cap) do
      total = total + 1
      if e.trigger ~= nil then used[e.trigger] = true end
      local want = TIP[e.trigger]
      if type(e.tip) == "string" and e.tip ~= "" then nonempty = nonempty + 1 end
      if want ~= nil and e.tip == want then
        matched = matched + 1
      else
        unmatched[#unmatched + 1] = tostring(e.marker) .. "(" .. tostring(e.trigger) .. ")"
      end
    end
  end
  check("D1a: the WHOLE ABILITIES table was captured (" .. total .. " entries, want 707)",
    total == 707)
  check("D1b: EVERY implemented entry carries a NON-EMPTY tooltip line (" .. nonempty .. "/" .. total .. ")",
    nonempty == total and total == 707)
  check("D2: EVERY implemented entry's line equals the allowed wording for its actual trigger ("
    .. matched .. "/" .. total .. ")", matched == total and total == 707)
  local unmatched_msg = ""
  if #unmatched > 0 then
    local shown = {}
    for i = 1, math.min(#unmatched, 6) do shown[i] = unmatched[i] end
    unmatched_msg = " (first " .. #shown .. " of " .. #unmatched .. ": " .. table.concat(shown, ", ")
      .. (#unmatched > #shown and ", ..." or "") .. ")"
  end
  check("D3a: no entry left unmatched (" .. #unmatched .. ")" .. unmatched_msg, #unmatched == 0)
  local missing_trig = 0
  for tr in pairs(used) do
    if TIP[tr] == nil then missing_trig = missing_trig + 1 end
  end
  check("D3b: every trigger used in the table has an allowed wording (missing = " .. missing_trig .. ")",
    missing_trig == 0)

  -- --------------------------------------------------- D4: the shipped twui.xml
  check("D4a: the twui.xml carries the NEW short line", raw_find(twui_src, NEW_LINE, 1, true) ~= nil)
  check("D4b: the OLD generic sentence is GONE from the twui.xml", raw_find(twui_src, OLD_LINE, 1, true) == nil)

  if not RED_MODE then
    check("HEADLINE (harness 93): the appended tooltip line is now ONE SHORT clause per ability, COMPOSED from the "
      .. "trigger the entry actually rides (FOURTH.TRIGGER_TIP[trigger] -> ability.tip) - all " .. total
      .. " entries match their evaluator; the old one-size 'fires by itself while the unit charges' sentence is "
      .. "removed from the shipped twui.xml, which now carries only the short badge hint.", matched == total and total == 707)
  else
    check("RED CONTROL (harness 93): N/A for the harness-94 round - the harness-94 red snapshot (the shipped "
      .. "harness-93 build) already carries FOURTH.TRIGGER_TIP and the entry wiring, so every entry matches its "
      .. "trigger wording: " .. matched .. "/" .. total .. " entries match (want 707), total " .. total
      .. " (want 707)",
      matched == 707 and total == 707)
  end
end
if not LIGHT then run_h93() end

-- ============================================================================
-- HARNESS 94 (this round): ACCUSATION'S AUTOMATIC ACTIVATION - the FIRST
--   ENEMY-TARGETED trigger, and the first ability whose cast target is an
--   ENEMY unit.
--   A new reusable evaluator `enemy_engaged_or_shot` fires when an enemy unit
--   in range is in melee OR under missile fire; the chosen enemy is the CAST
--   TARGET (never the owner), cast through the round-4-proven bench_fresh
--   fresh-handle route (caster + target re-fetched the same tick). Accusation's
--   entry moves from melee_unwavering (481 -> 480) onto the new trigger
--   (0 -> 1); the table stays 579 entries / 605 keys.
--   This harness proves, against the LIVE source and the ANNOTATED copy:
--     0r: the evaluator/helpers/constant/wiring/tooltip tokens, the moved
--         trigger counts, the poll clears, and the distinct live reason strings;
--     N1..N9: enemy in melee in range -> FIRES at that enemy; enemy under
--         missile fire -> FIRES; neither -> SILENT; out of range -> SILENT;
--         condition lapses between pick and cast -> SKIPPED; unreadable
--         is_under_missile_attack -> treated FALSE with the one-time log;
--         self-cast regression (the target is NEVER the owner); prefer in-melee
--         over missile; closest among equals.
--   RED CONTROL: with H94_LIVE / H94_ANN pointing at the pre-edit snapshot (the
--   shipped harness-93 build: no enemy evaluator, Accusation still on
--   melee_unwavering = 481) the 0r section tokens fail and every firing N-world
--   fires nothing - only the SILENT worlds pass (N3/N4 both files = 4, plus the
--   ANNOTATED legs of the lapse/unreadable worlds N5/N6 = 2).
-- ============================================================================
function run_h94()
  local ACC = "wh_main_hero_abilities_accusation"
  local live_src94 = read_file(LIVE)
  local ann_src94  = read_file(ANN)
  local RED94 = { fires = 0, claims = 0, ui = 0 }
  local function posv(v) return (v == true) or (type(v) == "number") end
  local function lg(tag, v) return (tag ~= "[live] ") or posv(v) end
  local function badd94(marker) return "zz_auto_badge_" .. marker end
  local function cp(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function note94(W, TAG)
    RED94.ui = RED94.ui + (W.ui_failures or 0)
    if TAG == "[live] " then
      RED94.fires = RED94.fires + #W.fires
      RED94.claims = RED94.claims + count_log(W, "claim: ")
    end
  end
  local function boot94(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, badd94(marker)); ui(W)
    W.conflict = true
    return true
  end
  -- the enemy UNIT OBJECT behind a uid (in the enemy list, not the friendly one)
  local function enemy_of(W, uid)
    for i = 1, #(W.enemy_entries or {}) do
      local pr = W.enemy_entries[i]
      if pr ~= nil and pr.unit ~= nil then
        local ok, id = pcall(function() return pr.unit:unique_ui_id() end)
        if ok and tostring(id) == tostring(uid) then return pr.unit end
      end
    end
    return nil
  end

  -- --------------------------------------------------- 0r: tokens (both files)
  print("== HARNESS 94 - section 0r: Accusation's enemy trigger tokens (BOTH files) ==")
  for _, f in ipairs({ { name = "live", src = live_src94 }, { name = "ann", src = ann_src94 } }) do
    local nm, s = f.name, f.src
    check("0r " .. nm .. ": the enemy_engaged_or_shot evaluator exists",
      raw_find(s, "function FOURTH.evaluate_enemy_engaged_or_shot(unit, routing)", 1, true) ~= nil)
    check("0r " .. nm .. ": the trigger is wired in the map",
      raw_find(s, "enemy_engaged_or_shot = FOURTH.evaluate_enemy_engaged_or_shot,", 1, true) ~= nil)
    check("0r " .. nm .. ": the tooltip wording entry is present verbatim",
      raw_find(s, "enemy_engaged_or_shot = \"When armed, fires when an enemy unit in range is in melee or under missile fire\",", 1, true) ~= nil)
    check("0r " .. nm .. ": Accusation rides the new trigger",
      raw_find(s, "{ marker = \"accusation\", name = \"Accusation\", trigger = \"enemy_engaged_or_shot\",", 1, true) ~= nil)
    check("0r " .. nm .. ": the 70% named range constant exists (52 m)",
      raw_find(s, "FOURTH.ACCUSATION_RANGE_M = 52", 1, true) ~= nil)
    check("0r " .. nm .. ": the enemy enumerator is read",
      raw_find(s, "bm:get_scriptunits_for_main_enemy_army_to_local_player()", 1, true) ~= nil)
    check("0r " .. nm .. ": the proven fresh-caster re-fetch helper exists",
      raw_find(s, "function FOURTH.eg_fresh_caster_su(unit)", 1, true) ~= nil)
    check("0r " .. nm .. ": is_under_missile_attack is read fail-safe",
      raw_find(s, "enemy:is_under_missile_attack()", 1, true) ~= nil)
    check("0r " .. nm .. ": the trigger counts moved (melee_unwavering 480, enemy_engaged_or_shot 1)",
      cp(s, 'trigger = "melee_unwavering"') == 374 and cp(s, 'trigger = "enemy_engaged_or_shot"') == 85
      and cp(s, 'trigger = "enemy_ground_area"') == 9 and cp(s, 'trigger = "enemy_ground_melee"') == 67)
    check("0r " .. nm .. ": the table stays 688 entries / 688 badges",
      cp(s, "\t{ marker = ") == 707 and cp(s, 'badge = "') == 707)
    check("0r " .. nm .. ": the self-cast writes stay exactly two",
      cp(s, "FOURTH.cast_target = unit") == 2)
    check("0r " .. nm .. ": the enemy slots are set once and cleared (eg_enemy 3, eg_caster_su 2)",
      cp(s, "FOURTH.eg_enemy = nil") == 3 and cp(s, "FOURTH.eg_caster_su = nil") == 2
      and cp(s, "FOURTH.eg_enemy = best_enemy") == 2)
    check("0r " .. nm .. ": NO army-bar key is in the mod (standing exclusion)",
      raw_find(s, "army_abilities", 1, true) == nil)
  end
  check("0r live: the DISTINCT arm reason strings are present",
    raw_find(live_src94, 'reason = "enemy in melee (targeting " .. etype .. ")"', 1, true) ~= nil
    and raw_find(live_src94, 'reason = "enemy under missile fire (targeting " .. etype .. ")"', 1, true) ~= nil)
  check("0r live: the chosen-target, pre-cast re-check and lapse lines are reported",
    raw_find(live_src94, "\" target: '", 1, true) ~= nil
    and raw_find(live_src94, "\" pre-cast re-check:", 1, true) ~= nil
    and raw_find(live_src94, "\" SKIPPED: the chosen enemy lapsed before the cast", 1, true) ~= nil)
  check("0r live: the one-time unreadable-missile notice exists",
    raw_find(live_src94, "accusation: enemy is_under_missile_attack read UNAVAILABLE", 1, true) ~= nil)
  check("0r ann: the reading copy stays log-free and find-free",
    raw_find(ann_src94, "log(", 1, true) == nil and raw_find(ann_src94, "string.find", 1, true) == nil)

  -- ==========================================================================
  -- N1. ENEMY IN MELEE, IN RANGE -> FIRES at that enemy (fresh-handle route).
  -- ==========================================================================
  local function world_n1(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9401, owns = { ACC }, melee = false, in_range = true } },
      enemies = { { name = "orc_boyz", uid = 9402, melee = true } },
      cards = { { id = "9401", state = "active", vis = true } },
      bar = { { id = "b1", key = ACC } } })
    print("== " .. TAG .. "N1. ACCUSATION: an enemy in melee in range -> FIRES at it == ")
    if not boot94(W, PATH, TAG, 9401, "accusation", "N1") then return nil end
    local friendly0 = W.friendly_calls or 0
    polln(W, 1)
    local hunter = unit_of(W, 9401)
    local enemy = enemy_of(W, 9402)
    local a = (#W.fires == 1 and W.fires[1].uid == 9401 and W.fires[1].key == ACC)
    check(TAG .. "N1a: the hunter fired accusation once (" .. fire_detail(W) .. ")", a)
    local b = (fire_target_for(W, 9401) == enemy and enemy ~= nil and enemy ~= hunter)
    check(TAG .. "N1b: the cast target is the ENEMY, not the owner", b)
    local c = ((W.friendly_calls or 0) > friendly0)
    check(TAG .. "N1c: the CASTER was re-fetched FRESH on the firing tick (the proven route)", c)
    local d = (count_log(W, "reason: enemy in melee (targeting orc_boyz)") == 1)
    check(TAG .. "N1d: the melee-arm reason names the enemy type [live log]", lg(TAG, d))
    note94(W, TAG); tally(W)
    return a and b and c and lg(TAG, d)
  end

  -- ==========================================================================
  -- N2. ENEMY UNDER MISSILE FIRE, IN RANGE -> FIRES (distance-fallback range).
  -- ==========================================================================
  local function world_n2(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9411, owns = { ACC }, melee = false, dist = 20 } },
      enemies = { { name = "goblin_archers", uid = 9412, melee = false, missile = true } },
      cards = { { id = "9411", state = "active", vis = true } },
      bar = { { id = "b1", key = ACC } } })
    print("== " .. TAG .. "N2. ACCUSATION: an enemy under missile fire in range -> FIRES == ")
    if not boot94(W, PATH, TAG, 9411, "accusation", "N2") then return nil end
    polln(W, 1)
    local enemy = enemy_of(W, 9412)
    local a = (#W.fires == 1 and W.fires[1].uid == 9411 and W.fires[1].key == ACC)
    check(TAG .. "N2a: the hunter fired accusation once (" .. fire_detail(W) .. ")", a)
    local b = (fire_target_for(W, 9411) == enemy and enemy ~= nil)
    check(TAG .. "N2b: the cast target is the enemy under fire", b)
    local c = (count_log(W, "reason: enemy under missile fire (targeting goblin_archers)") == 1)
    check(TAG .. "N2c: the missile-arm reason names the enemy type [live log]", lg(TAG, c))
    note94(W, TAG); tally(W)
    return a and b and lg(TAG, c)
  end

  -- ==========================================================================
  -- N3. ENEMY IN RANGE BUT NEITHER in melee nor under fire -> SILENT.
  -- ==========================================================================
  local function world_n3(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9421, owns = { ACC }, melee = false, dist = 20 } },
      enemies = { { name = "idle_orcs", uid = 9422, melee = false, missile = false } },
