    polln(W, 3)
    local a = (#W.fires == 0)
    check(TAG .. "N3a: the idle-enemy board stays SILENT (" .. fire_detail(W) .. ")", a)
    note94(W, TAG); tally(W)
    return a
  end

  -- ==========================================================================
  -- N4. ENEMY IN MELEE BUT OUT OF RANGE -> SILENT.
