  -- ==========================================================================
  -- N5. THE CONDITION LAPSES between the pick and the cast -> SKIPPED.
  --     The enemy is in melee on the evaluator's read; on the pre-cast re-read
  --     it is NOT (a melee_seq of true then false).
  -- ==========================================================================
  local function world_n5(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9441, owns = { ACC }, melee = false, dist = 20 } },
      enemies = { { name = "orc_boyz", uid = 9442, melee_seq = { true, false } } },
      cards = { { id = "9441", state = "active", vis = true } },
      bar = { { id = "b1", key = ACC } } })
    print("== " .. TAG .. "N5. ACCUSATION: the condition lapses before the cast -> SKIPPED == ")
    if not boot94(W, PATH, TAG, 9441, "accusation", "N5") then return nil end
    polln(W, 1)
    local a = (#W.fires == 0)
    check(TAG .. "N5a: the lapsed target is NOT fired for (" .. fire_detail(W) .. ")", a)
    local b = (count_log(W, "accusation SKIPPED: the chosen enemy lapsed before the cast") == 1)
    check(TAG .. "N5b: the pre-cast lapse skip is reported once [live log]", lg(TAG, b))
    note94(W, TAG); tally(W)
    return a and lg(TAG, b)
  end

  -- ==========================================================================
  -- N6. UNREADABLE is_under_missile_attack -> treated FALSE + ONE-TIME log.
  -- ==========================================================================
  local function world_n6(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9451, owns = { ACC }, melee = false, dist = 20 } },
      enemies = { { name = "orc_boyz", uid = 9452, melee = false, missile_raises = true } },
      cards = { { id = "9451", state = "active", vis = true } },
      bar = { { id = "b1", key = ACC } } })
    print("== " .. TAG .. "N6. ACCUSATION: unreadable is_under_missile_attack -> FALSE + one-time log == ")
    if not boot94(W, PATH, TAG, 9451, "accusation", "N6") then return nil end
    polln(W, 3)
    local a = (#W.fires == 0)
    check(TAG .. "N6a: an unreadable missile read never fires (" .. fire_detail(W) .. ")", a)
    local b = ((W.missile_raise_attempts or 0) >= 1)
    check(TAG .. "N6b: the mock WAS asked is_under_missile_attack (raised " .. (W.missile_raise_attempts or 0) .. ")", b)
    local c = (count_log(W, "is_under_missile_attack read UNAVAILABLE") == 1)
    check(TAG .. "N6c: the unreadable read is reported exactly ONCE [live log]", lg(TAG, c))
    note94(W, TAG); tally(W)
    return a and b and lg(TAG, c)
  end

  -- ==========================================================================
  -- N7. SELF-CAST REGRESSION GUARD: the target is the ENEMY, NEVER the owner.
  -- ==========================================================================
  local function world_n7(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9461, owns = { ACC }, melee = false, in_range = true } },
      enemies = { { name = "chaos_warriors", uid = 9462, melee = true } },
      cards = { { id = "9461", state = "active", vis = true } },
      bar = { { id = "b1", key = ACC } } })
    print("== " .. TAG .. "N7. ACCUSATION: the cast target is NEVER the owner == ")
    if not boot94(W, PATH, TAG, 9461, "accusation", "N7") then return nil end
    polln(W, 1)
    local hunter = unit_of(W, 9461)
    local enemy = enemy_of(W, 9462)
    local a = (#W.fires == 1)
    check(TAG .. "N7a: the hunter fired once (" .. fire_detail(W) .. ")", a)
    local b = (fire_target_for(W, 9461) == enemy)
    check(TAG .. "N7b: the cast target IS the enemy unit", b)
    local c = (fire_target_for(W, 9461) ~= hunter)
    check(TAG .. "N7c: the cast target is NOT the owner (self-cast regression guard)", c)
    note94(W, TAG); tally(W)
    return a and b and c
  end

  -- ==========================================================================
  -- N8. PREFER IN-MELEE over under-fire: a missile enemy and a melee enemy,
  --     both in range -> the MELEE one is chosen.
  -- ==========================================================================
  local function world_n8(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9471, owns = { ACC }, melee = false, in_range = true } },
      enemies = { { name = "goblin_archers", uid = 9472, melee = false, missile = true },
                  { name = "orc_boyz", uid = 9473, melee = true } },
      cards = { { id = "9471", state = "active", vis = true } },
      bar = { { id = "b1", key = ACC } } })
    print("== " .. TAG .. "N8. ACCUSATION: an in-melee enemy is preferred over one under fire == ")
    if not boot94(W, PATH, TAG, 9471, "accusation", "N8") then return nil end
    polln(W, 1)
    local melee_enemy = enemy_of(W, 9473)
    local missile_enemy = enemy_of(W, 9472)
    local a = (#W.fires == 1 and fire_target_for(W, 9471) == melee_enemy)
    check(TAG .. "N8a: the MELEE enemy is chosen, not the closer missile one", a)
    local b = (melee_enemy ~= missile_enemy)
    check(TAG .. "N8b: the two enemies are distinct units", b)
    local c = (count_log(W, "reason: enemy in melee (targeting orc_boyz)") == 1)
    check(TAG .. "N8c: the melee arm's reason is the one logged [live log]", lg(TAG, c))
    note94(W, TAG); tally(W)
    return a and b and lg(TAG, c)
  end

  -- ==========================================================================
  -- N9. AMONG EQUALS PREFER THE CLOSEST: two in-melee enemies; the nearer one
  --     (distance 10 vs 40) is chosen.
  -- ==========================================================================
  local function world_n9(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9481, owns = { ACC }, melee = false, in_range = true,
                  dist_by_target = { [9482] = 40, [9483] = 10 } } },
      enemies = { { name = "far_orcs", uid = 9482, melee = true },
                  { name = "near_orcs", uid = 9483, melee = true } },
      cards = { { id = "9481", state = "active", vis = true } },
      bar = { { id = "b1", key = ACC } } })
    print("== " .. TAG .. "N9. ACCUSATION: among equals the CLOSEST enemy is chosen == ")
    if not boot94(W, PATH, TAG, 9481, "accusation", "N9") then return nil end
    polln(W, 1)
    local near_enemy = enemy_of(W, 9483)
    local far_enemy = enemy_of(W, 9482)
    local a = (#W.fires == 1 and fire_target_for(W, 9481) == near_enemy)
    check(TAG .. "N9a: the CLOSER in-melee enemy is chosen (not the far one)", a)
    local b = (near_enemy ~= far_enemy)
    check(TAG .. "N9b: the two enemies are distinct units", b)
    note94(W, TAG); tally(W)
    return a and b
  end

  -- run each world twice: live and annotated
  local WORLDS = { world_n1, world_n2, world_n3, world_n4, world_n5, world_n6, world_n7, world_n8, world_n9 }
  local results = {}
  for _, path in ipairs({ LIVE, ANN }) do
    local TAG = (path == LIVE) and "[live] " or "[ann]  "
    for _, wfn in ipairs(WORLDS) do
      results[#results + 1] = wfn(path, TAG)
    end
  end
  local n_ok = 0
  for _, r in ipairs(results) do if posv(r) then n_ok = n_ok + 1 end end
  print("== HARNESS 94 - N-worlds: " .. n_ok .. "/" .. #results .. " passed; fires " .. RED94.fires .. " ==")

  check("every ui tick ran clean across the HARNESS-94 worlds (" .. RED94.ui .. " failures)", RED94.ui == 0)

  if not RED_MODE then
    check("HEADLINE (harness 94): ACCUSATION now fires automatically through the FIRST ENEMY-TARGETED trigger "
      .. "`enemy_engaged_or_shot` - an enemy unit within the ability's 70% value 52 m reach is a valid target "
      .. "when it is in melee OR under missile fire (prefer in-melee, then closest); the chosen enemy is the CAST "
      .. "TARGET (never the owner) and the cast uses the round-4-proven bench_fresh fresh-handle route (caster and "
      .. "target re-enumerated the same tick). Accusation's entry moves from melee_unwavering (481 -> 480) to the "
      .. "new trigger (0 -> 1); the table stays 579 entries / 605 keys. All " .. #results .. " worlds passed.",
      n_ok == #results)
  else
    check("RED CONTROL (harness 94): N/A for the harness-95 round - the harness-95 red snapshot (the shipped "
      .. "harness-94 build) already carries the enemy evaluator, so every N-world passes by design: " .. n_ok .. "/"
      .. #results .. " world results pass (want " .. #results .. "), fires "
      .. RED94.fires .. ", claims " .. RED94.claims, n_ok == #results)
  end
end
if not LIGHT then run_h94() end

-- ============================================================================
-- HARNESS 95 - THE STANDING 70% RANGE RULE (this round).
--   The user's rule: EVERY trigger-range constant = AT MOST 70% of the ability's
--   REAL game-data range, rounded DOWN to a whole metre, with NO exceptions
--   ("...No exceptions."). The symptom it removes: the caster WALKING toward a
--   target inside the ability's reach but outside a comfortable cast range.
--   Re-derived (real -> floor(real * 0.70)):
--     GLORIOUS DEATH 55 -> 38 ; VERMINKING 35 -> 24 ; METALLURGY 35 -> 24 ;
--     WAVERING 35 -> 24 ; BLOOD SACRIFICE 100 -> 70 ; EAT DA RUNTS 100 -> 70 ;
--     ACCUSATION 75 -> 52.
--   BOUNDARY WORLDS (each live + annotated): for EACH changed constant, an
--   ALLY/ENEMY just inside the NEW 70% bound FIRES, and a target between 70%
--   and 100% of the REAL range (the movement-prone zone) stays SILENT.
--   RED CONTROL: with H95_LIVE / H95_ANN pointing at the pre-edit snapshot (the
--   shipped harness-94 build: GD 25, VM 25, MT 25, WV 25, BS 25, EDR 25, ACC 75)
--   the 0s tokens and the half of the boundary worlds that sit INSIDE the new
--   bound fail by design (14/28 pass), every earlier pin that moved fails, and
--   every earlier world passes.
-- ============================================================================
function run_h95()
  local GDK = "wh3_dlc25_lord_abilities_glorious_death"
  local VMK = "wh3_dlc29_lord_abilities_will_of_the_verminking"
  local MTK = "wh3_main_character_abilities_enchanted_metallurgy"
  local WUK = "wh3_dlc29_spell_bound_prayer_fury_of_ulric"
  local BSK = "wh3_dlc26_lord_abilities_blood_sacrifice"
  local EDK = "wh3_dlc26_unit_abilities_eat_da_runts"
  local ACK = "wh_main_hero_abilities_accusation"
  local SL_DAEMON = "wh3_dlc25_dwf_cha_daemon_slayer"
  local SL_UNIT   = "wh_main_dwf_inf_slayers"

  local live_src95 = read_file(LIVE)
  local ann_src95  = read_file(ANN)
  local RED95 = { fires = 0, claims = 0, ui = 0 }
  local function posv(v) return (v == true) or (type(v) == "number") end
  local function lg(tag, v) return (tag ~= "[live] ") or posv(v) end
  local function badd95(marker) return "zz_auto_badge_" .. marker end
  local function cp95(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function note95(W, TAG)
    RED95.ui = RED95.ui + (W.ui_failures or 0)
    if TAG == "[live] " then
      RED95.fires = RED95.fires + #W.fires
      RED95.claims = RED95.claims + count_log(W, "claim: ")
    end
  end
  local function boot95(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, badd95(marker)); ui(W)
    W.conflict = true
    return true
  end

  -- --------------------------------------------------- 0s: tokens (both files)
  print("== HARNESS 95 - section 0s: the standing 70% range rule (BOTH files) ==")
  for _, f in ipairs({ { name = "live", src = live_src95 }, { name = "ann", src = ann_src95 } }) do
    local nm, s = f.name, f.src
    check("0s " .. nm .. ": the rule constant FOURTH.RANGE_FRACTION = 0.70 exists",
      raw_find(s, "FOURTH.RANGE_FRACTION = 0.70", 1, true) ~= nil)
    check("0s " .. nm .. ": GLORIOUS DEATH = 38 (55 * 0.70, floored)",
      raw_find(s, "local GLORIOUS_DEATH_RANGE_M = 38", 1, true) ~= nil)
    check("0s " .. nm .. ": the old field-tuned 25 m Glorious Death gate is GONE (no exceptions)",
      raw_find(s, "local GLORIOUS_DEATH_RANGE_M = 25", 1, true) == nil)
    check("0s " .. nm .. ": VERMINKING = 24 (35 * 0.70, floored)",
      raw_find(s, "FOURTH.VERMINKING_RANGE_M = 24", 1, true) ~= nil)
    check("0s " .. nm .. ": METALLURGY = 24 (35 * 0.70, floored)",
      raw_find(s, "FOURTH.METALLURGY_RANGE_M = 24", 1, true) ~= nil)
    check("0s " .. nm .. ": WAVERING = 24 (35 * 0.70, floored)",
      raw_find(s, "FOURTH.WAVERING_RANGE_M = 24", 1, true) ~= nil)
    check("0s " .. nm .. ": BLOOD SACRIFICE = 70 (100 * 0.70)",
      raw_find(s, "FOURTH.BLOOD_SACRIFICE_RANGE_M = 70", 1, true) ~= nil)
    check("0s " .. nm .. ": EAT DA RUNTS = 70 (100 * 0.70)",
      raw_find(s, "FOURTH.EAT_DA_RUNTS_RANGE_M = 70", 1, true) ~= nil)
    check("0s " .. nm .. ": ACCUSATION = 52 (75 * 0.70, floored)",
      raw_find(s, "FOURTH.ACCUSATION_RANGE_M = 52", 1, true) ~= nil)
    check("0s " .. nm .. ": the old ACCUSATION 75 m constant is GONE",
      raw_find(s, "FOURTH.ACCUSATION_RANGE_M = 75", 1, true) == nil)
    check("0s " .. nm .. ": the per-constant comments carry the real range and the 70% derivation",
      raw_find(s, "55 * 0.70 = 38.5 -> 38", 1, true) ~= nil
      and raw_find(s, "35 * 0.70 = 24.5 -> 24", 1, true) ~= nil
      and raw_find(s, "100 * 0.70 = 70.0 -> 70", 1, true) ~= nil
      and raw_find(s, "75 * 0.70 = 52.5 -> 52", 1, true) ~= nil)
    check("0s " .. nm .. ": the charge-window pair is NOT an ability range and is UNCHANGED (12 / 60)",
      raw_find(s, "CHARGE_MIN_DISTANCE_M    = 12", 1, true) ~= nil
      and raw_find(s, "CHARGE_MAX_DISTANCE_M    = 60", 1, true) ~= nil)
    check("0s " .. nm .. ": the ability table is UNCHANGED (688 entries)",
      cp95(s, "\t{ marker = ") == 707)
  end

  -- ---------------------------------------------------------------- the worlds
  -- Each world: a friendly owner that owns the key, the marker's badge ARMED,
  -- and a candidate at a chosen distance. 'expect' = true when the ability
  -- should FIRE, false when it must stay SILENT. Bounds: GD 38 / VM 24 /
  -- MT 24 / WV 24 / BS 70 / EDR 70 / ACC 52.

  -- GLORIOUS DEATH: an in-melee Slayer ALLY at 'dist' m (owner NOT a Slayer-in-melee)
  local function world_gd(PATH, TAG, dist, expect, wname)
    local W = make_world({ can_perform = true, units = {
      { name = SL_DAEMON, uid = 9801, owns = { GDK }, melee = false, wavering = false },
      { name = SL_UNIT,   uid = 9802, owns = {}, melee = true, dist = dist },
    }, cards = {
      { id = "9801", state = "active", vis = true }, { id = "9802", state = "active", vis = true },
    }, bar = { { id = "b1", key = GDK } } })
    print("== " .. TAG .. wname .. ". GLORIOUS DEATH: an in-melee Slayer ally at " .. dist .. " m (bound 38) ==")
    if not boot95(W, PATH, TAG, 9801, "glorious_death", wname) then return nil end
    polln(W, 1)
    local fired = (#W.fires == 1 and W.fires[1].key == GDK)
    check(TAG .. wname .. "a: at " .. dist .. " m the ability " .. (expect and "FIRES" or "stays SILENT")
      .. " (" .. fire_detail(W) .. ")", fired == expect)
    note95(W, TAG); tally(W)
    return (fired == expect)
  end

  -- WILL OF THE VERMINKING: an in-melee WAVERING ally at 'dist' m
  local function world_vm(PATH, TAG, dist, expect, wname)
    local W = make_world({ can_perform = true, units = {
      { name = "skreech",  uid = 9811, owns = { VMK }, melee = false, wavering = false },
      { name = "clanrats", uid = 9812, owns = {}, melee = true, wavering = true, dist = dist },
    }, cards = {
      { id = "9811", state = "active", vis = true }, { id = "9812", state = "active", vis = true },
    }, bar = { { id = "b1", key = VMK } } })
    print("== " .. TAG .. wname .. ". VERMINKING: a wavering in-melee ally at " .. dist .. " m (bound 24) ==")
    if not boot95(W, PATH, TAG, 9811, "will_of_the_verminking", wname) then return nil end
    polln(W, 1)
    local fired = (#W.fires == 1 and W.fires[1].key == VMK)
    check(TAG .. wname .. "a: at " .. dist .. " m the ability " .. (expect and "FIRES" or "stays SILENT")
      .. " (" .. fire_detail(W) .. ")", fired == expect)
    note95(W, TAG); tally(W)
    return (fired == expect)
  end

  -- ENCHANTED METALLURGY: an in-melee ally at 'dist' m (owner NOT in melee)
  local function world_mt(PATH, TAG, dist, expect, wname)
    local W = make_world({ can_perform = true, units = {
      { name = "lord",     uid = 9821, owns = { MTK }, melee = false },
      { name = "infantry", uid = 9822, owns = {}, melee = true, dist = dist },
    }, cards = {
      { id = "9821", state = "active", vis = true }, { id = "9822", state = "active", vis = true },
    }, bar = { { id = "b1", key = MTK } } })
    print("== " .. TAG .. wname .. ". METALLURGY: an in-melee ally at " .. dist .. " m (bound 24) ==")
    if not boot95(W, PATH, TAG, 9821, "enchanted_metallurgy", wname) then return nil end
    polln(W, 1)
    local fired = (#W.fires == 1 and W.fires[1].key == MTK)
    check(TAG .. wname .. "a: at " .. dist .. " m the ability " .. (expect and "FIRES" or "stays SILENT")
      .. " (" .. fire_detail(W) .. ")", fired == expect)
    note95(W, TAG); tally(W)
    return (fired == expect)
  end

  -- WAVERING SELF-OR-ALLY (Fury of Ulric): an in-melee WAVERING ally at 'dist' m
  local function world_wv(PATH, TAG, dist, expect, wname)
    local W = make_world({ can_perform = true, units = {
      { name = "ulric",  uid = 9831, owns = { WUK }, melee = false, wavering = false },
      { name = "broken", uid = 9832, owns = {}, melee = true, wavering = true, dist = dist },
    }, cards = {
      { id = "9831", state = "active", vis = true }, { id = "9832", state = "active", vis = true },
    }, bar = { { id = "b1", key = WUK } } })
    print("== " .. TAG .. wname .. ". WAVERING: an in-melee wavering ally at " .. dist .. " m (bound 24) ==")
    if not boot95(W, PATH, TAG, 9831, "fury_of_ulric", wname) then return nil end
    polln(W, 1)
    local fired = (#W.fires == 1 and W.fires[1].key == WUK)
    check(TAG .. wname .. "a: at " .. dist .. " m the ability " .. (expect and "FIRES" or "stays SILENT")
      .. " (" .. fire_detail(W) .. ")", fired == expect)
    note95(W, TAG); tally(W)
    return (fired == expect)
  end

  -- BLOOD SACRIFICE: a hurt ally (40% health) at 'dist' m
  local function world_bs(PATH, TAG, dist, expect, wname)
    local W = make_world({ can_perform = true, units = {
      { name = "lord", uid = 9841, owns = { BSK }, melee = false, health_percent = 100 },
      { name = "ally", uid = 9842, owns = {}, melee = false, health_percent = 40, dist = dist },
    }, cards = {
      { id = "9841", state = "active", vis = true }, { id = "9842", state = "active", vis = true },
    }, bar = { { id = "b1", key = BSK } } })
    print("== " .. TAG .. wname .. ". BLOOD SACRIFICE: a 40% ally at " .. dist .. " m (bound 70) ==")
    if not boot95(W, PATH, TAG, 9841, "blood_sacrifice", wname) then return nil end
    polln(W, 1)
    local fired = (#W.fires == 1 and W.fires[1].key == BSK)
    check(TAG .. wname .. "a: at " .. dist .. " m the ability " .. (expect and "FIRES" or "stays SILENT")
      .. " (" .. fire_detail(W) .. ")", fired == expect)
    note95(W, TAG); tally(W)
    return (fired == expect)
  end

  -- EAT DA RUNTS!: a hurt ally (50% health) at 'dist' m (owner healthy)
  local function world_ed(PATH, TAG, dist, expect, wname)
    local W = make_world({ can_perform = true, units = {
      { name = "unit", uid = 9851, owns = { EDK }, melee = false, health_percent = 100 },
      { name = "ally", uid = 9852, owns = {}, melee = false, health_percent = 50, dist = dist },
    }, cards = {
      { id = "9851", state = "active", vis = true }, { id = "9852", state = "active", vis = true },
    }, bar = { { id = "b1", key = EDK } } })
    print("== " .. TAG .. wname .. ". EAT DA RUNTS: a 50% ally at " .. dist .. " m (bound 70) ==")
    if not boot95(W, PATH, TAG, 9851, "eat_da_runts", wname) then return nil end
    polln(W, 1)
    local fired = (#W.fires == 1 and W.fires[1].key == EDK)
    check(TAG .. wname .. "a: at " .. dist .. " m the ability " .. (expect and "FIRES" or "stays SILENT")
      .. " (" .. fire_detail(W) .. ")", fired == expect)
    note95(W, TAG); tally(W)
    return (fired == expect)
  end

  -- ACCUSATION: an in-melee ENEMY at 'dist' m (distance fallback; no unit_in_range)
  local function world_acc(PATH, TAG, dist, expect, wname)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9861, owns = { ACK }, melee = false,
                  dist_by_target = { [9862] = dist } } },
      enemies = { { name = "orc_boyz", uid = 9862, melee = true } },
      cards = { { id = "9861", state = "active", vis = true } },
      bar = { { id = "b1", key = ACK } } })
    print("== " .. TAG .. wname .. ". ACCUSATION: an in-melee enemy at " .. dist .. " m (bound 52) ==")
    if not boot95(W, PATH, TAG, 9861, "accusation", wname) then return nil end
    polln(W, 1)
    local fired = (#W.fires == 1 and W.fires[1].key == ACK)
    check(TAG .. wname .. "a: at " .. dist .. " m the ability " .. (expect and "FIRES" or "stays SILENT")
      .. " (" .. fire_detail(W) .. ")", fired == expect)
    note95(W, TAG); tally(W)
    return (fired == expect)
  end

  print()
  print("== HARNESS 95 - the 70% boundary worlds (each live + annotated) ==")
  local res = {}
  local function run_all(fn, dist, expect, wname)
    res[#res + 1] = fn(LIVE, "[live] ", dist, expect, wname)
    res[#res + 1] = fn(ANN,  "[ann]  ", dist, expect, wname)
  end
  run_all(world_gd,  38, true,  "G1")   -- just inside the new 38 m bound -> FIRES
  run_all(world_gd,  45, false, "G2")   -- between 38 and 55 (the movement zone) -> SILENT
  run_all(world_vm,  24, true,  "V1")   -- just inside 24 -> FIRES
  run_all(world_vm,  25, false, "V2")   -- between 24 and 35 -> SILENT
  run_all(world_mt,  24, true,  "M1")
  run_all(world_mt,  25, false, "M2")
  run_all(world_wv,  24, true,  "W1")
  run_all(world_wv,  25, false, "W2")
  run_all(world_bs,  70, true,  "B1")   -- just inside 70 -> FIRES
  run_all(world_bs,  71, false, "B2")   -- between 70 and 100 -> SILENT
  run_all(world_ed,  70, true,  "E1")
  run_all(world_ed,  71, false, "E2")
  run_all(world_acc, 52, true,  "A1")   -- just inside 52 -> FIRES
  run_all(world_acc, 70, false, "A2")   -- between 52 and 75 (the reported WALK zone) -> SILENT

  local n_ok = 0
  for _, r in ipairs(res) do if posv(r) then n_ok = n_ok + 1 end end
  print("== HARNESS 95 - boundary worlds: " .. n_ok .. "/" .. #res .. " passed; fires " .. RED95.fires .. " ==")

  check("every ui tick ran clean across the HARNESS-95 worlds (" .. RED95.ui .. " failures)", RED95.ui == 0)

  if not RED_MODE then
    check("HEADLINE (harness 95): the user's STANDING 70% RANGE RULE ships - EVERY trigger-range constant is "
      .. "floor(0.70 * the ability's REAL game-data range): GLORIOUS DEATH 55->38, VERMINKING 35->24, METALLURGY "
      .. "35->24, WAVERING 35->24, BLOOD SACRIFICE 100->70, EAT DA RUNTS 100->70, ACCUSATION 75->52 - with NO "
      .. "exceptions (the old field-tuned 25 m Glorious Death gate is replaced by 38 m at the user's direction). "
      .. "For each constant an ally/enemy just INSIDE the new bound FIRES and one between 70% and 100% (the "
      .. "movement-prone zone) stays SILENT; all " .. #res .. " boundary worlds passed.",
      n_ok == #res)
  else
    check("RED CONTROL (harness 95): N/A for the harness-96 round - the harness-96 red snapshot (the shipped "
      .. "harness-95 build) already IS the 70% range rule, so every boundary world passes by design: " .. n_ok
      .. "/" .. #res .. " world results pass (want " .. #res .. "), fires "
      .. RED95.fires .. ", claims " .. RED95.claims, n_ok == #res)
  end
end
if not LIGHT then run_h95() end

-- ============================================================================
-- HARNESS 96 - THE ACCUSATION MOVE-ORDER ROOT CAUSE (this round).
--   THE BUG (proven by the passive observer probe zz_probe_dist, tick 59):
--     CAND-FIRST ... dist=81.3m first_passing_test=engine
--         engine_unit_in_range=t our_52_test=f our_75_test=f
--   The Accusation OFFER test consulted the engine's own loose unit_in_range
--   reach read - TRUE at 81.3 m while BOTH of the mod's bounds said FALSE - so
--   the mod offered and cast at a target 81.3 m away and the engine WALKED the
--   caster in (the reported move order). The log label was static ("within
--   52m") and could not show the real distance.
--   THE FIX: the offer test is the 70% CONSTANT ONLY -
--     unit:unit_distance(enemy) <= FOURTH.ACCUSATION_RANGE_M  (52 m)
--   with the engine helper REMOVED from the offer path, and the log prints the
--   REAL edge-to-edge distance (unit:unit_distance, battle_unit.lua:160) at the
--   target choice AND the pre-cast re-check.
--   WORLDS (each live + annotated):
--     R1 (REGRESSION - the exact bug): in_range=TRUE, distance 81.3 m -> the
--        trigger must NOT fire. RED on the pre-edit snapshot (it fires there).
--     R2 inside the bound (48.7 m) -> FIRES.
--     R3 outside the bound (70 m) -> SILENT.
--     R4 the log carries the REAL distance ("distance=48.7m bound=52m") at
--        BOTH the target choice and the pre-cast re-check.
--     R5 the engine flag is FALSE but 40 m (inside) -> the CONSTANT rules, FIRES.
--   RED CONTROL: with H96_LIVE / H96_ANN pointing at the pre-edit snapshot (the
--   shipped harness-95 build, whose offer test trusts unit_in_range) R1 FIRES,
--   R5 stays silent and R4's log lacks the real distance, plus sheet-0t's tokens
--   fail; every earlier world still passes except harness-95's own boundary-count
--   pin (re-based here to the N/A form).
-- ============================================================================
function run_h96()
  local ACK = "wh_main_hero_abilities_accusation"
  local live_src96 = read_file(LIVE)
  local ann_src96  = read_file(ANN)
  local RED96 = { fires = 0, claims = 0, ui = 0 }
  local function posv(v) return (v == true) or (type(v) == "number") end
  local function lg(tag, v) return (tag ~= "[live] ") or posv(v) end
  local function badd96(marker) return "zz_auto_badge_" .. marker end
  local function cp96(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function note96(W, TAG)
    RED96.ui = RED96.ui + (W.ui_failures or 0)
    if TAG == "[live] " then
      RED96.fires = RED96.fires + #W.fires
      RED96.claims = RED96.claims + count_log(W, "claim: ")
    end
  end
  local function boot96(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, badd96(marker)); ui(W)
    W.conflict = true
    return true
  end
  local function enemy_of96(W, uid)
    for i = 1, #(W.enemy_entries or {}) do
      local pr = W.enemy_entries[i]
      if pr ~= nil and pr.unit ~= nil then
        local ok, id = pcall(function() return pr.unit:unique_ui_id() end)
        if ok and tostring(id) == tostring(uid) then return pr.unit end
      end
    end
    return nil
  end

  -- --------------------------------------------------- 0t: tokens (both files)
  print("== HARNESS 96 - section 0t: the move-order fix tokens (BOTH files) ==")
  for _, f in ipairs({ { name = "live", src = live_src96 }, { name = "ann", src = ann_src96 } }) do
    local nm, s = f.name, f.src
    check("0t " .. nm .. ": the offer test uses the constant-only helper (eg_enemy_within_bound)",
      raw_find(s, "function FOURTH.eg_enemy_within_bound(unit, enemy)", 1, true) ~= nil)
    check("0t " .. nm .. ": the offer gate is wired to the constant-only helper",
      raw_find(s, "and FOURTH.eg_enemy_within_bound(unit, enemy) then", 1, true) ~= nil)
    check("0t " .. nm .. ": the engine's unit_in_range CALL is GONE from the file",
      raw_find(s, "unit_in_range(", 1, true) == nil)
    check("0t " .. nm .. ": the old engine-helper function is GONE",
      raw_find(s, "function FOURTH.eg_enemy_in_range(unit, enemy)", 1, true) == nil)
    check("0t " .. nm .. ": the test compares the gap to FOURTH.ACCUSATION_RANGE_M (the 52 m 70% value)",
      raw_find(s, "return gap <= FOURTH.ACCUSATION_RANGE_M", 1, true) ~= nil
      and raw_find(s, "FOURTH.ACCUSATION_RANGE_M = 52", 1, true) ~= nil)
    check("0t " .. nm .. ": the distance primitive is documented (unit:unit_distance + battle_unit.lua:160)",
      raw_find(s, "unit:unit_distance(enemy)", 1, true) ~= nil
      and raw_find(s, "battle_unit.lua:160", 1, true) ~= nil)
    check("0t " .. nm .. ": the whole 688-entry table and the 70% rule are untouched",
      cp96(s, "\t{ marker = ") == 707
      and raw_find(s, "FOURTH.RANGE_FRACTION = 0.70", 1, true) ~= nil)
  end
  check("0t live: the target-choice log prints the REAL distance and the bound",
    raw_find(live_src96, '") distance="', 1, true) ~= nil
    and raw_find(live_src96, '.. "m bound=" .. tostring(bound) .. "m")', 1, true) ~= nil)
  check("0t live: the pre-cast re-check log prints the REAL distance too",
    raw_find(live_src96, '", distance="', 1, true) ~= nil
    and raw_find(live_src96, '.. "m bound=" .. eg_bound_text .. ") - firing")', 1, true) ~= nil
    and raw_find(live_src96, '.. " bound=" .. eg_bound_text .. ") - cast not spent")', 1, true) ~= nil)
  check("0t live: the misleading static 'within 52m' label is GONE",
    raw_find(live_src96, '") within "', 1, true) == nil)
  check("0t ann: the reading copy stays log-free and find-free",
    raw_find(ann_src96, "log(", 1, true) == nil and raw_find(ann_src96, "string.find", 1, true) == nil)

  -- ==========================================================================
  -- R1. THE REGRESSION - the exact probe case: the engine says in-range but the
  --     real distance (81.3 m) EXCEEDS the bound -> the trigger must NOT fire.
  -- ==========================================================================
  local function world_r1(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9891, owns = { ACK }, melee = false,
                  in_range = true, dist = 81.3 } },
      enemies = { { name = "orc_boyz", uid = 9892, melee = true } },
      cards = { { id = "9891", state = "active", vis = true } },
      bar = { { id = "b1", key = ACK } } })
    print("== " .. TAG .. "R1. REGRESSION: unit_in_range=TRUE but the distance 81.3 m EXCEEDS the 52 m bound -> MUST stay SILENT ==")
    if not boot96(W, PATH, TAG, 9891, "accusation", "R1") then return nil end
    polln(W, 3)
    local a = (#W.fires == 0)
    check(TAG .. "R1a: the 81.3 m target is NOT offered even though the engine said in-range (" .. fire_detail(W) .. ")", a)
    local b = (count_log(W, "accusation target:") == 0)
    check(TAG .. "R1b: no target is chosen, so no cast and no walk order [live log]", lg(TAG, b))
    note96(W, TAG); tally(W)
    return a and lg(TAG, b)
  end

  -- ==========================================================================
  -- R2. INSIDE the bound: an in-melee enemy at 48.7 m -> FIRES at that enemy.
  -- ==========================================================================
  local function world_r2(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9901, owns = { ACK }, melee = false, dist = 48.7 } },
      enemies = { { name = "orc_boyz", uid = 9902, melee = true } },
      cards = { { id = "9901", state = "active", vis = true } },
      bar = { { id = "b1", key = ACK } } })
    print("== " .. TAG .. "R2. INSIDE: an in-melee enemy at 48.7 m (inside the 52 m bound) -> FIRES ==")
    if not boot96(W, PATH, TAG, 9901, "accusation", "R2") then return nil end
    polln(W, 1)
    local enemy = enemy_of96(W, 9902)
    local a = (#W.fires == 1 and W.fires[1].key == ACK and fire_target_for(W, 9901) == enemy)
    check(TAG .. "R2a: the 48.7 m enemy is chosen and fired at (" .. fire_detail(W) .. ")", a)
    note96(W, TAG); tally(W)
    return a
  end

  -- ==========================================================================
  -- R3. OUTSIDE the bound: an in-melee enemy at 70 m -> SILENT.
  -- ==========================================================================
  local function world_r3(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9911, owns = { ACK }, melee = false, dist = 70 } },
      enemies = { { name = "orc_boyz", uid = 9912, melee = true } },
      cards = { { id = "9911", state = "active", vis = true } },
      bar = { { id = "b1", key = ACK } } })
    print("== " .. TAG .. "R3. OUTSIDE: an in-melee enemy at 70 m (outside the 52 m bound) -> SILENT ==")
    if not boot96(W, PATH, TAG, 9911, "accusation", "R3") then return nil end
    polln(W, 3)
    local a = (#W.fires == 0)
    check(TAG .. "R3a: the 70 m enemy is NOT offered (" .. fire_detail(W) .. ")", a)
    note96(W, TAG); tally(W)
    return a
  end

  -- ==========================================================================
  -- R4. THE LOG CARRIES THE REAL DISTANCE at the choice AND the re-check.
  -- ==========================================================================
  local function world_r4(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9921, owns = { ACK }, melee = false, dist = 48.7 } },
      enemies = { { name = "orc_boyz", uid = 9922, melee = true } },
      cards = { { id = "9921", state = "active", vis = true } },
      bar = { { id = "b1", key = ACK } } })
    print("== " .. TAG .. "R4. LOG: the real distance (48.7 m) and the bound (52 m) are printed ==")
    if not boot96(W, PATH, TAG, 9921, "accusation", "R4") then return nil end
    polln(W, 1)
    local a = (#W.fires == 1)
    check(TAG .. "R4a: the ability fired (" .. fire_detail(W) .. ")", a)
    local b = (count_log(W, "is the chosen enemy (melee) distance=48.7m bound=52m") == 1)
    check(TAG .. "R4b: the target-choice line names the REAL 48.7 m and the 52 m bound [live log]", lg(TAG, b))
    local c = (count_log(W, "distance=48.7m bound=52m) - firing") == 1)
    check(TAG .. "R4c: the pre-cast re-check line names the REAL 48.7 m too [live log]", lg(TAG, c))
    note96(W, TAG); tally(W)
    return a and lg(TAG, b) and lg(TAG, c)
  end

  -- ==========================================================================
  -- R5. THE ENGINE FLAG IS FALSE but the real distance is INSIDE the bound ->
  --     the CONSTANT rules, so it FIRES (the engine helper is not consulted).
  -- ==========================================================================
  local function world_r5(PATH, TAG)
    local W = make_world({ can_perform = true,
      units = { { name = "witch_hunter", uid = 9931, owns = { ACK }, melee = false,
                  in_range = false, dist = 40 } },
      enemies = { { name = "orc_boyz", uid = 9932, melee = true } },
      cards = { { id = "9931", state = "active", vis = true } },
      bar = { { id = "b1", key = ACK } } })
    print("== " .. TAG .. "R5. ENGINE-FALSE: the flag says out-of-range but 40 m is INSIDE -> the CONSTANT rules, FIRES ==")
    if not boot96(W, PATH, TAG, 9931, "accusation", "R5") then return nil end
    polln(W, 1)
    local a = (#W.fires == 1)
    check(TAG .. "R5a: the 40 m enemy fires on OUR bound, not the engine's flag (" .. fire_detail(W) .. ")", a)
    note96(W, TAG); tally(W)
    return a
  end

  local WORLDS = { world_r1, world_r2, world_r3, world_r4, world_r5 }
  local results = {}
  for _, path in ipairs({ LIVE, ANN }) do
    local TAG = (path == LIVE) and "[live] " or "[ann]  "
    for _, wfn in ipairs(WORLDS) do
      results[#results + 1] = wfn(path, TAG)
    end
  end
  local n_ok = 0
  for _, r in ipairs(results) do if posv(r) then n_ok = n_ok + 1 end end
  print("== HARNESS 96 - move-order worlds: " .. n_ok .. "/" .. #results .. " passed; fires " .. RED96.fires .. " ==")

  check("every ui tick ran clean across the HARNESS-96 worlds (" .. RED96.ui .. " failures)", RED96.ui == 0)

  if not RED_MODE then
    check("HEADLINE (harness 96): the Accusation move-order ROOT CAUSE is fixed - the offer test is the 70% "
      .. "CONSTANT ONLY (unit:unit_distance(enemy) <= FOURTH.ACCUSATION_RANGE_M = 52 m) and NEVER the engine's "
      .. "looser unit_in_range reach read. The probe's tick-59 case (dist=81.3 m, engine in_range=TRUE) is the "
      .. "regression world: it must NOT offer, so the caster can never be walked in. The log now prints the REAL "
      .. "edge-to-edge distance (unit:unit_distance, battle_unit.lua:160) at the target choice AND the pre-cast "
      .. "re-check ('distance=48.7m bound=52m'). All " .. #results .. " worlds passed.", n_ok == #results)
  else
    check("RED CONTROL (harness 96): on the pre-edit snapshot (the shipped harness-95 build, whose offer test "
      .. "trusts the engine's unit_in_range) the regression world R1 FIRES (81.3 m, engine in-range) and R5 stays "
      .. "silent (engine flag false), and R4's live log lacks the real distance - and the section-0t tokens fail. "
      .. "R2/R3 pass by design (the snapshot's distance fallback agrees), plus R4's annotated leg. " .. n_ok .. "/"
      .. #results .. " world results pass (want 5), fires " .. RED96.fires .. ", claims " .. RED96.claims, n_ok == 5)
  end
end
if not LIGHT then run_h96() end

-- ============================================================================
-- HARNESS 97 - THE REST OF CLASS A (this round).
--   THE JOB: apply the PROVEN Accusation enemy-targeting mechanism to the other
--   97 Class-A entries derived from WH3_audit_report.md (98 total; Accusation
--   263 is already done). 88 ride the EXISTING `enemy_engaged_or_shot` trigger
--   (enemy-UNIT casts); 9 ride a NEW `enemy_ground_area` trigger (enemy-GROUND
--   area hexes) that casts through
--   perform_special_ability_ground(key, ENEMY_POSITION, 0, 0).
--   Every entry carries its own REAL target_intercept_range (range_real). ONE
--   named constant per real range (FOURTH.ENEMY_CAST_R<real>) holds the 70%
--   bound = floor(real * FOURTH.RANGE_FRACTION); FOURTH.ENEMY_CAST maps the
--   real range to it and ability.range_m is set at load. The offer test is the
--   per-ability constant ONLY (unit:unit_distance(enemy) <= bound) - NEVER the
--   engine's unit_in_range. The marker-prefixed log prints the REAL distance.
--   This harness proves, against the LIVE source and the ANNOTATED copy:
--     0u: the 12 named constants, the FOURTH.ENEMY_CAST map, the range_real
--         fields (98), the load-loop wiring, the picker, the ground evaluator/
--         helper/key-set, the moved trigger counts, the poll slots, and that
--         unit_in_range( is still GONE;
--     per-family worlds (12 real-range families): an enemy INSIDE the bound and
--         in melee FIRES AT THE ENEMY (unit form) or casts on the ENEMY's GROUND
--         (ground form); an enemy BEYOND the bound stays SILENT even though the
--         engine's own helper says in-range (THE REGRESSION GUARD);
--     plus: an enemy under missile fire FIRES; a lapse between pick and cast
--         SKIPS; the self-cast guard (target is NEVER the owner); the fresh-
--         handle guard (the caster is re-fetched the same tick).
--   RED CONTROL: with H97_LIVE / H97_ANN pointing at the pre-edit snapshot (the
--   shipped harness-96 build: all 97 still melee_unwavering self-cast, no
--   picker, no ground form) the 0u tokens fail and every INSIDE/missile/ground
--   world fires nothing; the BEYOND worlds pass by design (nothing fires).
-- ============================================================================
function run_h97()
  local live_src97 = read_file(LIVE)
  local ann_src97  = read_file(ANN)
  local RED97 = { fires = 0, claims = 0, ui = 0 }
  local function posv(v) return (v == true) or (type(v) == "number") end
  local function lg(tag, v) return (tag ~= "[live] ") or posv(v) end
  local function badd97(marker) return "zz_auto_badge_" .. marker end
  local function cp97(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function note97(W, TAG)
    RED97.ui = RED97.ui + (W.ui_failures or 0)
    if TAG == "[live] " then
      RED97.fires = RED97.fires + #W.fires
      RED97.claims = RED97.claims + count_log(W, "claim: ")
    end
  end
  local function boot97(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, badd97(marker)); ui(W)
    W.conflict = true
    return true
  end
  local function enemy_of97(W, uid)
    for i = 1, #(W.enemy_entries or {}) do
      local pr = W.enemy_entries[i]
      if pr ~= nil and pr.unit ~= nil then
        local ok, id = pcall(function() return pr.unit:unique_ui_id() end)
        if ok and tostring(id) == tostring(uid) then return pr.unit end
      end
    end
    return nil
  end

  -- THE 12 REAL-RANGE FAMILIES: one representative ability apiece (unit form
  -- where the family has one, else the ground form).
  -- ROUND 101: the real=30 representative is dispatch_the_swarm_attack
  -- (Bitter Sting was REMOVED - a boss-only entry).
  local FAM = {
    { real = 20,  bound = 14,  marker = "sadistic_snare", key = "wh3_dlc23_lord_abilities_sadistic_snare", ground = false },
    { real = 30,  bound = 21,  marker = "dispatch_the_swarm_attack", key = "wh3_dlc29_hero_active_dispatch_the_swarm_attack", ground = false },
    { real = 35,  bound = 24,  marker = "sword_of_filth", key = "wh3_dlc25_weapon_abilities_sword_of_filth", ground = false },
    { real = 50,  bound = 35,  marker = "frost_shard_glaive", key = "wh3_main_weapon_abilities_frost_shard_glaive", ground = false },
    { real = 70,  bound = 49,  marker = "oil_flask", key = "wh2_dlc13_lord_abilities_oil_flask", ground = false },
    { real = 75,  bound = 52,  marker = "accusation", key = "wh_main_hero_abilities_accusation", ground = false },
    { real = 100, bound = 70,  marker = "blade_of_setep", key = "wh2_dlc09_weapon_abilities_blade_of_setep", ground = false },
    { real = 150, bound = 105, marker = "headhunt", key = "wh3_dlc26_character_abilities_headhunt", ground = false },
    { real = 180, bound = 126, marker = "mark_of_yin", key = "wh3_dlc24_unit_abilities_mark_of_yin", ground = false },
    { real = 200, bound = 140, marker = "acquiescence", key = "wh3_dlc27_spell_bound_acquiescence", ground = false },
    { real = 15,  bound = 10,  marker = "entangle", key = "wh2_dlc10_character_abilities_entangle", ground = true },
    { real = 500, bound = 350, marker = "tricksters_shard", key = "wh_main_item_abilities_tricksters_shard", ground = true },
  }

  -- --------------------------------------------------- 0u: tokens (both files)
  print("== HARNESS 97 - section 0u: the Class-A enemy batch tokens (BOTH files) ==")
  local CONSTS = { {"FOURTH.ENEMY_CAST_R15  = 10", "15", "10"}, {"FOURTH.ENEMY_CAST_R20  = 14", "20", "14"},
    {"FOURTH.ENEMY_CAST_R30  = 21", "30", "21"}, {"FOURTH.ENEMY_CAST_R35  = 24", "35", "24"},
    {"FOURTH.ENEMY_CAST_R50  = 35", "50", "35"}, {"FOURTH.ENEMY_CAST_R70  = 49", "70", "49"},
    {"FOURTH.ENEMY_CAST_R75  = 52", "75", "52"}, {"FOURTH.ENEMY_CAST_R100 = 70", "100", "70"},
    {"FOURTH.ENEMY_CAST_R150 = 105", "150", "105"}, {"FOURTH.ENEMY_CAST_R180 = 126", "180", "126"},
    {"FOURTH.ENEMY_CAST_R200 = 140", "200", "140"}, {"FOURTH.ENEMY_CAST_R500 = 350", "500", "350"} }
  for _, f in ipairs({ { name = "live", src = live_src97 }, { name = "ann", src = ann_src97 } }) do
    local nm, s = f.name, f.src
    local allc = true
    for i = 1, #CONSTS do
      if raw_find(s, CONSTS[i][1], 1, true) == nil then allc = false end
    end
    check("0u " .. nm .. ": all 12 named 70% enemy-cast constants are present with their values", allc)
    check("0u " .. nm .. ": the REAL-range -> bound map (FOURTH.ENEMY_CAST) exists",
      raw_find(s, "FOURTH.ENEMY_CAST = {", 1, true) ~= nil)
    check("0u " .. nm .. ": every Class-A entry carries its REAL range (range_real x205)",
      cp97(s, "\t\trange_real = ") == 207)
    check("0u " .. nm .. ": the load loop maps the real range to the named constant",
      raw_find(s, "ability.range_m = FOURTH.ENEMY_CAST[ability.range_real]", 1, true) ~= nil)
    check("0u " .. nm .. ": the shared enemy picker and the fresh-caster route exist",
      raw_find(s, "function FOURTH.eg_pick_enemy(unit, routing, ground)", 1, true) ~= nil
      and raw_find(s, "function FOURTH.eg_fresh_caster_su(unit)", 1, true) ~= nil
      and raw_find(s, "FOURTH.eg_caster_su = FOURTH.eg_fresh_caster_su(unit)", 1, true) ~= nil
      and raw_find(s, "uc = FOURTH.eg_caster_su.uc", 1, true) ~= nil)
    check("0u " .. nm .. ": the per-ability bound is read from FOURTH.eg_range_m",
      raw_find(s, "local bound = FOURTH.eg_range_m", 1, true) ~= nil
      and raw_find(s, "return gap <= bound", 1, true) ~= nil)
    check("0u " .. nm .. ": the enemy-ground evaluator/helper/key-set exist and are wired",
      raw_find(s, "function FOURTH.evaluate_enemy_ground_area(unit, routing)", 1, true) ~= nil
      and raw_find(s, "function FOURTH.enemy_ground_cast(uc, enemy, ability_key)", 1, true) ~= nil
      and raw_find(s, "enemy_ground_area = FOURTH.evaluate_enemy_ground_area,", 1, true) ~= nil
      and raw_find(s, "enemy_ground_keys = {", 1, true) ~= nil)
    check("0u " .. nm .. ": the 9 enemy-ground keys are registered",
      cp97(s, '["wh2_dlc09_item_abilities_amulet_of_phastah"] = true,') == 1
      and cp97(s, '["wh_dlc03_item_abilities_chalice_of_dark_rain"] = true,') == 1
      and cp97(s, '["wh2_dlc09_character_abilities_curse_of_khsar"] = true,') == 1
      and cp97(s, '["wh2_dlc10_character_abilities_entangle"] = true,') == 1
      and cp97(s, '["wh3_dlc25_character_abilities_get_em"] = true,') == 1
      and cp97(s, '["wh2_dlc13_lord_abilities_hunters_snare"] = true,') == 1
      and cp97(s, '["wh2_dlc13_lord_abilities_hunters_trap"] = true,') == 1
      and cp97(s, '["wh2_main_item_abilities_the_tricksters_pendant"] = true,') == 1
      and cp97(s, '["wh_main_item_abilities_tricksters_shard"] = true,') == 1)
    check("0u " .. nm .. ": the trigger counts moved (melee_unwavering 360, enemy_engaged_or_shot 86, enemy_ground_area 9)",
      cp97(s, 'trigger = "melee_unwavering"') == 374
      and cp97(s, 'trigger = "enemy_engaged_or_shot"') == 85
      and cp97(s, 'trigger = "enemy_ground_area"') == 9
      and cp97(s, 'trigger = "enemy_ground_melee"') == 67)
    check("0u " .. nm .. ": the table stays 688 entries / 688 badges",
      cp97(s, "\t{ marker = ") == 707 and cp97(s, 'badge = "') == 707)
    check("0u " .. nm .. ": the poll sets the current ability's bound + marker",
      raw_find(s, "FOURTH.eg_range_m = ability.range_m", 1, true) ~= nil
      and raw_find(s, "FOURTH.eg_marker = ability.marker", 1, true) ~= nil)
    check("0u " .. nm .. ": the engine's unit_in_range CALL is still GONE",
      raw_find(s, "unit_in_range(", 1, true) == nil)
    check("0u " .. nm .. ": the 70% rule is untouched",
      raw_find(s, "FOURTH.RANGE_FRACTION = 0.70", 1, true) ~= nil)
  end
  check("0u live: the picker's target-choice log is marker-prefixed and prints the REAL distance + bound",
    raw_find(live_src97, 'log("  " .. marker .. " target: \'"', 1, true) ~= nil
    and raw_find(live_src97, '.. "m bound=" .. tostring(bound) .. "m")', 1, true) ~= nil)
  check("0u live: the pre-cast re-check is marker-prefixed and prints the REAL distance + bound",
    raw_find(live_src97, 'log("  " .. eg_marker_now .. " pre-cast re-check:', 1, true) ~= nil
    and raw_find(live_src97, '.. "m bound=" .. eg_bound_text .. ") - firing")', 1, true) ~= nil)
  check("0u live: the enemy-ground cast branch is present and logged",
    raw_find(live_src97, 'enemy-ground cast      : perform_special_ability_ground', 1, true) ~= nil
    and raw_find(live_src97, "FOURTH.enemy_ground_cast(uc, FOURTH.eg_enemy, ability_key)", 1, true) ~= nil)
  check("0u live: the distinct unit/ground reason strings are present",
    raw_find(live_src97, 'reason = "enemy in melee (targeting " .. etype .. ")"', 1, true) ~= nil
    and raw_find(live_src97, 'reason = "enemy-ground area in melee (targeting " .. etype .. ")"', 1, true) ~= nil)
  check("0u ann: the reading copy stays log-free and find-free",
    raw_find(ann_src97, "log(", 1, true) == nil and raw_find(ann_src97, "string.find", 1, true) == nil)

  -- ==========================================================================
  -- THE PER-FAMILY WORLDS: INSIDE (fires at the enemy) / BEYOND (silent, the
  -- regression guard: the engine's own helper says in-range).
  -- ==========================================================================
  local function world_family(FAM_, PATH, TAG, mode)
    local mid = 9700 + (FAM_.real % 90) + (mode == "inside" and 0 or 40)
    local uid, euid = mid, mid + 200
    local inside = (mode == "inside")
    local dist = inside and (FAM_.bound - 5) or (FAM_.bound + 25)
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { FAM_.key }, melee = false,
                  in_range = true, dist = dist } },
      enemies = { { name = "orc_boyz", uid = euid, melee = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = FAM_.key } } })
    local wname = string.format("%s r%d/%d b%d", (inside and "INSIDE" or "BEYOND"), FAM_.real, FAM_.real, FAM_.bound)
    print("== " .. TAG .. "FAM " .. wname .. " (" .. FAM_.marker .. ", " .. (FAM_.ground and "ground" or "unit") .. ", dist " .. dist .. " m) ==")
    if not boot97(W, PATH, TAG, uid, FAM_.marker, "FAM " .. wname .. " ") then return nil end
    polln(W, 3)
    local enemy = enemy_of97(W, euid)
    if FAM_.ground then
      if inside then
        local a = (#W.ground_fires == 1 and W.ground_fires[1].key == FAM_.key)
        check(TAG .. "FAM " .. wname .. ": the enemy-ground cast fired the key (" .. #W.ground_fires .. " ground fires)", a)
        local b = (W.ground_fires[1] ~= nil and W.ground_fires[1].pos ~= nil
          and W.ground_fires[1].pos.marker == ("pos:" .. tostring(euid)))
        check(TAG .. "FAM " .. wname .. ": the area was placed on the ENEMY's ground (pos marker " .. tostring(W.ground_fires[1] and W.ground_fires[1].pos and W.ground_fires[1].pos.marker) .. ")", b)
        local c = (W.fires ~= nil and #W.fires == 0)
        check(TAG .. "FAM " .. wname .. ": the unit form was NOT used for the enemy-ground hex", c)
        note97(W, TAG); tally(W)
        return a and b and c
      else
        local a = (#W.ground_fires == 0 and #W.fires == 0)
        check(TAG .. "FAM " .. wname .. ": beyond the bound stays SILENT though the engine said in-range (ground fires " .. #W.ground_fires .. ", unit fires " .. #W.fires .. ")", a)
        note97(W, TAG); tally(W)
        return a
      end
    else
      if inside then
        local a = (#W.fires == 1 and W.fires[1].key == FAM_.key and fire_target_for(W, uid) == enemy)
        check(TAG .. "FAM " .. wname .. ": the in-bound in-melee enemy is fired at (" .. fire_detail(W) .. ")", a)
        local b = (fire_target_for(W, uid) ~= unit_of(W, uid))
        check(TAG .. "FAM " .. wname .. ": the cast target is NOT the owner (self-cast guard)", b)
        note97(W, TAG); tally(W)
        return a and b
      else
        local a = (#W.fires == 0)
        check(TAG .. "FAM " .. wname .. ": beyond the bound stays SILENT though the engine said in-range (" .. fire_detail(W) .. ")", a)
        note97(W, TAG); tally(W)
        return a
      end
    end
  end

  local results = {}
  for _, path in ipairs({ LIVE, ANN }) do
    local TAG = (path == LIVE) and "[live] " or "[ann]  "
    for i = 1, #FAM do
      results[#results + 1] = world_family(FAM[i], path, TAG, "inside")
      results[#results + 1] = world_family(FAM[i], path, TAG, "beyond")
    end
  end

  -- ==========================================================================
  -- MISSILE: an enemy under missile fire (not in melee) inside the bound FIRES.
  -- ==========================================================================
  local function world_missile(PATH, TAG)
    local KEY = "wh2_dlc09_weapon_abilities_blade_of_setep"  -- bound 70
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = 9801, owns = { KEY }, melee = false, dist = 60 } },
      enemies = { { name = "goblin_archers", uid = 9802, melee = false, missile = true } },
      cards = { { id = "9801", state = "active", vis = true } },
      bar = { { id = "b1", key = KEY } } })
    print("== " .. TAG .. "MISSILE: an enemy under missile fire inside the bound FIRES ==")
    if not boot97(W, PATH, TAG, 9801, "blade_of_setep", "MISSILE ") then return nil end
    polln(W, 1)
    local enemy = enemy_of97(W, 9802)
    local a = (#W.fires == 1 and fire_target_for(W, 9801) == enemy)
    check(TAG .. "MISSILE: the under-fire enemy at 60 m (bound 70) is fired at (" .. fire_detail(W) .. ")", a)
    note97(W, TAG); tally(W)
    return a
  end

  -- ==========================================================================
  -- LAPSE: the condition lapses between the pick and the cast -> SKIP.
  -- ==========================================================================
  local function world_lapse(PATH, TAG)
    local KEY = "wh2_dlc09_weapon_abilities_blade_of_setep"
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = 9811, owns = { KEY }, melee = false, dist = 60 } },
      enemies = { { name = "orc_boyz", uid = 9812, melee_seq = { true, false } } },
      cards = { { id = "9811", state = "active", vis = true } },
      bar = { { id = "b1", key = KEY } } })
    print("== " .. TAG .. "LAPSE: the chosen enemy lapses before the cast -> SKIPPED ==")
    if not boot97(W, PATH, TAG, 9811, "blade_of_setep", "LAPSE ") then return nil end
    polln(W, 1)
    local a = (#W.fires == 0)
    check(TAG .. "LAPSE: the lapsed target is NOT fired for (" .. fire_detail(W) .. ")", a)
    local b = (count_log(W, "SKIPPED: the chosen enemy lapsed before the cast") == 1)
    check(TAG .. "LAPSE: the pre-cast lapse skip is reported once [live log]", lg(TAG, b))
    note97(W, TAG); tally(W)
    return a and lg(TAG, b)
  end

  -- ==========================================================================
  -- FRESH-HANDLE GUARD: the caster is re-fetched the SAME tick (a controller
  -- held from an earlier poll silently no-ops - this is the proof it does not).
  -- ==========================================================================
  local function world_fresh(PATH, TAG)
    local KEY = "wh3_dlc26_character_abilities_headhunt"  -- bound 105
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = 9821, owns = { KEY }, melee = false, dist = 90 } },
      enemies = { { name = "orc_boyz", uid = 9822, melee = true } },
      cards = { { id = "9821", state = "active", vis = true } },
      bar = { { id = "b1", key = KEY } } })
    print("== " .. TAG .. "FRESH: the caster is re-fetched FRESH on the firing tick ==")
    if not boot97(W, PATH, TAG, 9821, "headhunt", "FRESH ") then return nil end
    local friendly0 = W.friendly_calls or 0
    polln(W, 1)
    local a = (#W.fires == 1)
    check(TAG .. "FRESH: the in-bound in-melee enemy is fired at (" .. fire_detail(W) .. ")", a)
    local b = ((W.friendly_calls or 0) > friendly0)
    check(TAG .. "FRESH: the CASTER was re-fetched on the firing tick (fresh/not-stale handle)", b)
    note97(W, TAG); tally(W)
    return a and b
  end

  results[#results + 1] = world_missile(LIVE, "[live] "); results[#results + 1] = world_missile(ANN, "[ann]  ")
  results[#results + 1] = world_lapse(LIVE, "[live] ");   results[#results + 1] = world_lapse(ANN, "[ann]  ")
  results[#results + 1] = world_fresh(LIVE, "[live] ");   results[#results + 1] = world_fresh(ANN, "[ann]  ")

  local n_ok = 0
  for _, r in ipairs(results) do if posv(r) then n_ok = n_ok + 1 end end
  print("== HARNESS 97 - Class-A family/guard worlds: " .. n_ok .. "/" .. #results .. " passed; fires " .. RED97.fires .. " ==")

  check("every ui tick ran clean across the HARNESS-97 worlds (" .. RED97.ui .. " failures)", RED97.ui == 0)

  if not RED_MODE then
    check("HEADLINE (harness 97): THE REST OF CLASS A ships on the proven Accusation enemy-targeting mechanism - 97 of the "
      .. "98 enemy-aimed entries (Accusation 263 already done) now fire at the ENEMY: 88 ride enemy_engaged_or_shot "
      .. "and 9 ride the new enemy_ground_area (perform_special_ability_ground on the chosen ENEMY's ground). Each entry "
      .. "carries its own REAL target_intercept_range -> ONE named 70% constant per real range (12 constants, "
      .. "floor(real*0.70)); the offer test is unit:unit_distance(enemy) <= that constant ONLY (never the engine's "
      .. "unit_in_range). The marker-prefixed log prints the REAL distance; the fresh-handle route, the pre-cast "
      .. "re-check and the hold are the Accusation ones. All " .. #results .. " worlds passed.", n_ok == #results)
  else
    check("RED CONTROL (harness 97): on the pre-edit snapshot (the shipped harness-96 build: all 97 still "
      .. "melee_unwavering self-cast, no picker, no ground form) the section-0u tokens fail and every non-accusation "
      .. "INSIDE/missile/ground world fires nothing; the 24 BEYOND worlds pass by design and the ACCUSATION family "
      .. "passes (it is already enemy-targeted on the snapshot). " .. n_ok .. "/" .. #results
      .. " world results pass (want 27), fires " .. RED97.fires .. ", claims " .. RED97.claims, n_ok == 27)
  end
end
if not LIGHT then run_h97() end

-- ============================================================================
-- HARNESS 98 - CLASS B (ally-targeted effects cast on self).
--   THE JOB: implement the audit's Class B (34 entries) on the mod's OWN ally
--   picker (the blood_sacrifice / eat_da_runts shape) with the Class-A round's
--   FRESH-HANDLE discipline. 17 entries move to one of FOUR new ally families;
--   1 (Stay Here, I'll Get Help!) had its ally pick already and only gains the
--   CAST TARGET + its own 70% bound; 1 is an ARMY-BAR ability (Meat Feast,
--   standing rule 10) and is SKIPPED; 15 need a user ruling and are unchanged.
--   Every implemented entry carries its own REAL target_intercept_range
--   (ally_range_real) -> ONE named 70% constant per real range (FOURTH.ALLY_CAST).
--   The offer test is the per-ability constant ONLY (unit:unit_distance(ally)) -
--   NEVER the engine's unit_in_range. The cast goes through the FRESH caster
--   controller AND the FRESH ally unit, re-enumerated the SAME tick.
--   This harness proves, against the LIVE source and the ANNOTATED copy:
--     0v: the 5 named constants, the FOURTH.ALLY_CAST map, the 18 ally_range_real
--         fields, the load-loop wiring, the fresh-friend helper, the shared ally
--         picker, the four family evaluators, the fresh-handle cast branch, the
--         poll slots, the moved trigger counts, and that unit_in_range( is GONE;
--     worlds: an ally in range qualifies and the cast TARGETS THAT ALLY (never
--         the owner); no qualifying ally -> SILENT; an ally BEYOND the bound stays
--         SILENT though the engine's own helper says in-range; a heal entry fires
--         on the health trigger AND picks the LOWEST-health ally; a melee+health
--         heal needs the owner in melee; a wavering family world; two LAPSE worlds
--         (pick->cast drift; pick->cast death) both SKIP; the fresh-handle proof.
--   RED CONTROL: with H98_LIVE / H98_ANN pointing at the pre-edit snapshot (the
--   shipped harness-97 build: no ally triggers at all) the 0v tokens fail and
--   every FIRE world fires nothing; the SILENT worlds pass by design.
-- ============================================================================
function run_h98()
  local live_src98 = read_file(LIVE)
  local ann_src98  = read_file(ANN)
  local RED98 = { fires = 0, claims = 0, ui = 0 }
  -- the RED-control expected pass count (the SILENT worlds whose snapshot
  -- trigger does not fire); verified by the red run below.
  local WANT_RED_98 = 13
  local function posv(v) return (v == true) or (type(v) == "number") end
  local function lg(tag, v) return (tag ~= "[live] ") or posv(v) end
  local function cp98(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function note98(W, TAG)
    RED98.ui = RED98.ui + (W.ui_failures or 0)
    if TAG == "[live] " then
      RED98.fires = RED98.fires + #W.fires
      RED98.claims = RED98.claims + count_log(W, "claim: ")
    end
  end
  local function boot98(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, "zz_auto_badge_" .. marker); ui(W)
    W.conflict = true
    return true
  end
  local function ally_of98(W, uid)
    for i = 1, #(W.live_entries or {}) do
      local pr = W.live_entries[i]
      if pr ~= nil and pr.unit ~= nil then
        local ok, id = pcall(function() return pr.unit:unique_ui_id() end)
        if ok and tostring(id) == tostring(uid) then return pr.unit end
      end
    end
    return nil
  end

  -- --------------------------------------------------- 0v: tokens (both files)
  print("== HARNESS 98 - section 0v: the Class-B ally-targeted tokens (BOTH files) ==")
  local CONSTS = { { "FOURTH.ALLY_CAST_R50  = 35", 50, 35 }, { "FOURTH.ALLY_CAST_R60  = 42", 60, 42 },
                   { "FOURTH.ALLY_CAST_R75  = 52", 75, 52 }, { "FOURTH.ALLY_CAST_R100 = 70", 100, 70 },
                   { "FOURTH.ALLY_CAST_R150 = 105", 150, 105 } }
  for _, f in ipairs({ { name = "live", src = live_src98 }, { name = "ann", src = ann_src98 } }) do
    local nm, s = f.name, f.src
    local allc = true
    for i = 1, #CONSTS do
      if math.floor(CONSTS[i][2] * 0.70 + 1e-9) ~= CONSTS[i][3] then allc = false end
      if raw_find(s, CONSTS[i][1], 1, true) == nil then allc = false end
    end
    check("0v " .. nm .. ": all 5 named 70% ally-cast constants are present with their values", allc)
    check("0v " .. nm .. ": the REAL-range -> ally-bound map (FOURTH.ALLY_CAST) exists",
      raw_find(s, "FOURTH.ALLY_CAST = {", 1, true) ~= nil)
    check("0v " .. nm .. ": every Class-B AND ally-aware entry carries its REAL ally range (harness 104: 32 + 9 = 41)",
      cp98(s, "\t\tally_range_real = ") == 41)
    check("0v " .. nm .. ": the load loop maps the ally real range to the named constant",
      raw_find(s, "ability.range_m = FOURTH.ALLY_CAST[ability.ally_range_real]", 1, true) ~= nil)
    check("0v " .. nm .. ": the fresh-friend helper + the shared ally picker exist",
      raw_find(s, "function FOURTH.ab_fresh_friend_su(unit)", 1, true) ~= nil
      and raw_find(s, "function FOURTH.ab_pick_ally(unit, routing, family)", 1, true) ~= nil
      and raw_find(s, "function FOURTH.ab_ally_valid(unit, ally)", 1, true) ~= nil
      and raw_find(s, "FOURTH.ab_caster_su = FOURTH.ab_fresh_friend_su(unit)", 1, true) ~= nil
      and raw_find(s, "FOURTH.ab_ally_su = FOURTH.ab_fresh_friend_su(best_ally)", 1, true) ~= nil)
    check("0v " .. nm .. ": the four family evaluators exist and are wired",
      raw_find(s, "function FOURTH.evaluate_ally_heal(unit, routing)", 1, true) ~= nil
      and raw_find(s, "function FOURTH.evaluate_ally_heal_melee(unit, routing)", 1, true) ~= nil
      and raw_find(s, "function FOURTH.evaluate_ally_wavering(unit, routing)", 1, true) ~= nil
      and raw_find(s, "function FOURTH.evaluate_ally_melee_buff(unit, routing)", 1, true) ~= nil
      and raw_find(s, "ally_heal = FOURTH.evaluate_ally_heal,", 1, true) ~= nil
      and raw_find(s, "ally_heal_melee = FOURTH.evaluate_ally_heal_melee,", 1, true) ~= nil
      and raw_find(s, "ally_wavering = FOURTH.evaluate_ally_wavering,", 1, true) ~= nil
      and raw_find(s, "ally_melee_buff = FOURTH.evaluate_ally_melee_buff,", 1, true) ~= nil)
    check("0v " .. nm .. ": the FRESH-HANDLE cast branch is present (caster + ally re-fetched the same tick)",
      raw_find(s, "uc = FOURTH.ab_caster_su.uc", 1, true) ~= nil
      and raw_find(s, "target = FOURTH.ab_ally_su.unit", 1, true) ~= nil
      and raw_find(s, "if FOURTH.ab_ally ~= nil then", 1, true) ~= nil)
    check("0v " .. nm .. ": the per-ability ally bound is read from FOURTH.ab_range_m, never unit_in_range",
      raw_find(s, "local bound = FOURTH.ab_range_m", 1, true) ~= nil
      and raw_find(s, "FOURTH.ab_gap_ok", 1, true) ~= nil
      and raw_find(s, "unit_in_range(", 1, true) == nil)
    check("0v " .. nm .. ": the poll clears the ally slots and sets THIS ability's bound + marker",
      raw_find(s, "FOURTH.ab_ally = nil", 1, true) ~= nil
      and raw_find(s, "FOURTH.ab_range_m = ability.range_m", 1, true) ~= nil
      and raw_find(s, "FOURTH.ab_marker = ability.marker", 1, true) ~= nil)
    check("0v " .. nm .. ": the trigger counts (harness 104: ushoran_health 20 + 13 ally-aware, others unchanged)",
      cp98(s, 'trigger = "melee_unwavering"') == 374
      and cp98(s, 'trigger = "charge_or_melee"') == 28
      and cp98(s, 'trigger = "ushoran_health"') == 20
      and cp98(s, 'trigger = "health_aura_ground"') == 2 and cp98(s, 'trigger = "health_aura_ally"') == 9
      and cp98(s, 'trigger = "health_aura_self"') == 2
      and cp98(s, 'trigger = "melee_health75"') == 1)
    check("0v " .. nm .. ": the four ally triggers are wired (14 buff / 3 heal / 1 heal_melee / 2 wavering)",
      cp98(s, 'trigger = "ally_melee_buff"') == 14
      and cp98(s, 'trigger = "ally_heal"') == 3
      and cp98(s, 'trigger = "ally_heal_melee"') == 1
      and cp98(s, 'trigger = "ally_wavering"') == 2)
    check("0v " .. nm .. ": the table stays 688 entries / 688 badges",
      cp98(s, "\t{ marker = ") == 707 and cp98(s, 'badge = "') == 707)
    check("0v " .. nm .. ": the 70% rule is untouched and the engine unit_in_range CALL is still GONE",
      raw_find(s, "FOURTH.RANGE_FRACTION = 0.70", 1, true) ~= nil)
  end
  check("0v live: the picker's chosen-ally log prints the REAL distance + bound",
    raw_find(live_src98, " is the chosen ally (", 1, true) ~= nil
    and raw_find(live_src98, '.. "m bound=" .. FOURTH.ab_bound_text())', 1, true) ~= nil)
  check("0v live: the pre-cast ally re-check prints the REAL distance + bound",
    raw_find(live_src98, " pre-cast re-check: the chosen ally is still valid (", 1, true) ~= nil
    and raw_find(live_src98, "SKIPPED: the chosen ally lapsed before the cast", 1, true) ~= nil)
  check("0v ann: the reading copy stays log-free and find-free",
    raw_find(ann_src98, "log(", 1, true) == nil and raw_find(ann_src98, "string.find", 1, true) == nil)

  -- ==========================================================================
  -- THE ALLY WORLDS. One generic builder: a caster (+ an optional ally) and an
  -- expectation of fire-on-the-ally / silence.
  -- ==========================================================================
  local function world_ab(PATH, TAG, o)
    local units = { { name = o.cname or "caster", uid = o.cuid, owns = { o.key },
                      melee = o.cmelee, wavering = o.cwavering, health_percent = o.chp } }
    if o.auid ~= nil then
      units[#units + 1] = { name = o.aname or "ally", uid = o.auid, owns = {},
                            melee = o.amelee, wavering = o.awavering,
                            health_percent = o.ahp, dist = o.adist, dist_seq = o.adist_seq,
                            men_alive = o.amen, men_die_tick = o.amen_die_tick,
                            in_range = true }
    end
    local cards = { { id = tostring(o.cuid), state = "active", vis = true } }
    if o.auid ~= nil then cards[#cards + 1] = { id = tostring(o.auid), state = "active", vis = true } end
    local W = make_world({ can_perform = true, units = units, cards = cards,
                           bar = { { id = "b1", key = o.key } } })
    print("== " .. TAG .. o.wname .. " ==")
    if not boot98(W, PATH, TAG, o.cuid, o.marker, o.wname) then return nil end
    local f0 = W.friendly_calls or 0
    polln(W, 1)
    local owner = unit_of(W, o.cuid)
    local ally = (o.auid ~= nil) and ally_of98(W, o.auid) or nil
    if o.expect == "fire_ally" then
      local a = (#W.fires == 1 and W.fires[1].key == o.key and ally ~= nil
        and fire_target_for(W, o.cuid) == ally)
      check(TAG .. o.wname .. ": fires ONCE and the cast target IS THE ALLY (" .. fire_detail(W) .. ")", a)
      local b = (#W.fires == 1 and owner ~= nil and fire_target_for(W, o.cuid) ~= owner)
      check(TAG .. o.wname .. ": the cast target is NOT the owner (self-cast guard)", b)
      local c = true
      if o.fresh then
        c = ((W.friendly_calls or 0) > f0)
        check(TAG .. o.wname .. ": the caster AND the ally are re-fetched FRESH on the firing tick"
          .. " (friendly fetches " .. f0 .. "->" .. tostring(W.friendly_calls) .. ")", c)
      end
      note98(W, TAG); tally(W)
      return a and b and c
    else
      local a = (#W.fires == 0 and #W.ground_fires == 0)
      check(TAG .. o.wname .. ": stays SILENT (" .. fire_detail(W) .. ")", a)
      local b = true
      if o.want_skip_log then
        b = lg(TAG, count_log(W, "SKIPPED: the chosen ally lapsed before the cast") >= 1)
        check(TAG .. o.wname .. ": the pre-cast lapse skip is reported [live log]", b)
      end
      note98(W, TAG); tally(W)
      return a and b
    end
  end

  local DAB   = { key = "wh3_dlc26_character_abilities_da_boss_as_a_plan", marker = "da_boss_as_a_plan", bound = 105 }
  local PATCH = { key = "wh2_dlc13_character_abilities_patch_up", marker = "patch_up", bound = 70 }
  local SHOCK = { key = "wh2_dlc16_hero_abilities_shock_collar", marker = "shock_collar", bound = 70 }
  local PHOEN = { key = "wh3_dlc27_character_abilities_captain_of_the_phoenix_guard", marker = "captain_of_the_phoenix_guard", bound = 35 }
  local STAY  = { key = "wh2_dlc09_character_abilities_stay_here_ill_get_help", marker = "stay_here_ill_get_help", bound = 42 }

  local function w1(PATH, TAG) -- ALLY IN RANGE -> cast ON THE ALLY (buff family) + fresh handles
    return world_ab(PATH, TAG, { wname = "AB-U1: an in-melee caster with an ally in range casts ON THE ALLY",
      key = DAB.key, marker = DAB.marker, cuid = 9901, auid = 9902, cmelee = true, adist = 20, expect = "fire_ally", fresh = true })
  end
  local function w2(PATH, TAG) -- NO ALLY -> SILENT
    return world_ab(PATH, TAG, { wname = "AB-U2: no friendly unit other than the caster -> SILENT",
