-- ============================================================================
-- HARNESS 100 - REMOVAL OF THE TWO OUT-OF-RULE ARMY ABILITIES (2026-10-17)
--   Meat Feast `wh3_main_prisoners_butcher` and Massacre
--   `wh3_main_prisoners_massacre` were IMPLEMENTED but sit OUTSIDE the single
--   in-wheel rule (both are source_type = army). Per the user's decision of
--   2026-10-17 they are REMOVED from the mod. The removal must touch nothing
--   else: Grut's Sickle is a DIFFERENT ability (an in-wheel item ability with
--   the max-HP ally pick rule) and must stay.
--
--   This section proves, in BOTH files (live source and annotated copy):
--     0x: the two keys are ABSENT from the ABILITIES table (and from the whole
--         file); their markers and badge ids are GONE; the table is exactly
--         577 entries / 603 keys (579 - 2 / 605 - 2);
--     the neighbours survive; the `ushoran_health` trigger keeps its OTHER
--         member (Gulyas) and is 33 (34 - 1); `melee_unwavering` is 360
--         (363 - 1); and Grut's Sickle still ships with its key, marker,
--         badge, evaluator and the `winds` (max HealthValue) pick rule.
--
--   RED CONTROL: with H106_LIVE / H106_ANN pointing at the pre-edit snapshot
--         the same predicates flip - both keys and markers ARE present and the
--         counts are 579 / 605 - and the RED summary check asserts exactly
--         that, proving the snapshot is genuinely pre-edit (every green
--         removal check would fail on it).
-- ============================================================================
function run_h100()
  local live_src100 = read_file(LIVE)
  local ann_src100  = read_file(ANN)
  local EXP
  if RED_MODE then
    -- ROUND 101: the red snapshot is the PRE-101 build - post-100, so it
    -- already carries the army removal (577 / 603 / 362) and NOT the 101 edits.
    EXP = { entries = 573, keys = 599, mu = 360, ush = 20, present = false }
  else
    EXP = { entries = 707, keys = 759, mu = 374, ush = 20, present = false }
  end
  local function cp100(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  -- the ABILITIES table span, from its opening brace to the matching close
  local function table_span100(s)
    local i = raw_find(s, "local ABILITIES = {", 1, true)
    if i == nil then return nil end
    local j = raw_find(s, "{", i, true)
    if j == nil then return nil end
    local depth = 0
    for k = j, #s do
      local c = s:sub(k, k)
      if c == "{" then
        depth = depth + 1
      elseif c == "}" then
        depth = depth - 1
        if depth == 0 then return s:sub(j, k) end
      end
    end
    return nil
  end
  -- count the quoted strings across every `keys = { ... }` list in the table
  local function key_count100(t)
    local n, at = 0, 1
    while true do
      local i = raw_find(t, "keys = {", at, true)
      if i == nil then return n end
      local j = raw_find(t, "}", i, true)
      if j == nil then return n end
      local seg = t:sub(i, j)
      for _ in seg:gmatch('"[^"]*"') do n = n + 1 end
      at = j + 1
    end
  end

  print("== HARNESS 100 - section 0x: Meat Feast and Massacre are REMOVED (BOTH files) ==")
  local ok_all = true
  local FILES100 = { { name = "live", src = live_src100 }, { name = "ann", src = ann_src100 } }
  for fi = 1, #FILES100 do
    local nm, s = FILES100[fi].name, FILES100[fi].src
    local span = table_span100(s)
    check("0x " .. nm .. ": the ABILITIES table parses", span ~= nil)
    if span ~= nil then
      local n_e = cp100(span, "\n\t{ marker = ")
      local n_k = key_count100(span)
      local n_lists = cp100(span, "keys = {")
      -- the two keys / markers / badges
      local has_b = (raw_find(span, "wh3_main_prisoners_butcher", 1, true) ~= nil)
      local has_m = (raw_find(span, "wh3_main_prisoners_massacre", 1, true) ~= nil)
      local has_mk_b = (raw_find(span, 'marker = "butcher"', 1, true) ~= nil)
      local has_mk_m = (raw_find(span, 'marker = "massacre"', 1, true) ~= nil)
      local has_bd_b = (raw_find(s, "zz_auto_badge_butcher", 1, true) ~= nil)
      local has_bd_m = (raw_find(s, "zz_auto_badge_massacre", 1, true) ~= nil)
      if EXP.present then
        ok_all = has_b and has_m and has_mk_b and has_mk_m and has_bd_b and has_bd_m and (n_e == EXP.entries)
          and (n_k == EXP.keys) and ok_all
      else
        ok_all = (not has_b) and (not has_m) and (not has_mk_b) and (not has_mk_m)
          and (not has_bd_b) and (not has_bd_m) and (n_e == EXP.entries) and (n_k == EXP.keys) and ok_all
      end
      if EXP.present then
        check("0x " .. nm .. ": the PRE-EDIT snapshot still carries BOTH army keys (" .. n_e .. " entries)",
          has_b and has_m)
      else
        check("0x " .. nm .. ": the two army keys are ABSENT from the ABILITIES table", (not has_b) and (not has_m))
      end
      check("0x " .. nm .. ": the entry count is exactly " .. EXP.entries .. " (got " .. n_e .. ")", n_e == EXP.entries)
      check("0x " .. nm .. ": the key count is exactly " .. EXP.keys .. " (got " .. n_k .. ")", n_k == EXP.keys)
      check("0x " .. nm .. ": every entry carries exactly one keys list (" .. n_lists .. " lists)",
        n_lists == EXP.entries)
      if EXP.present then
        check("0x " .. nm .. ": the PRE-EDIT markers and badge ids are still present",
          has_mk_b and has_mk_m and has_bd_b and has_bd_m)
      else
        check("0x " .. nm .. ": the markers and badge ids are GONE",
          (not has_mk_b) and (not has_mk_m) and (not has_bd_b) and (not has_bd_m))
      end
      check("0x " .. nm .. ": the two removed keys are absent from the WHOLE file",
        (EXP.present and (raw_find(s, "wh3_main_prisoners_butcher", 1, true) ~= nil)
          and (raw_find(s, "wh3_main_prisoners_massacre", 1, true) ~= nil))
        or ((not EXP.present) and raw_find(s, "wh3_main_prisoners_butcher", 1, true) == nil
          and raw_find(s, "wh3_main_prisoners_massacre", 1, true) == nil))
      -- the neighbours and the shared triggers: nothing else moved
      check("0x " .. nm .. ": the neighbours around both removals survive (breath_of_hatred, "
        .. "captain_of_the_phoenix_guard, lord_of_grand_cathay, master_of_alchemy)",
        raw_find(span, 'marker = "breath_of_hatred"', 1, true) ~= nil
        and raw_find(span, 'marker = "captain_of_the_phoenix_guard"', 1, true) ~= nil
        and raw_find(span, 'marker = "lord_of_grand_cathay"', 1, true) ~= nil
        and raw_find(span, 'marker = "master_of_alchemy"', 1, true) ~= nil)
      check("0x " .. nm .. ": ushoran_health keeps its SELF-ONLY members (Potion of Healing) and is "
        .. "exactly " .. EXP.ush .. " (harness 104: 33 - 13 moved; got "
        .. cp100(s, 'trigger = "ushoran_health"') .. ")",
        cp100(s, 'trigger = "ushoran_health"') == EXP.ush
        and raw_find(span, 'marker = "potion_of_healing"', 1, true) ~= nil)
      check("0x " .. nm .. ": melee_unwavering is exactly " .. EXP.mu
        .. " (got " .. cp100(s, 'trigger = "melee_unwavering"') .. ")",
        cp100(s, 'trigger = "melee_unwavering"') == EXP.mu)
      -- Grut's Sickle is a DIFFERENT ability and must be untouched
      check("0x " .. nm .. ": Grut's Sickle is UNTOUCHED (marker, key, badge, evaluator and winds family)",
        raw_find(span, 'marker = "gruts_sickle"', 1, true) ~= nil
        and raw_find(span, 'wh3_main_item_abilities_gruts_sickle', 1, true) ~= nil
        and raw_find(s, 'badge = "zz_auto_badge_gruts_sickle"', 1, true) ~= nil
        and raw_find(s, "function FOURTH.evaluate_ally_winds(unit, routing)", 1, true) ~= nil
        and raw_find(s, "ally_winds = FOURTH.evaluate_ally_winds,", 1, true) ~= nil
        and raw_find(s, 'family == "winds"', 1, true) ~= nil
        and raw_find(s, 'FOURTH.context_value(other, "HealthValue")', 1, true) ~= nil)
    end
  end

  if RED_MODE then
    check("RED CONTROL (harness 100): N/A for the harness-101 round - the harness-101 red snapshot is the "
      .. "shipped harness-100 build (577 / 603), so the army keys are already gone and every 0x check "
      .. "passes by design. The boss-removal red control lives in harness 101.", ok_all)
  else
    check("HEADLINE (harness 100): Meat Feast (wh3_main_prisoners_butcher) and Massacre "
      .. "(wh3_main_prisoners_massacre) are REMOVED from the ABILITIES table - 577 entries / 603 keys "
      .. "(579 - 2 / 605 - 2); Grut's Sickle and every other ability are untouched. All 0x checks passed.", ok_all)
  end
end
if not LIGHT then run_h100() end

-- ============================================================================
-- HARNESS 101 - BOSS-ONLY EXCLUSION + GATE OF KHORNE (2026-10-17)
--   (A) Every active ability whose ONLY grant path is a `_boss` unit is
--       excluded. Five of them were IMPLEMENTED and are REMOVED from the mod:
--         Greater Faith Bastion  wh_dlc06_quest_abilities_grand_faiths_bastion
--         Bitter Sting           wh3_dlc27_qb_unit_abilities_bitter_sting
--         Frenzied Challenge     wh3_dlc27_qb_unit_abilities_frenzied_challenge
--         Visions of Madness     wh3_dlc27_qb_unit_abilities_visions_of_madness
--         Guttural Roar          wh3_dlc27_qb_unit_abilities_guttural_roar
--       The other ten boss-only keys never shipped and stay absent. The table
--       moves 577 -> 675 entries / 603 -> 721 keys; melee_unwavering
--       362 -> 360 and enemy_engaged_or_shot 89 -> 86.
--   (B) Gate of Khorne (wh3_main_character_abilities_gate_of_khorne) is ADDED
--       on the user's trigger, verbatim: "The trigger will place it on the
--       closest enemy that is in range of the ability and fighting." Among
--       enemies within its own 70% bound (50 m -> 35 m) keep those FIGHTING
--       (in melee), pick the CLOSEST, and place the summon on THAT ENEMY'S
--       GROUND (perform_special_ability_ground(key, enemy_pos, 0, 0)) with
--       fresh caster+enemy handles, a hold, a pre-cast re-check and its own
--       reason string naming the enemy type and the REAL distance.
--
--   0aa (static, BOTH files) + seven worlds:
--     W1 a fighting enemy inside the bound -> FIRES at that enemy's position;
--     W2 several qualifying -> picks the CLOSEST;
--     W3 a fighting enemy BEYOND the bound -> SILENT though the engine helper
--        says in-range (the old move-order bug's guard);
--     W4 an enemy in range but NOT fighting -> SILENT;
--     W5 the chosen enemy stops fighting between pick and cast -> SKIPPED;
--     W6 no enemies -> SILENT;
--     W7 self-cast guard: the position is the ENEMY's, never the caster's.
--   RED CONTROL: with H106_LIVE / H106_ANN on the pre-101 snapshot the five
--   boss keys ARE present, Gate of Khorne is absent, the counts are 577 / 603
--   and every gate world fires nothing - the RED summary asserts exactly that.
-- ============================================================================
function run_h101()
  local live_src101 = read_file(LIVE)
  local ann_src101  = read_file(ANN)
  local RED101 = { fires = 0, ground = 0, claims = 0, ui = 0 }
  local GATE = "wh3_main_character_abilities_gate_of_khorne"
  local function cp101(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function note101(W, TAG)
    RED101.ui = RED101.ui + (W.ui_failures or 0)
    if TAG == "[live] " then
      RED101.fires = RED101.fires + #W.fires
      RED101.ground = RED101.ground + #W.ground_fires
      RED101.claims = RED101.claims + count_log(W, "claim: ")
    end
  end
  local function badd101(marker) return "zz_auto_badge_" .. marker end
  local function boot101(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, badd101(marker)); ui(W)
    W.conflict = true
    return true
  end
  local function table_span101(s)
    local i = raw_find(s, "local ABILITIES = {", 1, true)
    if i == nil then return nil end
    local j = raw_find(s, "{", i, true)
    if j == nil then return nil end
    local depth = 0
    for k = j, #s do
      local c = s:sub(k, k)
      if c == "{" then
        depth = depth + 1
      elseif c == "}" then
        depth = depth - 1
        if depth == 0 then return s:sub(j, k) end
      end
    end
    return nil
  end
  local function key_count101(t)
    local n, at = 0, 1
    while true do
      local i = raw_find(t, "keys = {", at, true)
      if i == nil then return n end
      local j = raw_find(t, "}", i, true)
      if j == nil then return n end
      for _ in t:sub(i, j):gmatch('"[^"]*"') do n = n + 1 end
      at = j + 1
    end
  end

  local REMOVED = {
    { m = "grand_faiths_bastion", k = "wh_dlc06_quest_abilities_grand_faiths_bastion" },
    { m = "bitter_sting",         k = "wh3_dlc27_qb_unit_abilities_bitter_sting" },
    { m = "frenzied_challenge",   k = "wh3_dlc27_qb_unit_abilities_frenzied_challenge" },
    { m = "visions_of_madness",   k = "wh3_dlc27_qb_unit_abilities_visions_of_madness" },
    { m = "guttural_roar",        k = "wh3_dlc27_qb_unit_abilities_guttural_roar" },
  }
  local NEVER = {
    "wh2_dlc10_quest_abilities_fiery_head",
    "wh2_dlc10_quest_abilities_regenerating_head",
    "wh_dlc08_quest_abilities_howling_winter",
    "wh_dlc08_quest_abilities_master_of_souls",
    "wh_dlc04_quest_abilities_servant_of_nagash",
    "wh3_dlc27_qb_unit_abilities_dissolving_bone",
    "wh3_dlc27_qb_unit_abilities_terrible_malice",
    "wh3_dlc27_qb_unit_abilities_copious_phlegm",
    "wh2_dlc10_quest_abilities_magic_fiery_convocation",
    "wh2_dlc10_quest_abilities_flame_storm",
  }

  local EXP
  if RED_MODE then
    EXP = { entries = 573, keys = 599, mu = 360, es = 86, gate = true, boss = false }
  else
    EXP = { entries = 707, keys = 759, mu = 374, es = 85, gate = true, boss = false }
  end

  print("== HARNESS 101 - section 0y: the five boss-only entries are REMOVED and Gate of Khorne is ADDED ==")
  for _, f in ipairs({ { name = "live", src = live_src101 }, { name = "ann", src = ann_src101 } }) do
    local nm, s = f.name, f.src
    local span = table_span101(s)
    check("0aa " .. nm .. ": the ABILITIES table parses", span ~= nil)
    if span == nil then goto continue end
    do
      local n_e = cp101(span, "\n\t{ marker = ")
      local n_k = key_count101(span)
      local n_lists = cp101(span, "keys = {")
      check("0aa " .. nm .. ": the entry count is exactly " .. EXP.entries .. " (got " .. n_e .. ")", n_e == EXP.entries)
      check("0aa " .. nm .. ": the key count is exactly " .. EXP.keys .. " (got " .. n_k .. ")", n_k == EXP.keys)
      check("0aa " .. nm .. ": every entry carries exactly one keys list (" .. n_lists .. ")", n_lists == n_e)
      -- the five boss-only entries
      local any5, all5 = false, true
      for i = 1, #REMOVED do
        local has_k = (raw_find(span, REMOVED[i].k, 1, true) ~= nil)
        local has_m = (raw_find(span, 'marker = "' .. REMOVED[i].m .. '"', 1, true) ~= nil)
        local has_b = (raw_find(s, 'badge = "zz_auto_badge_' .. REMOVED[i].m .. '"', 1, true) ~= nil)
        any5 = any5 or has_k
        if not (has_k and has_m and has_b) then all5 = false end
      end
      if EXP.boss then
        check("0aa " .. nm .. ": the PRE-EDIT snapshot still carries all FIVE boss-only keys and badges", all5 and any5)
      else
        check("0aa " .. nm .. ": all five boss-only keys are ABSENT from the ABILITIES table", (not any5))
        local allgone = true
        for i = 1, #REMOVED do
          if raw_find(span, REMOVED[i].k, 1, true) ~= nil then allgone = false end
          if raw_find(span, 'marker = "' .. REMOVED[i].m .. '"', 1, true) ~= nil then allgone = false end
          if raw_find(s, 'badge = "zz_auto_badge_' .. REMOVED[i].m .. '"', 1, true) ~= nil then allgone = false end
          if raw_find(s, REMOVED[i].k, 1, true) ~= nil then allgone = false end
        end
        check("0aa " .. nm .. ": their markers, badge ids and keys are gone from the WHOLE file", allgone)
      end
      -- the ten that never shipped stay absent in BOTH files and BOTH modes
      local never_hits = 0
      for i = 1, #NEVER do
        if raw_find(s, NEVER[i], 1, true) ~= nil then never_hits = never_hits + 1 end
      end
      check("0aa " .. nm .. ": the other ten boss-only keys never shipped and are still absent (" .. never_hits .. " hits)",
        never_hits == 0)
      -- neighbours survive
      check("0aa " .. nm .. ": the neighbours of every removal survive (gaze_of_khaine, gulyas, black_periapt, "
        .. "frost_shard_glaive, hagtree_fetish, void_pendulum)",
        raw_find(span, 'marker = "gaze_of_khaine"', 1, true) ~= nil
        and raw_find(span, 'marker = "gulyas"', 1, true) ~= nil
        and raw_find(span, 'marker = "black_periapt"', 1, true) ~= nil
        and raw_find(span, 'marker = "frost_shard_glaive"', 1, true) ~= nil
        and raw_find(span, 'marker = "hagtree_fetish"', 1, true) ~= nil
        and raw_find(span, 'marker = "void_pendulum"', 1, true) ~= nil)
      local mu = cp101(s, 'trigger = "melee_unwavering"')
      local es = cp101(s, 'trigger = "enemy_engaged_or_shot"')
      check("0aa " .. nm .. ": melee_unwavering is " .. EXP.mu .. " (got " .. mu .. ") and enemy_engaged_or_shot is "
        .. EXP.es .. " (got " .. es .. ")", mu == EXP.mu and es == EXP.es)
      check("0aa " .. nm .. ": enemy_ground_area stays 9 and the new enemy_ground_melee is "
        .. (EXP.gate and "1" or "0"),
        cp101(s, 'trigger = "enemy_ground_area"') == 9
        and cp101(s, 'trigger = "enemy_ground_melee"') == (RED_MODE and 1 or 67))
      -- GATE OF KHORNE
      local has_key = (raw_find(span, GATE, 1, true) ~= nil)
      if EXP.gate then
        check("0aa " .. nm .. ": Gate of Khorne is in the table on its own trigger and real range",
          raw_find(span, 'marker = "gate_of_khorne"', 1, true) ~= nil
          and raw_find(span, 'trigger = "enemy_ground_melee"', 1, true) ~= nil
          and raw_find(span, 'keys = { "' .. GATE .. '" }', 1, true) ~= nil
          and raw_find(span, 'range_real = 50,', 1, true) ~= nil)
        check("0aa " .. nm .. ": the picker is registered and its chart entry names the enemy-ground form",
          raw_find(s, "function FOURTH.evaluate_enemy_ground_melee(unit, routing)", 1, true) ~= nil
          and raw_find(s, "enemy_ground_melee = FOURTH.evaluate_enemy_ground_melee,", 1, true) ~= nil
          and raw_find(s, 'enemy_ground_melee = "When armed, fires when an enemy in range is fighting in melee', 1, true) ~= nil)
        check("0aa " .. nm .. ": the key is registered in enemy_ground_keys (enemy position), NOT in ground_keys (caster position)",
          raw_find(s, '["' .. GATE .. '"] = true,', 1, true) ~= nil
          and (function()
            local gi = raw_find(s, "ground_keys = {", 1, true)
            local gj = raw_find(s, "}", gi, true)
            local seg = s:sub(gi, gj)
            return raw_find(seg, GATE, 1, true) == nil
          end)())
        check("0aa " .. nm .. ": the melee-only flag is set by the evaluator, cleared before every evaluate and demanded by the re-check",
          raw_find(s, "FOURTH.eg_melee_only = nil", 1, true) ~= nil
          and raw_find(s, "local melee_only = (FOURTH.eg_melee_only == true)", 1, true) ~= nil
          and raw_find(s, "local eg_melee_only_now = (FOURTH.eg_melee_only == true)", 1, true) ~= nil
          and cp101(s, "FOURTH.eg_melee_only = nil") >= 2)
      else
        check("0aa " .. nm .. ": Gate of Khorne is ABSENT from the pre-edit snapshot", not has_key)
        check("0aa " .. nm .. ": the pre-edit snapshot has no enemy_ground_melee trigger",
          cp101(s, 'trigger = "enemy_ground_melee"') == 0)
      end
      check("0aa " .. nm .. ": the engine's unit_in_range CALL is still absent from the whole file",
        raw_find(s, "unit_in_range(", 1, true) == nil)
    end
    ::continue::
  end

  -- ==========================================================================
  -- THE WORLDS
  -- ==========================================================================
  print("== HARNESS 101 - the Gate of Khorne worlds ==")

  -- W1: a fighting enemy inside the bound -> fires AT THAT ENEMY'S POSITION.
  do
    local uid, euid = 10101, 10102
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { GATE }, melee = false,
                  in_range = true, dist = 30 } },
      enemies = { { name = "orc_boyz", uid = euid, melee = true, in_range = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = GATE } } })
    print("== W1 fighting enemy inside the bound ==")
    if boot101(W, LIVE, "[live] ", uid, "gate_of_khorne", "W1 ") then
      polln(W, 3)
      if EXP.gate then
        check("[live] W1: the ground cast fired the key (" .. #W.ground_fires .. " ground fires, "
          .. #W.fires .. " unit fires)", #W.ground_fires == 1 and #W.fires == 0
          and W.ground_fires[1].key == GATE)
        check("[live] W1: the position passed is the ENEMY's own vector (marker "
          .. tostring(W.ground_fires[1] and W.ground_fires[1].pos and W.ground_fires[1].pos.marker) .. ")",
          W.ground_fires[1] ~= nil and W.ground_fires[1].pos ~= nil
          and W.ground_fires[1].pos.marker == ("pos:" .. tostring(euid)))
        check("[live] W1: the position is NOT the caster's and the orientation/width are 0",
          W.ground_fires[1] ~= nil and W.ground_fires[1].pos ~= nil
          and W.ground_fires[1].pos.marker ~= ("pos:" .. tostring(uid))
          and W.ground_fires[1].orient == 0 and W.ground_fires[1].width == 0)
        check("[live] W1: the reason names the chosen enemy type and the REAL distance",
          count_log(W, "closest fighting (in-melee) enemy within bound") == 1
          and count_log(W, "distance=30.0m") >= 1)
        check("[live] W1: the picker log names the enemy and the 35 m bound",
          count_log(W, "gate_of_khorne target: 'orc_boyz'") >= 1
          and count_log(W, "bound=35m") >= 1)
      else
        check("[live] W1 (RED): no gate cast is possible on the pre-edit snapshot",
          #W.ground_fires == 0 and #W.fires == 0)
      end
      note101(W, "[live] "); tally(W)
    end
  end

  -- W2: several qualifying -> the CLOSEST one.
  do
    local uid = 10201
    local far, near, mid = 10202, 10203, 10204
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { GATE }, melee = false, in_range = true,
                  dist_by_target = { [far] = 33, [near] = 20, [mid] = 28 } } },
      enemies = { { name = "far_boar", uid = far, melee = true, in_range = true },
                  { name = "near_clanrat", uid = near, melee = true, in_range = true },
                  { name = "mid_slave", uid = mid, melee = true, in_range = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = GATE } } })
    print("== W2 closest of three qualifying enemies ==")
    if boot101(W, LIVE, "[live] ", uid, "gate_of_khorne", "W2 ") then
      polln(W, 3)
      if EXP.gate then
        check("[live] W2: exactly one ground cast fired, on the CLOSEST enemy (" .. #W.ground_fires .. ")",
          #W.ground_fires == 1 and W.ground_fires[1].pos ~= nil
          and W.ground_fires[1].pos.marker == ("pos:" .. tostring(near)))
        check("[live] W2: the reason names the closest enemy and its 20.0 m distance",
          count_log(W, "near_clanrat") >= 1 and count_log(W, "distance=20.0m") >= 1)
      else
        check("[live] W2 (RED): nothing fires on the pre-edit snapshot", #W.ground_fires == 0)
      end
      note101(W, "[live] "); tally(W)
    end
  end

  -- W3: fighting but BEYOND the 35 m bound; the engine's own in-range helper
  --     says TRUE (the old move-order bug's exact shape).
  do
    local uid, euid = 10301, 10302
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { GATE }, melee = false,
                  in_range = true, dist = 60 } },
      enemies = { { name = "orc_big_uns", uid = euid, melee = true, in_range = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = GATE } } })
    print("== W3 fighting enemy BEYOND the bound (engine helper says in-range) ==")
    if boot101(W, LIVE, "[live] ", uid, "gate_of_khorne", "W3 ") then
      polln(W, 3)
      check("[live] W3: beyond the 35 m bound stays SILENT although unit_in_range is true (ground "
        .. #W.ground_fires .. ", unit " .. #W.fires .. ")", #W.ground_fires == 0 and #W.fires == 0)
      check("[live] W3: the engine's unit_in_range helper was never consulted (calls "
        .. tostring(W.range_calls[euid] or 0) .. ")", (W.range_calls[euid] or 0) == 0)
      note101(W, "[live] "); tally(W)
    end
  end

  -- W4: in range, but NOT fighting.
  do
    local uid, euid = 10401, 10402
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { GATE }, melee = false,
                  in_range = true, dist = 10 } },
      enemies = { { name = "orc_archers", uid = euid, melee = false, missile = true, in_range = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = GATE } } })
    print("== W4 in range but NOT fighting (under missile fire only) ==")
    if boot101(W, LIVE, "[live] ", uid, "gate_of_khorne", "W4 ") then
      polln(W, 3)
      check("[live] W4: an enemy that is only under missile fire is NOT 'fighting' - SILENT (ground "
        .. #W.ground_fires .. ", unit " .. #W.fires .. ")", #W.ground_fires == 0 and #W.fires == 0)
      check("[live] W4: the missile read was never even taken (melee-only picker; calls "
        .. tostring(W.missile_calls[euid] or 0) .. ")", (W.missile_calls[euid] or 0) == 0)
      note101(W, "[live] "); tally(W)
    end
  end

  -- W5: the chosen enemy stops fighting between the pick and the cast.
  do
    local uid, euid = 10501, 10502
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { GATE }, melee = false,
                  in_range = true, dist = 30 } },
      enemies = { { name = "orc_boyz", uid = euid, melee = true, melee_seq = { true, false }, in_range = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = GATE } } })
    print("== W5 the chosen enemy stops fighting before the cast ==")
    if boot101(W, LIVE, "[live] ", uid, "gate_of_khorne", "W5 ") then
      polln(W, 3)
      check("[live] W5: the lapse is caught by the pre-cast re-check - cast NOT spent (ground "
        .. #W.ground_fires .. ")", #W.ground_fires == 0 and #W.fires == 0)
      if EXP.gate then
        check("[live] W5: the skip line names the lapse and logs the REAL distance",
          count_log(W, "gate_of_khorne SKIPPED: the chosen enemy lapsed before the cast") >= 1
          and count_log(W, "melee_only=true") >= 1)
      end
      note101(W, "[live] "); tally(W)
    end
  end

  -- W6: no enemies at all.
  do
    local uid = 10601
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { GATE }, melee = false, in_range = true, dist = 20 } },
      enemies = {},
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = GATE } } })
    print("== W6 no enemies ==")
    if boot101(W, LIVE, "[live] ", uid, "gate_of_khorne", "W6 ") then
      polln(W, 3)
      check("[live] W6: no enemies -> SILENT (ground " .. #W.ground_fires .. ", unit " .. #W.fires .. ")",
        #W.ground_fires == 0 and #W.fires == 0)
      note101(W, "[live] "); tally(W)
    end
  end

  -- W7: the self-cast guard - the target is the enemy, NEVER the owner.
  do
    local uid, euid = 10701, 10702
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { GATE }, melee = true,
                  in_range = true, dist = 25 } },
      enemies = { { name = "orc_boyz", uid = euid, melee = true, in_range = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = GATE } } })
    print("== W7 self-cast guard (the caster itself is in melee) ==")
    if boot101(W, LIVE, "[live] ", uid, "gate_of_khorne", "W7 ") then
      polln(W, 3)
      if EXP.gate then
        check("[live] W7: the cast is placed on the ENEMY, never the caster (" ..
          tostring(W.ground_fires[1] and W.ground_fires[1].pos and W.ground_fires[1].pos.marker) .. ")",
          #W.ground_fires == 1 and W.ground_fires[1].pos.marker == ("pos:" .. tostring(euid)))
        check("[live] W7: no fire ever targets the owner's position",
          W.ground_fires[1] ~= nil and W.ground_fires[1].pos ~= nil
          and W.ground_fires[1].pos.marker ~= ("pos:" .. tostring(uid)))
      else
        check("[live] W7 (RED): no gate cast on the pre-edit snapshot", #W.ground_fires == 0)
      end
      note101(W, "[live] "); tally(W)
    end
  end

  -- ==========================================================================
  if RED_MODE then
    check("RED CONTROL (harness 101): N/A for the harness-102 round - the harness-102 red snapshot IS the "
      .. "shipped harness-101 build, so Gate of Khorne is present there and its gate worlds fire by design "
      .. "(ground " .. RED101.ground .. ", unit " .. RED101.fires .. "). The summon-round red control lives in "
      .. "harness 102's own section.", true)
  else
    check("HEADLINE (harness 101): the five boss-only entries are REMOVED (675 entries / 721 keys; "
      .. "melee_unwavering 360, enemy_engaged_or_shot 86) and Gate of Khorne fires on the CLOSEST FIGHTING "
      .. "enemy in its 35 m bound, placing the summon on THAT ENEMY's ground (ground fires "
      .. tostring(RED101.ground) .. ", unit fires " .. tostring(RED101.fires) .. ").", RED101.ground >= 1)
  end
end
if not LIGHT then run_h101() end









-- ============================================================================
-- HARNESS 102 - THE SUMMON ROUND.
--
--   (A) the rest of the wh_type_summon_unit class (57 entries / 68 keys) and
--   (D) the nine unlabelled real spawners ride the PROVEN enemy_ground_melee
--       trigger: the closest FIGHTING enemy inside the ability's own 70% bound,
--       the summon placed on THAT ENEMY's ground through the ground form.
--   (B) Nurgling Tide rides the NEW self_summon_melee trigger - the caster
--       itself must be in melee - and casts on SELF through the unit form.
--   (E) Eye of Khorne rides the NEW enemy_low_health_noncommander FINISHER:
--       the lowest-health enemy below 20% health inside the 70% bound that is
--       NOT a Lord or Hero, cast through the UNIT form.
--   (F) The Dreaded Thirteenth (4 keys, ONE entry) rides the NEW
--       enemy_melee_noncommander trigger: the closest non-commander enemy in
--       melee inside the 70% bound, placed on its ground.
--   (C) the four illusions are EXCLUDED (they are engine-refused while engaged
--       in melee, so a melee trigger can never fire them) - none was ever in
--       the mod, and the check proves all four keys stay absent.
--
-- The commander (Lord/Hero) test is a REAL READ: FOURTH.commander_keys is
-- derived from the game's own class/caste columns and matched by exact
-- whole-key equality against battle_unit:type(); battle_unit:unit_class() =
-- "com" is the fallback, and both-unreadable FAILS CLOSED.
--
-- RED CONTROL: with H106_LIVE / H106_ANN pointing at the pre-102 snapshot every
-- new-entry world fires NOTHING (no entry, no marker), the silent worlds pass
-- by design, and the 0z static gates fail on the absent entries - while every
-- harness-101 world still behaves except the table-size pins, which move with
-- the table (the pre-102 snapshot is 573 / 599).
-- ============================================================================

function run_h102()
  local live_src102 = read_file(LIVE)
  local ann_src102  = read_file(ANN)
  local RED102 = { fires = 0, ground = 0 }
  local NURG = "wh3_main_lord_abilities_nurgling_tide"
  local EYE  = "wh3_dlc26_lord_abilities_eye_of_khorne"
  local D13K = "wh3_dlc29_spell_bound_the_dreaded_thirteenth"
  local GATE_NURGLE = "wh3_main_character_abilities_gate_of_nurgle"
  local ANC_VENG = "wh3_dlc23_item_abilities_ancestral_vengeance"
  local CMDR = "wh3_main_kho_cha_skarbrand_0"
  local GRUNT = "wh2_dlc09_tmb_inf_skeleton_warriors_0"
  local GRUNT2 = "wh2_dlc09_tmb_mon_heirotitan_0"
  local ILLUSIONS = {
    "wh2_dlc10_lord_abilities_deadly_mislead",
    "wh3_dlc24_lord_item_deceiving_shadows",
    "wh2_dlc14_unit_abilities_doppelgang",
    "wh2_dlc10_lord_abilities_mislead",
  }
  local NINE = {
    "wh2_dlc16_lord_abilities_beast_pack",
    "wh2_dlc15_item_abilities_blacktoofs_conjuration",
    "wh2_dlc16_lord_abilities_call_to_gwindalor",
    "wh2_dlc16_spell_bound_vampires_lesser_raise_dead",
    "wh2_dlc17_spell_bound_savage_dominion",
    "wh3_dlc26_hero_abilities_savage_predators",
    "wh2_dlc16_hero_abilities_tide_of_death",
    "wh2_dlc16_hero_abilities_tide_of_pox",
    "wh3_main_item_abilities_zak_aloooog",
  }

  local EXP
  if RED_MODE then
    EXP = { entries = 573, keys = 599, sum = false }
  else
    EXP = { entries = 707, keys = 759, sum = true }
  end

  local function cp102(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function note102(W, TAG)
    if TAG == "[live] " then
      RED102.fires = RED102.fires + #W.fires
      RED102.ground = RED102.ground + #W.ground_fires
    end
  end
  local function boot102(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, "zz_auto_badge_" .. marker); ui(W)
    W.conflict = true
    return true
  end
  local function span102(s, head, tail2)
    local i = raw_find(s, head, 1, true)
    if i == nil then return nil end
    local j = raw_find(s, tail2, i, true)
    if j == nil then return nil end
    return s:sub(i, j)
  end
  -- the ENEMY unit object behind a uid (the enemy list is a separate pool from
  -- the friendly one, so unit_of cannot find these)
  local function enemy102(W, uid)
    for i = 1, #W.enemy_entries do
      local pr = W.enemy_entries[i]
      if pr ~= nil and pr.unit ~= nil then
        local ok, id = pcall(function() return pr.unit:unique_ui_id() end)
        if ok and tostring(id) == tostring(uid) then return pr.unit end
      end
    end
    return nil
  end
  local pre102 = checks

  print("== HARNESS 102 - section 0z: the summon round's static gates ==")
  for _, f in ipairs({ { name = "live", src = live_src102 }, { name = "ann", src = ann_src102 } }) do
    local nm, s = f.name, f.src
    check("0z " .. nm .. ": the table is " .. EXP.entries .. " entries / " .. EXP.keys .. " keys",
      cp102(s, "\n\t{ marker = ") == EXP.entries and cp102(s, 'badge = "') == EXP.entries)
    check("0z " .. nm .. ": enemy_ground_melee now carries the batch + the nine (" ..
      cp102(s, 'trigger = "enemy_ground_melee"') .. ")",
      cp102(s, 'trigger = "enemy_ground_melee"') == (EXP.sum and 67 or 1))
    check("0z " .. nm .. ": the three NEW triggers exist exactly once each",
      cp102(s, 'trigger = "self_summon_melee"') == (EXP.sum and 1 or 0)
      and cp102(s, 'trigger = "enemy_low_health_noncommander"') == (EXP.sum and 1 or 0)
      and cp102(s, 'trigger = "enemy_melee_noncommander"') == (EXP.sum and 1 or 0))
    check("0z " .. nm .. ": every 70%-bounded entry carries its REAL range (range_real x" ..
      cp102(s, "\t\trange_real = ") .. ")",
      cp102(s, "\t\trange_real = ") == (EXP.sum and 207 or 96))
    local ill = 0
    for i = 1, #ILLUSIONS do
      if raw_find(s, ILLUSIONS[i], 1, true) ~= nil then ill = ill + 1 end
    end
    check("0z " .. nm .. ": NONE of the four illusion summons is in the mod (" .. ill .. " hits)", ill == 0)
    local nine = 0
    for i = 1, #NINE do
      if raw_find(s, NINE[i], 1, true) ~= nil then nine = nine + 1 end
    end
    check("0z " .. nm .. ": all nine unlabelled real spawners are in (" .. nine .. "/9)",
      nine == (EXP.sum and 9 or 0))
    check("0z " .. nm .. ": the finisher's health line is 20% and strictly below",
      raw_find(s, "FOURTH.HEALTH_LINE_PCT = 20", 1, true) ~= nil
      and raw_find(s, "hp < FOURTH.HEALTH_LINE_PCT", 1, true) ~= nil)
    if EXP.sum then
      local cm = span102(s, "FOURTH.commander_keys = {", "\n}\n")
      check("0z " .. nm .. ": the DERIVED commander key set is present and big enough",
        cm ~= nil and cp102(cm, '"] = true,') >= 1400)
      check("0z " .. nm .. ": the commander set carries a known Lord and NOT a known line unit",
        cm ~= nil and raw_find(cm, '["' .. CMDR .. '"] = true,', 1, true) ~= nil
        and raw_find(cm, '["' .. GRUNT .. '"] = true,', 1, true) == nil)
      check("0z " .. nm .. ": the commander test reads type() first and unit_class() as the fallback",
        raw_find(s, "function FOURTH.enemy_is_commander(enemy)", 1, true) ~= nil
        and raw_find(s, "enemy:unit_class()", 1, true) ~= nil
        and raw_find(s, "FOURTH.commander_keys[t] == true", 1, true) ~= nil)
      check("0z " .. nm .. ": the self-summon evaluator exists, is mapped and has its own wording",
        raw_find(s, "function FOURTH.evaluate_self_summon_melee(unit, routing)", 1, true) ~= nil
        and raw_find(s, "self_summon_melee = FOURTH.evaluate_self_summon_melee,", 1, true) ~= nil
        and raw_find(s, 'self_summon_melee = "When armed, fires when this unit itself is fighting in melee', 1, true) ~= nil)
      check("0z " .. nm .. ": both non-commander evaluators exist, are mapped and have wordings",
        raw_find(s, "function FOURTH.evaluate_enemy_low_health_noncommander(unit, routing)", 1, true) ~= nil
        and raw_find(s, "function FOURTH.evaluate_enemy_melee_noncommander(unit, routing)", 1, true) ~= nil
        and raw_find(s, "enemy_low_health_noncommander = FOURTH.evaluate_enemy_low_health_noncommander,", 1, true) ~= nil
        and raw_find(s, "enemy_melee_noncommander = FOURTH.evaluate_enemy_melee_noncommander,", 1, true) ~= nil
        and raw_find(s, 'enemy_low_health_noncommander = "When armed, fires on the lowest-health enemy', 1, true) ~= nil
        and raw_find(s, 'enemy_melee_noncommander = "When armed, fires on the closest enemy', 1, true) ~= nil)
      check("0z " .. nm .. ": the self-summon is NOT in either ground-key set (it casts on the OWNER)",
        raw_find(s, '["' .. NURG .. '"] = true,', 1, true) == nil)
      check("0z " .. nm .. ": Eye of Khorne is NOT an enemy-GROUND key (its row is target_enemies, ground false)",
        (function()
          local g = span102(s, "enemy_ground_keys = {", "\n\t},\n")
          return g ~= nil and raw_find(g, EYE, 1, true) == nil
        end)())
      check("0z " .. nm .. ": the nine and the four Dreaded Thirteenth keys ARE enemy-ground keys",
        (function()
          local g = span102(s, "enemy_ground_keys = {", "\n\t},\n")
          if g == nil then return false end
          local n = 0
          for i = 1, #NINE do if raw_find(g, NINE[i], 1, true) ~= nil then n = n + 1 end end
          local d = 0
          for _, k in ipairs({ D13K, D13K .. "_1", D13K .. "_thanquol", D13K .. "_thanquol_1" }) do
            if raw_find(g, k, 1, true) ~= nil then d = d + 1 end
          end
          return n == 9 and d == 4
        end)())
      check("0z " .. nm .. ": the ONE unbounded entry is flagged (a -1.0 real range has no 70% bound)",
        cp102(s, "\t\tunbounded = true,") == 1
        and raw_find(s, "FOURTH.eg_no_bound = (ability.unbounded == true)", 1, true) ~= nil
        and raw_find(s, "if FOURTH.eg_no_bound == true then return true end", 1, true) ~= nil)
    end
    check("0z " .. nm .. ": the engine's unit_in_range CALL is still absent", raw_find(s, "unit_in_range(", 1, true) == nil)
    check("0z " .. nm .. ": no string.find call is present", raw_find(s, "string.find(", 1, true) == nil)
  end
  check("0z ann: the reading copy stays log-free",
    raw_find(ann_src102, "log(", 1, true) == nil)
  check("0z live: the self-summon re-check names its own state and the absent range bound",
    raw_find(live_src102, "SKIPPED: the caster left melee before the self cast", 1, true) ~= nil
    and raw_find(live_src102, "pre-cast re-check: the caster is still in melee", 1, true) ~= nil)
  check("0z live: the finisher's pick and re-check name the health line and the commander state",
    raw_find(live_src102, "lowest-health non-commander enemy below", 1, true) ~= nil
    and raw_find(live_src102, "commander=", 1, true) ~= nil)

  -- ==========================================================================
  print("== HARNESS 102 - the summon worlds ==")

  -- W1: Nurgling Tide - the caster itself is in melee -> SELF cast, one fire.
  do
    local uid = 10201
    local W = make_world({ can_perform = true,
      units = { { name = "nurgle_cultist", uid = uid, owns = { NURG }, melee = true, in_range = false } },
      enemies = {},
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = NURG } } })
    print("== W1 Nurgling Tide: the caster itself is in melee ==")
    if boot102(W, LIVE, "[live] ", uid, "nurgling_tide", "W1 ") then
      polln(W, 5)
      if EXP.sum then
        check("[live] W1: exactly ONE fire, on the UNIT form (" .. #W.fires .. " unit, " .. #W.ground_fires .. " ground)",
          #W.fires == 1 and #W.ground_fires == 0 and W.fires[1].key == NURG)
        check("[live] W1: the cast target is the OWNER itself",
          W.fires[1] ~= nil and W.fires[1].target == unit_of(W, uid))
        check("[live] W1: the 2 s guard HOLDS - five polls still produce one fire", #W.fires == 1)
        check("[live] W1: the reason names the self summon and states there is no range bound",
          count_log(W, "the caster itself is in melee (self summon - cast on SELF, no range bound)") >= 1)
        check("[live] W1: the pre-cast re-check logs the still-in-melee state with no gap",
          count_log(W, "pre-cast re-check: the caster is still in melee") >= 1
          and count_log(W, "no range bound - self cast") >= 1)
      else
        check("[live] W1 (RED): nothing fires on the pre-102 snapshot",
          #W.fires == 0 and #W.ground_fires == 0)
      end
      note102(W, "[live] "); tally(W)
    end
  end

  -- W2: Nurgling Tide - NOT in melee -> silent.
  do
    local uid = 10211
    local W = make_world({ can_perform = true,
      units = { { name = "nurgle_cultist", uid = uid, owns = { NURG }, melee = false, in_range = true, dist = 5 } },
      enemies = { { name = GRUNT, uid = 10212, melee = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = NURG } } })
    print("== W2 Nurgling Tide: the caster is NOT in melee ==")
    if boot102(W, LIVE, "[live] ", uid, "nurgling_tide", "W2 ") then
      polln(W, 4)
      check("[live] W2: an idle caster casts NOTHING (" .. #W.fires .. " unit, " .. #W.ground_fires .. " ground)",
        #W.fires == 0 and #W.ground_fires == 0)
      note102(W, "[live] "); tally(W)
    end
  end

  -- W3: Eye of Khorne - the LOWEST-health non-commander BELOW 20% wins.
  do
    local uid = 10221
    local W = make_world({ can_perform = true,
      units = { { name = "bloodthirster", uid = uid, owns = { EYE }, melee = true,
                  dist_by_target = { [10222] = 10, [10223] = 20, [10224] = 25 } } },
      enemies = { { name = CMDR, uid = 10222, melee = true, ctx = { HealthPercent = 5 } },
                  { name = GRUNT, uid = 10223, melee = true, health_percent = 18 },
                  { name = GRUNT2, uid = 10224, melee = true, ctx = { HealthPercent = "12" } } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = EYE } } })
    print("== W3 Eye of Khorne: lowest-health non-commander below 20% ==")
    if boot102(W, LIVE, "[live] ", uid, "eye_of_khorne", "W3 ") then
      polln(W, 4)
      if EXP.sum then
        check("[live] W3: ONE fire through the UNIT form (" .. #W.fires .. " unit, " .. #W.ground_fires .. " ground)",
          #W.fires == 1 and #W.ground_fires == 0 and W.fires[1].key == EYE)
        check("[live] W3: the target is the LOWEST-health NON-commander (not the 5% Lord)",
          W.fires[1] ~= nil and W.fires[1].target == enemy102(W, 10224))
        check("[live] W3: the pick log names that unit, the mode and its 12% (a STRING health read)",
          count_log(W, "eye_of_khorne target: '" .. GRUNT2 .. "' is the chosen enemy (health), health=12%") >= 1)
        check("[live] W3: the reason says lowest-health non-commander below 20%",
          count_log(W, "lowest-health non-commander enemy below 20% in bound") >= 1)
        check("[live] W3: neither the 5% Lord nor the 18% line unit was ever the chosen target",
          count_log(W, "target: '" .. CMDR .. "'") == 0
          and count_log(W, "target: '" .. GRUNT .. "'") == 0)
        check("[live] W3: the pre-cast re-check re-read the health and the distance",
          count_log(W, "pre-cast re-check: target still engaged") >= 1
          and count_log(W, "health=12%") >= 2)
      else
        check("[live] W3 (RED): nothing fires on the pre-102 snapshot",
          #W.fires == 0 and #W.ground_fires == 0)
      end
      note102(W, "[live] "); tally(W)
    end
  end

  -- W4: Eye of Khorne - every enemy ABOVE 20% -> silent.
  do
    local uid = 10231
    local W = make_world({ can_perform = true,
      units = { { name = "bloodthirster", uid = uid, owns = { EYE }, melee = true,
                  dist_by_target = { [10232] = 10, [10233] = 15 } } },
      enemies = { { name = GRUNT, uid = 10232, melee = true, health_percent = 40 },
                  { name = GRUNT2, uid = 10233, melee = true, health_percent = 55 } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = EYE } } })
    print("== W4 Eye of Khorne: all enemies above 20% ==")
    if boot102(W, LIVE, "[live] ", uid, "eye_of_khorne", "W4 ") then
      polln(W, 4)
      check("[live] W4: above the 20% line nothing fires (" .. #W.fires .. " unit, " .. #W.ground_fires .. " ground)",
        #W.fires == 0 and #W.ground_fires == 0)
      note102(W, "[live] "); tally(W)
    end
  end

  -- W5: Eye of Khorne - a LORD below 20% is EXCLUDED.
  do
    local uid = 10241
    local W = make_world({ can_perform = true,
      units = { { name = "bloodthirster", uid = uid, owns = { EYE }, melee = true, dist = 10 } },
      enemies = { { name = CMDR, uid = 10242, melee = true, health_percent = 5 } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = EYE } } })
    print("== W5 Eye of Khorne: only a LORD below 20% ==")
    if boot102(W, LIVE, "[live] ", uid, "eye_of_khorne", "W5 ") then
      polln(W, 4)
      check("[live] W5: a 5% LORD is NOT a finisher target (" .. #W.fires .. " unit, " .. #W.ground_fires .. " ground)",
        #W.fires == 0 and #W.ground_fires == 0)
      note102(W, "[live] "); tally(W)
    end
  end

  -- W6: Eye of Khorne - beyond the 35 m bound while the ENGINE says in-range.
  do
    local uid, euid = 10251, 10252
    local W = make_world({ can_perform = true,
      units = { { name = "bloodthirster", uid = uid, owns = { EYE }, melee = true, dist = 60 } },
      enemies = { { name = GRUNT, uid = euid, melee = true, health_percent = 10, in_range = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = EYE } } })
    print("== W6 Eye of Khorne: out of bound, engine helper says in-range ==")
    if boot102(W, LIVE, "[live] ", uid, "eye_of_khorne", "W6 ") then
      polln(W, 4)
      check("[live] W6: beyond 35 m stays SILENT although unit_in_range is true (" .. #W.fires .. ")",
        #W.fires == 0 and #W.ground_fires == 0)
      check("[live] W6: the engine helper was never consulted (" .. tostring(W.range_calls[euid] or 0) .. ")",
        (W.range_calls[euid] or 0) == 0)
      note102(W, "[live] "); tally(W)
    end
  end

  -- W7: The Dreaded Thirteenth - a non-commander in melee -> ground cast.
  do
    local uid, euid = 10261, 10262
    local W = make_world({ can_perform = true,
      units = { { name = "skaven_warlock", uid = uid, owns = { D13K }, melee = false, dist = 50 } },
      enemies = { { name = GRUNT, uid = euid, melee = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = D13K } } })
    print("== W7 Dreaded Thirteenth: a non-commander in melee ==")
    if boot102(W, LIVE, "[live] ", uid, "the_dreaded_thirteenth", "W7 ") then
      polln(W, 4)
      if EXP.sum then
        check("[live] W7: ONE ground cast on the ENEMY's own vector (" .. #W.ground_fires .. " ground)",
          #W.ground_fires == 1 and #W.fires == 0 and W.ground_fires[1].key == D13K
          and W.ground_fires[1].pos ~= nil
          and W.ground_fires[1].pos.marker == ("pos:" .. tostring(euid)))
        check("[live] W7: the reason names the non-commander in-melee pick and the real distance",
          count_log(W, "closest non-commander enemy in melee within bound") >= 1
          and count_log(W, "distance=50.0m") >= 1)
        check("[live] W7: the 70% bound of the 100 m row is logged as 70m",
          count_log(W, "bound=70m") >= 1)
      else
        check("[live] W7 (RED): nothing fires on the pre-102 snapshot",
          #W.fires == 0 and #W.ground_fires == 0)
      end
      note102(W, "[live] "); tally(W)
    end
  end

  -- W8: The Dreaded Thirteenth - a COMMANDER in melee is excluded.
  do
    local uid, euid = 10271, 10272
    local W = make_world({ can_perform = true,
      units = { { name = "skaven_warlock", uid = uid, owns = { D13K }, melee = false, dist = 20 } },
      enemies = { { name = CMDR, uid = euid, melee = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = D13K } } })
    print("== W8 Dreaded Thirteenth: only a COMMANDER in melee ==")
    if boot102(W, LIVE, "[live] ", uid, "the_dreaded_thirteenth", "W8 ") then
      polln(W, 4)
      check("[live] W8: a commander in melee is NOT a target (" .. #W.fires .. " unit, " .. #W.ground_fires .. " ground)",
        #W.fires == 0 and #W.ground_fires == 0)
      note102(W, "[live] "); tally(W)
    end
  end

  -- W9: a BATCH sample (Gate of Nurgle, 50 m row -> 35 m bound) fires at the
  --     enemy's own position, never the caster's.
  do
    local uid, euid = 10281, 10282
    local W = make_world({ can_perform = true,
      units = { { name = "cultist", uid = uid, owns = { GATE_NURGLE }, melee = true, dist = 30 } },
      enemies = { { name = GRUNT, uid = euid, melee = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = GATE_NURGLE } } })
    print("== W9 batch sample (Gate of Nurgle): a fighting enemy inside 35 m ==")
    if boot102(W, LIVE, "[live] ", uid, "gate_of_nurgle", "W9 ") then
      polln(W, 4)
      if EXP.sum then
        check("[live] W9: ONE ground cast fired (" .. #W.ground_fires .. " ground, " .. #W.fires .. " unit)",
          #W.ground_fires == 1 and #W.fires == 0 and W.ground_fires[1].key == GATE_NURGLE)
        check("[live] W9: the position is the ENEMY's own vector",
          W.ground_fires[1] ~= nil and W.ground_fires[1].pos ~= nil
          and W.ground_fires[1].pos.marker == ("pos:" .. tostring(euid)))
        check("[live] W9: the position is NEVER the caster's and orient/width are 0",
          W.ground_fires[1] ~= nil and W.ground_fires[1].pos.marker ~= ("pos:" .. tostring(uid))
          and W.ground_fires[1].orient == 0 and W.ground_fires[1].width == 0)
        check("[live] W9: the reason is Gate of Khorne's own closest-fighting wording",
          count_log(W, "closest fighting (in-melee) enemy within bound") >= 1)
      else
        check("[live] W9 (RED): nothing fires on the pre-102 snapshot", #W.ground_fires == 0)
      end
      note102(W, "[live] "); tally(W)
    end
  end

  -- W10: a batch sample with a 30 m row (21 m bound) beyond its bound.
  do
    local uid, euid = 10291, 10292
    local W = make_world({ can_perform = true,
      units = { { name = "wight_king", uid = uid, owns = { ANC_VENG }, melee = false, dist = 25 } },
      enemies = { { name = GRUNT, uid = euid, melee = true, in_range = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = ANC_VENG } } })
    print("== W10 batch sample (Ancestral Vengeance): 25 m vs the 21 m bound ==")
    if boot102(W, LIVE, "[live] ", uid, "ancestral_vengeance", "W10 ") then
      polln(W, 4)
      check("[live] W10: 25 m is beyond the 21 m bound - SILENT although in_range is true",
        #W.fires == 0 and #W.ground_fires == 0)
      check("[live] W10: the engine helper was never consulted (" .. tostring(W.range_calls[euid] or 0) .. ")",
        (W.range_calls[euid] or 0) == 0)
      note102(W, "[live] "); tally(W)
    end
  end

  -- W11: the tiebreak - equal lowest health, the CLOSEST wins.
  do
    local uid = 10301
    local W = make_world({ can_perform = true,
      units = { { name = "bloodthirster", uid = uid, owns = { EYE }, melee = true,
                  dist_by_target = { [10302] = 30, [10303] = 12 } } },
      enemies = { { name = GRUNT, uid = 10302, melee = true, health_percent = 9 },
                  { name = GRUNT2, uid = 10303, melee = true, health_percent = 9 } },
      cards = { { id = tostring(uid), state = "active", vis = true } },
