      polln(W, 6)
      if RED_MODE then
        check("[live] W8 (RED): the pre-103 build fired at 90% health (" .. #W.fires .. ")", #W.fires >= 1)
      else
        check("[live] W8: a 90%-health unit does not fire the <=75% trigger (" .. #W.fires .. ")", #W.fires == 0)
      end
