  -- ==========================================================================
  if RED_MODE then
    check("HARNESS 102 suite boundary (harness 103): N/A in the red run - the pre-103 snapshot"
      .. " carries every harness-102 world unchanged", true)
  else
    check("HARNESS 102 suite boundary (harness 103): every harness-102 check ran first ("
      .. pre103 .. ", want 3518)", pre103 == 3518)
