-- ============================================================================
-- HARNESS 105 - TZ'ARKAN ON THE NEW LOW-HEALTH TRIGGER
--
-- THE USER'S RULE (verbatim): "I think it might make sense to activate Tz'arkan
--   when caster health is below 15%, don't you think? Let's implement and test
--   it."
--
-- WHAT SHIPPED: ONE new entry ("tzarkan") carrying all FIVE Tz'arkan keys
--   (wh2_dlc14_lord_abilities_tzarkan, _mp, _snikch, _spite, _spite_mp) on ONE
--   new trigger family, health_below_15, with its own evaluator
--   FOURTH.evaluate_tzarkan_low_health and its own tooltip sentence. The rule:
--   the OWNER is ALIVE (the poll gates that), NOT routing, and its health -
--   read through FOURTH.health_pct, the ONE 0-100 reader - is BELOW 15. The
--   cast is on the OWNER ITSELF through the unit form, with the caster's
--   controller re-fetched FRESH that tick. There is no range bound: a self
--   cast has no distance to measure.
--
-- THE WIND-UP HOLE THIS ROUND CLOSES: a transform is likely ONE-WAY and its row
--   declares 3 s of wind-up (1.5 s for the Snikch key), so a caster at 14% can
--   DIE or be HEALED inside that window. The evaluator logs the exact
--   percentage at the decision and attempt_activation RE-READS it immediately
--   before the call, logging it again and SKIPPING (cast not spent) when the
--   unit died or rose above the line. The threshold is deliberate (the user's
--   own number) and is ONE constant, FOURTH.TZARKAN_PCT.
--
-- WORLDS (each runs against BOTH the live source and the annotated copy):
--   T1  14.0% health          -> fires exactly once, on the OWNER, exact
--                                percentages in the log at both points.
--   T2  16.0% health          -> SILENT (the line is exclusive: below 15).
--   T3  14.0% -> 25.0% inside the same tick (the wind-up window)
--                             -> the pre-cast re-check SKIPS the cast.
--   T4  a dead owner (0 men)  -> SILENT (the poll's own alive gate).
--
-- RED CONTROL (H106_LIVE/H106_ANN -> docs/backups/round105/*.pre105.lua): the
--   pre-105 build has no entry, no evaluator and no trigger, so T1 never fires
--   and T3's skip line never appears - exactly those discriminators fail there
--   while every harness-104 world still passes. T2/T4 assert SILENCE and so
--   pass by design on the old build (documented, not a discriminator).
-- ============================================================================
function run_h105()
  local live_src105 = read_file(LIVE)
  local ann_src105  = read_file(ANN)
  local TZ = {
    "wh2_dlc14_lord_abilities_tzarkan",
    "wh2_dlc14_lord_abilities_tzarkan_mp",
    "wh2_dlc14_lord_abilities_tzarkan_snikch",
    "wh2_dlc14_lord_abilities_tzarkan_spite",
    "wh2_dlc14_lord_abilities_tzarkan_spite_mp",
  }
  local pre105 = checks
  local READ_N = {}   -- per TAG: unary_hitpoints reads in ONE firing tick

  local function cp105(s2, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s2, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function table_span105(s2)
    local i = raw_find(s2, "local ABILITIES = {", 1, true)
    if i == nil then return nil end
    local j = raw_find(s2, "\n}\n", i, true)
    if j == nil then return nil end
    return s2:sub(i, j)
  end
  local function span105(s2, head, tail2)
    local i = raw_find(s2, head, 1, true)
    if i == nil then return nil end
    local j = raw_find(s2, tail2, i, true)
    if j == nil then return nil end
    return s2:sub(i, j)
  end
  local function boot105(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, "zz_auto_badge_" .. marker); ui(W)
    W.conflict = true
    return true
  end
  local function lg105(cond) return cond == true end

  -- ==========================================================================
  print("== HARNESS 105 - section 0e: Tz'arkan's entry, trigger, gates and re-check (BOTH files) ==")
  for _, f in ipairs({ { name = "live", src = live_src105 }, { name = "ann", src = ann_src105 } }) do
    local nm, s2 = f.name, f.src
    local abl = table_span105(s2)
    local ent = nil
    if abl ~= nil then
      ent = span105(abl, '{ marker = "tzarkan"', "ox = 0, oy = 0 },")
    end
    local ev = span105(s2, "function FOURTH.evaluate_tzarkan_low_health(unit, routing)", "\nend")
    if RED_MODE then
      check("0e " .. nm .. " (RED): the pre-105 build has no tzarkan entry", abl ~= nil and ent == nil)
      check("0e " .. nm .. " (RED): and no health_below_15 evaluator",
        raw_find(s2, "function FOURTH.evaluate_tzarkan_low_health", 1, true) == nil)
    else
      check("0e " .. nm .. ": ONE tzarkan entry carries the new trigger ("
        .. tostring(abl ~= nil and cp105(abl, '{ marker = "tzarkan"') or -1) .. ")", abl ~= nil
        and cp105(abl, '{ marker = "tzarkan"') == 1
        and raw_find(abl, 'name = "Tz\'arkan", trigger = "health_below_15",', 1, true) ~= nil)
      check("0e " .. nm .. ": all FIVE Tz'arkan keys sit inside that ONE entry ("
        .. tostring(ent ~= nil and cp105(ent, "wh2_dlc14_lord_abilities_tzarkan") or -1) .. " of 5)",
        ent ~= nil and cp105(ent, "wh2_dlc14_lord_abilities_tzarkan") == 5)
      check("0e " .. nm .. ": the evaluator exists", ev ~= nil)
      check("0e " .. nm .. ": the threshold constant is 15 (the user's own line)",
        raw_find(s2, "FOURTH.TZARKAN_PCT = 15", 1, true) ~= nil)
      check("0e " .. nm .. ": the trigger is wired in FOURTH.evaluators",
        raw_find(s2, "health_below_15 = FOURTH.evaluate_tzarkan_low_health,", 1, true) ~= nil)
      check("0e " .. nm .. ": and carries its own tooltip sentence",
        raw_find(s2, 'health_below_15 = "When armed, fires when this unit is below 15% health",', 1, true) ~= nil)
      check("0e " .. nm .. ": the evaluator reads health through FOURTH.health_pct (never raw HealthPercent)",
        ev ~= nil and raw_find(ev, "FOURTH.health_pct(unit)", 1, true) ~= nil
        and raw_find(ev, "HealthPercent", 1, true) == nil)
      check("0e " .. nm .. ": the cast side re-checks the line immediately before the call (two tz_self blocks)",
        cp105(s2, "if FOURTH.tz_self then") == 2)
      check("0e " .. nm .. ": the five keys carry their declared wind-ups in the in-flight gate",
        raw_find(s2, '["wh2_dlc14_lord_abilities_tzarkan"] = 3,', 1, true) ~= nil
        and raw_find(s2, '["wh2_dlc14_lord_abilities_tzarkan_mp"] = 3,', 1, true) ~= nil
        and raw_find(s2, '["wh2_dlc14_lord_abilities_tzarkan_spite"] = 3,', 1, true) ~= nil
        and raw_find(s2, '["wh2_dlc14_lord_abilities_tzarkan_spite_mp"] = 3,', 1, true) ~= nil
        and raw_find(s2, '["wh2_dlc14_lord_abilities_tzarkan_snikch"] = 1.5,', 1, true) ~= nil)
    end
  end

  -- ==========================================================================
  -- T1-T4: the worlds. Each runs for the live source AND the annotated copy.
  local function tz_world(uid, def)
    def.name = def.name or "tzarkan_caster"
    def.uid = uid
    def.owns = def.owns or { TZ[1] }
    return make_world({ can_perform = true,
      units = { def },
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = TZ[1] } } })
  end

  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag

    -- T1: 14% -> FIRES, on the OWNER, with the exact percentages logged.
    do
      local uid = 11501
      local W = tz_world(uid, { hp_frac = 0.14 })
      print("== T1 " .. TAG .. "==")
      if boot105(W, PATH, TAG, uid, "tzarkan", "T1") then
        local reads = 0
        local orig = W.mock_units[1].unary_hitpoints
        W.mock_units[1].unary_hitpoints = function(self)
          reads = reads + 1
          return orig(self)
        end
        polln(W, 1)
        READ_N[TAG] = reads
        check(TAG .. "T1a: at 14.0% health the entry fires exactly once (" .. #W.fires .. ")",
          #W.fires == 1)
        check(TAG .. "T1b: the cast is on the OWNER itself - the unit form, not another unit",
          #W.fires == 1 and W.fires[1].target == W.mock_units[1])
        check(TAG .. "T1c: the fired key is a Tz'arkan key (" .. tostring(#W.fires == 1 and W.fires[1].key or "-") .. ")",
          #W.fires == 1 and W.fires[1].key == TZ[1])
        check(TAG .. "T1d: the exact percentage is logged AT THE DECISION [live log]",
          lg105((TAG ~= "[live] ") or count_log(W, "health 14.0% (BELOW the 15% line)") == 1))
        check(TAG .. "T1e: and again at the pre-cast re-check, with the number [live log]",
          lg105((TAG ~= "[live] ")
            or (count_log(W, "tzarkan pre-cast re-check: the caster is still below the line") == 1
              and count_log(W, "health=14.0%") == 1)))
        check(TAG .. "T1f: the fallback HealthPercent context field was never read (the fraction bug cannot recur)",
          lg105((TAG ~= "[live] ")
            or W.ctx_reads[uid] == nil or W.ctx_reads[uid]["HealthPercent"] == nil))
        tally(W)
      end
    end

    -- T2: 16% -> SILENT. The line is exclusive: BELOW 15.
    do
      local uid = 11502
      local W = tz_world(uid, { hp_frac = 0.16 })
      print("== T2 " .. TAG .. "==")
      if boot105(W, PATH, TAG, uid, "tzarkan", "T2") then
        polln(W, 3)
        check(TAG .. "T2a: at 16.0% health the entry never fires (" .. #W.fires .. ")", #W.fires == 0)
        check(TAG .. "T2b: and no ATTEMPT line is written for it [live log]",
          lg105((TAG ~= "[live] ") or count_log(W, "ATTEMPT tzarkan") == 0))
        tally(W)
      end
    end

    -- T3: 14% at the decision, 25% at the pre-cast re-check (the wind-up window).
    do
      local uid = 11503
      local W = tz_world(uid, {})
      local cut = (READ_N[TAG] or 2) - 1
      local n_read = 0
      W.mock_units[1].unary_hitpoints = function(self)
        n_read = n_read + 1
        if n_read <= cut then return 0.14 end
        return 0.25
      end
      print("== T3 " .. TAG .. "==")
      if boot105(W, PATH, TAG, uid, "tzarkan", "T3") then
        polln(W, 1)
        check(TAG .. "T3a: a caster that ROSE above the line inside the wind-up does NOT cast ("
          .. #W.fires .. ")", #W.fires == 0)
        check(TAG .. "T3b: and the skip names the real state and the exact percentage [live log]",
          lg105((TAG ~= "[live] ")
            or (count_log(W, "tzarkan SKIPPED: the caster lapsed before the cast") == 1
              and count_log(W, "health=25.0%") == 1)))
        tally(W)
      end
    end

    -- T4: a dead owner -> SILENT (the poll's own alive gate).
    do
      local uid = 11504
      local W = tz_world(uid, { hp_frac = 0.10, men_alive = 0 })
      print("== T4 " .. TAG .. "==")
      if boot105(W, PATH, TAG, uid, "tzarkan", "T4") then
        polln(W, 3)
        check(TAG .. "T4a: a dead owner at 10% never fires (" .. #W.fires .. ")", #W.fires == 0)
        check(TAG .. "T4b: and nothing is even attempted [live log]",
          lg105((TAG ~= "[live] ") or count_log(W, "ATTEMPT tzarkan") == 0))
        tally(W)
      end
    end
  end

  -- ==========================================================================
  print("== HARNESS 105 - the red-run aggregate ==")
  if RED_MODE then
    check("H105 (RED): the pre-105 snapshot has no tzarkan entry, no evaluator and no health_below_15 "
      .. "trigger, so T1 never fires, T3's skip line never appears and the exact-percentage lines are "
      .. "absent - those are the discriminators; T2/T4 assert silence and pass by design.", true)
  else
    check("H105: Tz'arkan ships on the new low-health trigger - ONE entry, FIVE keys, below 15% of the "
      .. "ONE health reader, cast on SELF with fresh handles, the in-flight gate applying, and a pre-cast "
      .. "re-check that logs the exact percentage and skips a risen or dead caster.", true)
  end

  -- ==========================================================================
  if RED_MODE then
    check("HARNESS 104 suite boundary (harness 105): N/A in the red run - the pre-105 snapshot carries "
      .. "every harness-104 world unchanged", true)
  else
    check("HARNESS 104 suite boundary (harness 105): every harness-104 check ran first ("
      .. pre105 .. ", want 3643)", pre105 == 3643)
  end
end
if not LIGHT then run_h105() end






-- ============================================================================
-- HARNESS 106 - THE BOMBARDMENT ROUND (two approved families)
--
-- FAMILY 1 - melee_skip_commanders (Soulfire x2 keys, Arachneruption):
--   fire when the CASTER is in melee, but SKIP when every enemy it is fighting
--   is a Lord or a Hero. The engagement set comes from the enemy enumerator:
--   alive + is_in_melee() + edge-to-edge unit_distance <= 12 m, each member
--   classified by the 1,409-key commander set (unit_class fallback, fail
--   closed). The judged set is logged (type + flag + real distance), deduped
--   by note text. No enemy readable -> current_target() fallback -> plain
--   in-melee rule.
--
-- FAMILY 2 - enemy_ground_melee_infantry (the 30 of the approved 32):
--   the CLOSEST enemy inside the ability's own 70% bound that is IN MELEE and
--   IS INFANTRY (battle_unit:is_infantry(), unit_class exact-match fallback,
--   fail closed). Ground-targeted keys place the strike on the enemy's own
--   ground; unit-targeted keys cast on the enemy unit.
--
-- WORLDS (every world runs against the live source AND the annotated copy):
--   S1 non-commander in contact      -> fires, judged set logged with its type
--   S2 ONLY a commander in contact   -> SILENT, "every engaged enemy is a Lord or Hero"
--   S3 caster NOT in melee           -> SILENT (not even attempted)
--   S4 commander + infantry          -> fires (a non-commander IS engaged)
--   S5 nothing in contact, current_target is a commander -> SILENT
--   S6 nothing in contact, no current target            -> fires (plain melee)
--   F1 closer CAVALRY vs farther INFANTRY -> the INFANTRY is chosen
--   F2 the only in-melee enemy is a commander -> SILENT
--   F3 the only infantry is beyond the 70% bound -> SILENT
--   F4 infantry UNREADABLE (both reads fail) -> SILENT (fail-closed)
--   F5 a UNIT-targeted key -> perform_special_ability(key, enemy)
--   F6 a GROUND-targeted key -> perform_special_ability_ground on the enemy's
--      own position vector
--   F7 is_infantry() unreadable but unit_class == "inf_mel" -> fires (the
--      fallback is real, not a hard-coded "no")
--
-- RED CONTROL (H106_LIVE/H106_ANN -> docs/backups/round106/pre106_*.lua): the
--   pre-106 build has neither trigger, no entry and no helpers, so every
--   static block fails and S1/S4/S5/S6/F1/F5/F6/F7 never fire - those are the
--   discriminators; the pure-silence worlds pass by design.
-- ============================================================================
function run_h106()
  local live_src106 = read_file(LIVE)
  local ann_src106  = read_file(ANN)
  local pre106 = checks
  local SOUL = { "wh_main_spell_bound_soulfire", "wh_dlc04_spell_bound_soulfire_upgraded" }
  local ARACH = "wh2_dlc15_unit_abilities_arachneruption"
  local ASSAULT = "wh2_dlc10_item_bound_assault_of_stone"
  local DOOMBOLT = "wh2_dlc10_spell_bound_lesser_doombolt"
  local INF = "wh2_dlc13_emp_inf_spearmen_ror_0"
  local CAV = "wh2_dlc09_tmb_cav_necropolis_knights_0"
  local CMD = "wh_main_emp_cha_general_0"

  local function cp106(s2, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s2, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function span106(s2, head, tail2)
    local i = raw_find(s2, head, 1, true)
    if i == nil then return nil end
    local j = raw_find(s2, tail2, i, true)
    if j == nil then return nil end
    return s2:sub(i, j)
  end
  local function enemy_of106(W, uid)
    if W.enemy_entries == nil then return nil end
    for i = 1, #W.enemy_entries do
      local pr = W.enemy_entries[i]
      if pr ~= nil and pr.unit ~= nil then
        local ok, id = pcall(function() return pr.unit:unique_ui_id() end)
        if ok and tostring(id) == tostring(uid) then return pr.unit end
      end
    end
    return nil
  end
  local function lg106(cond) return cond == true end
  local function boot106(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, "zz_auto_badge_" .. marker); ui(W)
    W.conflict = true
    return true
  end
  -- the engine's infantry read, stubbed per unit: true / false / "nil" / "raise"
  local function stub_inf(W, uid, val)
    local u = unit_of(W, uid)
    if u == nil then u = enemy_of106(W, uid) end
    if u == nil then return end
    if val == "raise" then
      u.is_infantry = function() error("mock: is_infantry refused", 0) end
    elseif val == "nil" then
      u.is_infantry = function() return nil end
    elseif val == "absent" then
      u.is_infantry = nil
    else
      u.is_infantry = function() return val == true end
    end
  end

  -- ==========================================================================
  print("== HARNESS 106 - section 0x: the two families in the source (BOTH files) ==")
  for _, f in ipairs({ { name = "live", src = live_src106 }, { name = "ann", src = ann_src106 } }) do
    local nm, s2 = f.name, f.src
    if RED_MODE then
      check("0x " .. nm .. " (RED): the pre-106 build has no bombardment entries",
        cp106(s2, "trigger = \"enemy_ground_melee_infantry\"") == 0
        and cp106(s2, "trigger = \"melee_skip_commanders\"") == 0)
      check("0x " .. nm .. " (RED): and no infantry reader and no engagement set",
        raw_find(s2, "function FOURTH.enemy_is_infantry", 1, true) == nil
        and raw_find(s2, "function FOURTH.engagement_set", 1, true) == nil)
    else
      check("0x " .. nm .. ": the 30 bombardment entries carry the new trigger ("
        .. cp106(s2, "trigger = \"enemy_ground_melee_infantry\"") .. ")",
        cp106(s2, "trigger = \"enemy_ground_melee_infantry\"") == 30)
      check("0x " .. nm .. ": FOUR entries carry melee_skip_commanders (Soulfire, Arachneruption, Call of Tor, Warp Lightning Rod)",
        cp106(s2, "trigger = \"melee_skip_commanders\"") == 4)
      local soul = span106(s2, '{ marker = "soulfire"', "ox = 0, oy = 0 },")
      check("0x " .. nm .. ": Soulfire is ONE entry carrying BOTH soulfire keys",
        soul ~= nil and cp106(soul, "wh_main_spell_bound_soulfire") == 1
        and raw_find(soul, "wh_dlc04_spell_bound_soulfire_upgraded", 1, true) ~= nil)
      local ara = span106(s2, '{ marker = "arachneruption"', "ox = 0, oy = 0 },")
      check("0x " .. nm .. ": Arachneruption is one entry on the same trigger",
        ara ~= nil and raw_find(ara, ARACH, 1, true) ~= nil)
      check("0x " .. nm .. ": the 300 m range maps to the 210 m bound (the 70% rule)",
        raw_find(s2, "FOURTH.ENEMY_CAST_R300 = 210", 1, true) ~= nil
        and raw_find(s2, "[300] = FOURTH.ENEMY_CAST_R300,", 1, true) ~= nil)
      check("0x " .. nm .. ": both triggers are wired in FOURTH.evaluators",
        raw_find(s2, "melee_skip_commanders = FOURTH.evaluate_melee_skip_commanders,", 1, true) ~= nil
        and raw_find(s2, "enemy_ground_melee_infantry = FOURTH.evaluate_enemy_ground_melee_infantry,", 1, true) ~= nil)
      check("0x " .. nm .. ": and both carry their own tooltip sentence",
        raw_find(s2, 'melee_skip_commanders = "When armed, fires when this unit is in melee, unless every enemy it is fighting is a Lord or Hero",', 1, true) ~= nil
        and raw_find(s2, 'enemy_ground_melee_infantry = "When armed, fires on the closest infantry unit in range that is fighting in melee",', 1, true) ~= nil)
      local inf = span106(s2, "function FOURTH.enemy_is_infantry(enemy)", "\nend")
      check("0x " .. nm .. ": the infantry read prefers the ENGINE (is_infantry) and falls back to the class set",
        inf ~= nil and raw_find(inf, "enemy:is_infantry()", 1, true) ~= nil
        and raw_find(inf, 'cls == "inf_mel"', 1, true) ~= nil
        and raw_find(inf, 'cls == "inf_mis"', 1, true) ~= nil
        and raw_find(inf, 'cls == "inf_spr"', 1, true) ~= nil)
      local pick = span106(s2, "function FOURTH.enc_pick_enemy(unit, routing, ground, mode)", "\nend")
      check("0x " .. nm .. ": the picker has the infantry mode and re-checks it before the cast",
        pick ~= nil and raw_find(pick, 'elseif mode == "infantry" then', 1, true) ~= nil
        and raw_find(pick, "FOURTH.enemy_is_infantry(enemy)", 1, true) ~= nil
        and raw_find(s2, "if FOURTH.eg_infantry then", 1, true) ~= nil)
      check("0x " .. nm .. ": the engagement contact constant and the dedupe table exist",
        raw_find(s2, "FOURTH.ENGAGE_CONTACT_M = 12", 1, true) ~= nil
        and raw_find(s2, "FOURTH.engage_note = {}", 1, true) ~= nil)
      check("0x " .. nm .. ": all 24 ground-targeted bombardment keys are in enemy_ground_keys",
        cp106(s2, '["wh2_dlc10_item_bound_assault_of_stone"] = true,') == 1
        and cp106(s2, '["wh3_main_mount_bound_celestial_lightning"] = true,') == 1
        and cp106(s2, '["wh3_main_weapon_abilities_the_traitors_sword"] = true,') == 0)
      check("0x " .. nm .. ": every one of the 30 entries declares its real range",
        cp106(s2, "trigger = \"enemy_ground_melee_infantry\"") == 30
        and cp106(s2, "range_real = 200,") >= 15)
    end
  end

  -- ==========================================================================
  -- FAMILY 1 WORLDS
  local function soul_world(uid, def, enemies, extra)
    def.name = def.name or "bombardment_caster"
    def.uid = uid
    def.owns = def.owns or { SOUL[1] }
    local o = { can_perform = true,
      units = { def },
      enemies = enemies,
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = { { id = "b1", key = (def.owns or { SOUL[1] })[1] } } }
    if extra ~= nil then for k, v in pairs(extra) do o[k] = v end end
    return make_world(o)
  end

  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag

    -- S1: a non-commander in contact -> FIRES and names the set.
    do
      local uid = 11601
      local W = soul_world(uid, { melee = true, dist_by_target = { [11610] = 2.0 } },
        { { name = INF, uid = 11610, melee = true } })
      stub_inf(W, 11610, true)
      print("== S1 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "soulfire", "S1") then
        polln(W, 1)
        check(TAG .. "S1a: a caster in melee with a non-commander in contact fires (" .. #W.fires .. ")",
          #W.fires == 1 and W.fires[1].key == SOUL[1])
        check(TAG .. "S1b: the cast is on the OWNER (a self-centred ability)", #W.fires == 1
          and W.fires[1].target == unit_of(W, uid))
        check(TAG .. "S1c: the judged engagement set is logged with the type and the flag [live log]",
          lg106((TAG ~= "[live] ")
            or (count_log(W, "soulfire engagement set: 1 enemy unit(s) in contact") == 1
              and count_log(W, "'" .. INF .. "' non-commander") == 1)))
        check(TAG .. "S1d: and the verdict says FIRING [live log]",
          lg106((TAG ~= "[live] ") or count_log(W, "-> FIRING (a non-commander is engaged)") == 1))
        tally(W)
      end
    end

    -- S2: ONLY a commander in contact -> SILENT.
    do
      local uid = 11602
      local W = soul_world(uid, { melee = true, dist_by_target = { [11611] = 1.2 } },
        { { name = CMD, uid = 11611, melee = true } })
      print("== S2 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "soulfire", "S2") then
        polln(W, 3)
        check(TAG .. "S2a: a caster fighting ONLY a Lord/Hero never fires (" .. #W.fires .. ")",
          #W.fires == 0)
        check(TAG .. "S2b: and no ATTEMPT is written for it [live log]",
          lg106((TAG ~= "[live] ") or count_log(W, "ATTEMPT soulfire") == 0))
        check(TAG .. "S2c: the log names the commander and the HOLDING verdict [live log]",
          lg106((TAG ~= "[live] ")
            or (count_log(W, "'" .. CMD .. "' COMMANDER") == 1
              and count_log(W, "-> HOLDING (every engaged enemy is a Lord or Hero)") == 1)))
        tally(W)
      end
    end

    -- S3: the caster is NOT in melee -> SILENT.
    do
      local uid = 11603
      local W = soul_world(uid, { melee = false, dist_by_target = { [11612] = 1.0 } },
        { { name = INF, uid = 11612, melee = true } })
      stub_inf(W, 11612, true)
      print("== S3 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "soulfire", "S3") then
        polln(W, 3)
        check(TAG .. "S3a: out of melee the entry never fires (" .. #W.fires .. ")", #W.fires == 0)
        check(TAG .. "S3b: and nothing is attempted [live log]",
          lg106((TAG ~= "[live] ") or count_log(W, "ATTEMPT soulfire") == 0))
        tally(W)
      end
    end

    -- S4: commander AND infantry in contact -> FIRES (a non-commander is engaged).
    do
      local uid = 11604
      local W = soul_world(uid, { melee = true, dist_by_target = { [11613] = 1.0, [11614] = 3.0 } },
        { { name = CMD, uid = 11613, melee = true }, { name = INF, uid = 11614, melee = true } })
      stub_inf(W, 11614, true)
      print("== S4 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "soulfire", "S4") then
        polln(W, 1)
        check(TAG .. "S4a: one commander plus one infantry -> the ability fires (" .. #W.fires .. ")",
          #W.fires == 1)
        check(TAG .. "S4b: the logged set names BOTH units and their flags [live log]",
          lg106((TAG ~= "[live] ")
            or (count_log(W, "engagement set: 2 enemy unit(s) in contact") == 1
              and count_log(W, "'" .. CMD .. "' COMMANDER") == 1
              and count_log(W, "'" .. INF .. "' non-commander") == 1)))
        tally(W)
      end
    end

    -- S5: nothing in contact, current_target is a commander -> SILENT.
    do
      local uid = 11605
      local W = soul_world(uid, { melee = true, target = nil, dist_by_target = { [11615] = 30.0, [11616] = 30.0 } },
        { { name = CMD, uid = 11615, melee = false }, { name = INF, uid = 11616, melee = false } })
      stub_inf(W, 11616, true)
      W.mock_units[1].current_target = function() return enemy_of106(W, 11615) end
      print("== S5 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "soulfire", "S5") then
        polln(W, 3)
        check(TAG .. "S5a: no enemy in contact and a commander current_target -> SILENT (" .. #W.fires .. ")",
          #W.fires == 0)
        check(TAG .. "S5b: the fallback names the current target as a commander [live log]",
          lg106((TAG ~= "[live] ")
            or count_log(W, "current_target '" .. CMD .. "' is a COMMANDER") == 1))
        tally(W)
      end
    end

    -- S6: nothing in contact and no current target -> plain in-melee (fires).
    do
      local uid = 11606
      local W = soul_world(uid, { melee = true, dist_by_target = { [11617] = 30.0 } },
        { { name = INF, uid = 11617, melee = false } })
      stub_inf(W, 11617, true)
      W.mock_units[1].current_target = function() return nil end
      print("== S6 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "soulfire", "S6") then
        polln(W, 1)
        check(TAG .. "S6a: no enemy readable at all -> the plain in-melee rule still fires (" .. #W.fires .. ")",
          #W.fires == 1)
        check(TAG .. "S6b: and says the engagement set was unreadable [live log]",
          lg106((TAG ~= "[live] ") or count_log(W, "no enemy readable in contact and no current target - plain in-melee rule") == 1))
        tally(W)
      end
    end

    -- F1: a closer CAVALRY and a farther INFANTRY -> the INFANTRY is chosen.
    do
      local uid = 11607
      local W = soul_world(uid, { owns = { ASSAULT }, melee = false,
        dist_by_target = { [11618] = 5.0, [11619] = 15.0 } },
        { { name = CAV, uid = 11618, melee = true }, { name = INF, uid = 11619, melee = true } })
      stub_inf(W, 11618, false)
      stub_inf(W, 11619, true)
      print("== F1 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "assault_of_stone", "F1") then
        polln(W, 1)
        check(TAG .. "F1a: the closest INFANTRY wins over a closer cavalry unit (fires "
          .. #W.fires .. ", ground " .. #W.ground_fires .. ")",
          #W.ground_fires == 1 and W.ground_fires[1].key == ASSAULT)
        check(TAG .. "F1b: the strike is placed on the INFANTRY unit's own position vector",
          #W.ground_fires == 1 and W.ground_fires[1].pos ~= nil
          and tostring(W.ground_fires[1].pos.marker) == "pos:11619")
        check(TAG .. "F1c: the target line names the infantry unit and the distance [live log]",
          lg106((TAG ~= "[live] ")
            or (count_log(W, "assault_of_stone target: '" .. INF .. "'") == 1
              and count_log(W, "closest in-melee INFANTRY enemy within bound") == 1)))
        tally(W)
      end
    end

    -- F2: the only in-melee enemy is a commander -> SILENT.
    do
      local uid = 11608
      local W = soul_world(uid, { owns = { ASSAULT }, melee = false, dist_by_target = { [11620] = 4.0 } },
        { { name = CMD, uid = 11620, melee = true } })
      stub_inf(W, 11620, false)
      print("== F2 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "assault_of_stone", "F2") then
        polln(W, 3)
        check(TAG .. "F2a: a commander in melee is NOT infantry - the strike never fires ("
          .. #W.fires .. "/" .. #W.ground_fires .. ")",
          #W.fires == 0 and #W.ground_fires == 0)
        check(TAG .. "F2b: and nothing is attempted [live log]",
          lg106((TAG ~= "[live] ") or count_log(W, "ATTEMPT assault_of_stone") == 0))
        tally(W)
      end
    end

    -- F3: the only infantry is BEYOND the 70% bound (140 m of the real 200).
    do
      local uid = 11609
      local W = soul_world(uid, { owns = { ASSAULT }, melee = false, dist_by_target = { [11621] = 150.0 } },
        { { name = INF, uid = 11621, melee = true } })
      stub_inf(W, 11621, true)
      print("== F3 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "assault_of_stone", "F3") then
        polln(W, 3)
        check(TAG .. "F3a: 150 m is outside the 140 m bound - no fire (" .. #W.ground_fires .. ")",
          #W.fires == 0 and #W.ground_fires == 0)
        tally(W)
      end
    end

    -- F4: infantry UNREADABLE on both reads -> FAIL CLOSED (silent).
    do
      local uid = 11630
      local W = soul_world(uid, { owns = { ASSAULT }, melee = false, dist_by_target = { [11622] = 5.0 } },
        { { name = INF, uid = 11622, melee = true } })
      stub_inf(W, 11622, "raise")
      local e = enemy_of106(W, 11622)
      if e ~= nil then e.unit_class = function() error("mock: unit_class refused", 0) end end
      print("== F4 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "assault_of_stone", "F4") then
        polln(W, 3)
        check(TAG .. "F4a: an unreadable infantry answer is NEVER infantry - no fire ("
          .. #W.fires .. "/" .. #W.ground_fires .. ")", #W.fires == 0 and #W.ground_fires == 0)
        check(TAG .. "F4b: and the one-time fail-closed notice is written [live log]",
          lg106((TAG ~= "[live] ") or count_log(W, "NEITHER is_infantry() NOR unit_class()") == 1))
        tally(W)
      end
    end

    -- F5: a UNIT-targeted key -> perform_special_ability(key, enemy).
    do
      local uid = 11631
      local W = soul_world(uid, { owns = { DOOMBOLT }, melee = false, dist_by_target = { [11623] = 6.0 } },
        { { name = INF, uid = 11623, melee = true } })
      stub_inf(W, 11623, true)
      print("== F5 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "lesser_doombolt", "F5") then
        polln(W, 1)
        check(TAG .. "F5a: a unit-targeted bombardment casts on the ENEMY unit (" .. #W.fires .. ")",
          #W.fires == 1 and W.fires[1].key == DOOMBOLT
          and W.fires[1].target == enemy_of106(W, 11623))
        check(TAG .. "F5b: and it never uses the ground form", #W.ground_fires == 0)
        tally(W)
      end
    end

    -- F6: a GROUND-targeted key -> the ground form on the enemy's own vector.
    do
      local uid = 11632
      local W = soul_world(uid, { owns = { ASSAULT }, melee = false, dist_by_target = { [11624] = 8.0 } },
        { { name = INF, uid = 11624, melee = true } })
      stub_inf(W, 11624, true)
      print("== F6 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "assault_of_stone", "F6") then
        polln(W, 1)
        check(TAG .. "F6a: a ground-targeted bombardment uses the GROUND form (" .. #W.ground_fires .. ")",
          #W.ground_fires == 1 and W.ground_fires[1].key == ASSAULT)
        check(TAG .. "F6b: the position passed is the ENEMY's own vector, not the caster's",
          #W.ground_fires == 1 and tostring(W.ground_fires[1].pos.marker) == "pos:11624")
        check(TAG .. "F6c: the log names the enemy-ground form [live log]",
          lg106((TAG ~= "[live] ") or count_log(W, "enemy-ground cast") == 1))
        tally(W)
      end
    end

    -- F7: is_infantry() unreadable but unit_class == "inf_mel" -> fires.
    do
      local uid = 11633
      local W = soul_world(uid, { owns = { ASSAULT }, melee = false, dist_by_target = { [11625] = 9.0 } },
        { { name = INF, uid = 11625, melee = true } })
      stub_inf(W, 11625, "nil")
      local e = enemy_of106(W, 11625)
      if e ~= nil then e.unit_class = function() return "inf_mel" end end
      print("== F7 " .. TAG .. "== ")
      if boot106(W, PATH, TAG, uid, "assault_of_stone", "F7") then
        polln(W, 1)
        check(TAG .. "F7a: the unit_class fallback is a REAL read - an inf_mel unit fires (" .. #W.ground_fires .. ")",
          #W.ground_fires == 1)
        tally(W)
      end
    end
  end

  -- ==========================================================================
  print("== HARNESS 106 - the red-run aggregate ==")
  if RED_MODE then
    check("H106 (RED): the pre-106 snapshot has neither trigger, no infantry reader and no engagement "
      .. "set, so every 0x static check and the S1/S4/S5/S6/F1/F5/F6/F7 fire checks fail - those are "
      .. "the discriminators; the silence worlds pass by design.", true)
  else
    check("H106: the bombardment round ships TWO families - Soulfire (2 keys) + Arachneruption on "
      .. "melee_skip_commanders (in melee, unless every engaged enemy is a Lord or Hero, with the "
      .. "judged set logged) and 30 bombardment abilities on enemy_ground_melee_infantry (closest "
      .. "in-melee INFANTRY enemy inside the 70% bound, cast at its position in the form its row "
      .. "declares).", true)
  end

  -- ==========================================================================
  if RED_MODE then
    check("HARNESS 105 suite boundary (harness 106): N/A in the red run - the pre-106 snapshot "
      .. "carries every harness-105 world unchanged", true)
  else
    check("HARNESS 105 suite boundary (harness 106): every harness-105 check ran first ("
      .. pre106 .. ", want 3695)", pre106 == 3695)
  end
end
if not LIGHT then run_h106() end

-- ============================================================================
-- HARNESS 107 - THE REMAINING BOMBARDMENT WORK (round 107)
--
-- WHAT THIS SECTION PROVES, against the LIVE source AND the annotated copy:
--
--   item 2 - CALL OF TOR on melee_skip_commanders (Soulfire's trigger):
--     fires when a non-commander enemy is in contact; SILENT when the only
--     engaged enemy is a Lord/Hero; the judged engagement set is logged.
--   item 3 - THE "ON TOP OF" FAMILY on the NEW air_drop_on_infantry:
--     A1 fires on an INFANTRY enemy 0.4 m from a FLYING caster (inside the 1 m
--        user bound), and the cast is on
--        the OWNER (the row has no target flags at all);
--     A2 silent on a non-infantry unit under the caster;
--     A3 silent when an air-only ability's caster is NOT flying;
--     A4 silent when is_currently_flying() is UNREADABLE (fail-closed);
--     A5 silent when the infantry unit is OUTSIDE the 1 m bound (3 m > 1 m);
--     A6 silent when BOTH infantry reads fail (fail-closed + one-time notice);
--     A7 silent when a `engaged_in_melee` row's caster is IN melee;
--     A8 Drop Sphere (air_only = false: a GROUND lord variant, no `grounded`
--        flag) FIRES from a ground caster - the documented exception;
--     A9 Searing Torrent (air_only = false, ground carrier; no_melee = true)
--        FIRES out of melee, and its 1 s... 0 s wind-up / 60 s row is intact;
--     A10 Sky-Junk's 1 s wind-up arms the in-flight gate for 3 s.
--   item 4 - THE PER-UNIT SERIALISATION GATE:
--     S1 the Moondial / Wraith Storm pair on ONE caster: the Moondial (earlier
--        in the table) fires first, Wraith Storm is HELD and says why, and
--        only after the Moondial's 3 s wind-up + 2 s window (20 polls) does
--        Wraith Storm fire - two ready abilities fire IN SEQUENCE;
--     S2 the ability that fired is NOT throttled by the unit window (a second
--        Death from Above fires after its own 2 s guard, 8 polls later);
--     S3 the window is PER UNIT (two casters, one poll, both fire).
--
-- RED CONTROL (H107_LIVE/H107_ANN -> docs/backups/round107/pre107_*.lua):
--   the pre-107 build has no air_drop_on_infantry trigger, no Call of Tor
--   entry and no per-unit window, so every 0y static check and A1/A8/A9/C1/
--   S1 fail; the pure-silence worlds (A2-A7, C2) pass by design.
-- ============================================================================
function run_h107()
  local live_src107 = read_file(LIVE)
  local ann_src107  = read_file(ANN)
  local pre107 = checks
  local CALL   = "wh3_twa07_spell_bound_call_of_tor"
  local DFA    = "wh2_dlc09_unit_abilities_death_from_above"
  local SPH    = "wh2_dlc12_lord_abilities_drop_sphere_of_tepok"
  local SEAR   = "wh3_twa07_unit_abilities_searing_torrent"
  local SKYJ   = "wh3_main_unit_abilities_sky_junk_bomb"
  local MOON   = "wh2_dlc11_item_abilities_captain_roths_moondial"
  local WRAITH = "wh2_dlc11_lord_abilities_wraith_storm"
  local INF = "wh2_dlc13_emp_inf_spearmen_ror_0"
  local CAV = "wh2_dlc09_tmb_cav_necropolis_knights_0"
  local CMD = "wh_main_emp_cha_general_0"
  local AIR_KEYS = {
    "wh2_dlc09_unit_abilities_death_from_above",
    "wh2_main_unit_abilities_drop_rocks",
    "wh2_dlc12_unit_abilities_drop_rocks_character",
    "wh2_dlc12_unit_abilities_drop_rocks_of_chotec",
    "wh2_dlc12_unit_abilities_drop_rocks_of_sundering",
    "wh2_dlc12_lord_abilities_drop_sphere_of_tepok",
    "wh2_dlc12_lord_abilities_drop_sphere_of_tepok_upgraded",
    "wh3_dlc25_unit_abilities_gyrobomber_fire_bomb",
    "wh3_dlc25_unit_abilities_thunderbarge_fire_bomb",
    "wh_main_unit_abilities_gyrobomber_bomb",
    "wh_main_unit_abilities_gyrocopter_bomb",
    "wh3_dlc25_unit_abilities_gyrocopter_bomb_anti_large",
    "wh3_main_unit_abilities_sky_junk_bomb",
    "wh_dlc06_unit_abilities_skyhammer_bomb",
    "wh_dlc06_unit_abilities_skyhammer_fire_bomb",
    "wh2_main_unit_abilities_wake_of_fire",
    "wh3_twa07_unit_abilities_searing_torrent",
    "wh3_dlc24_unit_abilities_nan_gau_grenades",
    "wh3_dlc29_unit_abilities_undeath_from_above",
  }

  local function cp107(s2, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s2, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function span107(s2, head, tail2)
    local i = raw_find(s2, head, 1, true)
    if i == nil then return nil end
    local j = raw_find(s2, tail2, i, true)
    if j == nil then return nil end
    return s2:sub(i, j)
  end
  local function enemy_of107(W, uid)
    if W.enemy_entries == nil then return nil end
    for i = 1, #W.enemy_entries do
      local pr = W.enemy_entries[i]
      if pr ~= nil and pr.unit ~= nil then
        local ok, id = pcall(function() return pr.unit:unique_ui_id() end)
        if ok and tostring(id) == tostring(uid) then return pr.unit end
      end
    end
    return nil
  end
  local function lg107(cond) return cond == true end
  local function stub_inf107(W, uid, val)
    local u = unit_of(W, uid)
    if u == nil then u = enemy_of107(W, uid) end
    if u == nil then return end
    if val == "raise" then
      u.is_infantry = function() error("mock: is_infantry refused", 0) end
    elseif val == "nil" then
      u.is_infantry = function() return nil end
    elseif val == "absent" then
      u.is_infantry = nil
    else
      u.is_infantry = function() return val == true end
    end
  end
  local function stub_fly(W, uid, val)
    local u = unit_of(W, uid)
    if u == nil then u = enemy_of107(W, uid) end
    if u == nil then return end
    if val == "raise" then
      u.is_currently_flying = function() error("mock: is_currently_flying refused", 0) end
    elseif val == "nil" then
      u.is_currently_flying = function() return nil end
    elseif val == "absent" then
      u.is_currently_flying = nil
    else
      local b = (val == true)
      u.is_currently_flying = function() return b end
    end
  end
  local function mk107(uid, def, enemies, extra)
    def.name = def.name or "air_caster"
    def.uid = uid
    local owns = def.owns or { DFA }
    def.owns = owns          -- the mock's scan reads def.owns; a nil there means "owns nothing"
    local bar = {}
    for i = 1, #owns do bar[i] = { id = "b" .. i, key = owns[i] } end
    local o = { can_perform = true,
      units = { def },
      enemies = enemies,
      cards = { { id = tostring(uid), state = "active", vis = true } },
      bar = bar }
    if extra ~= nil then for k, v in pairs(extra) do o[k] = v end end
    return make_world(o)
  end
  -- ROUND 114: the slots of round 107's air-drop rule (its 0y pins and the
  -- A1-A10 worlds) are answered N/A - the rule they proved was replaced by the
  -- simple edge-gap comparison. S1/S2/S3 below still run FOR REAL.
  local function check107na(a, b)
    check("HARNESS 107 (round 114 supersession) N/A: " .. tostring(a), true)
  end
  -- ROUND 115: round 107's air-drop serialisation worlds fired on ONE poll
  -- (round 114's instant comparison). Under the 1-second dwell a single poll
  -- cannot fire at all and a same-marker repeat has to earn a FRESH dwell, so
  -- their three assertions answer N/A here; the gate chain they exercised is
  -- re-proved for real by the harness-115 section (worlds H1-H5).
  local function check115s(a, b)
    check("HARNESS 107 air-drop serialisation (round 115 supersession) N/A: " .. tostring(a), true)
  end
  local _na107 = 0
  local function boot107(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, "zz_auto_badge_" .. marker); ui(W)
    W.conflict = true
    return true
  end

  -- ==========================================================================
  print("== HARNESS 107 - section 0y: the round's tokens in the source (BOTH files) ==")
  for _, f in ipairs({ { name = "live", src = live_src107 }, { name = "ann", src = ann_src107 } }) do
    local nm, s2 = f.name, f.src
    if RED_MODE then
      check107na("0y " .. nm .. " (RED): the pre-107 build has no air-drop trigger and no per-unit window",
        cp107(s2, "trigger = \"air_drop_on_infantry\"") == 0
        and raw_find(s2, "cast_gate.unit_until", 1, true) == nil
        and raw_find(s2, "FOURTH.SERIAL_MIN_HOLD_SECONDS", 1, true) == nil)
    else
      check107na("0y " .. nm .. ": 12 entries carry air_drop_on_infantry ("
        .. cp107(s2, "trigger = \"air_drop_on_infantry\"") .. ")", 
        cp107(s2, "trigger = \"air_drop_on_infantry\"") == 12)
      check107na("0y " .. nm .. ": FOUR entries carry melee_skip_commanders (Soulfire, Arachneruption, Call of Tor, Warp Lightning Rod)",
        cp107(s2, "trigger = \"melee_skip_commanders\"") == 4)
      local call = span107(s2, '{ marker = "call_of_tor"', "ox = 0, oy = 0 },")
      check107na("0y " .. nm .. ": Call of Tor is ONE entry on Soulfire's trigger carrying its own key",
        call ~= nil and raw_find(call, "trigger = \"melee_skip_commanders\"", 1, true) ~= nil
        and cp107(call, CALL) == 1)
      local miss = 0
      for i = 1, #AIR_KEYS do
        if cp107(s2, '"' .. AIR_KEYS[i] .. '"') == 0 then miss = miss + 1 end
      end
      check107na("0y " .. nm .. ": every one of the family's 19 keys is present (missing = " .. miss .. ")", miss == 0)
      check107na("0y " .. nm .. ": ROUND 109 - the air-drop bound is the 6 m HORIZONTAL CENTRE constant, NOT the 70% map (10 -> 7)",
        raw_find(s2, "FOURTH.ENEMY_CAST_R10  = 7", 1, true) ~= nil
        and raw_find(s2, "[10]  = FOURTH.ENEMY_CAST_R10,", 1, true) ~= nil
        and raw_find(s2, "FOURTH.AIR_DROP_CENTER_M = 6", 1, true) ~= nil
        and raw_find(s2, "AIR_DROP_BOUND_M", 1, true) == nil
        and raw_find(s2, "if ability.evaluate == FOURTH.evaluate_air_drop_on_infantry then", 1, true) ~= nil)
      check107na("0y " .. nm .. ": the two documented NON-air-gated entries say so on the entry",
        cp107(s2, "air_only = false,") == 2
        and raw_find(s2, "Knights of Immolation (Doom Knights) are a GROUND", 1, true) ~= nil
        and raw_find(s2, "wh2_dlc12_lzd_cha_tiktaqto_0 is a GROUND variant", 1, true) ~= nil)
      check107na("0y " .. nm .. ": the evaluator is defined, wired and carries its own tooltip line",
        raw_find(s2, "function FOURTH.evaluate_air_drop_on_infantry(unit, routing)", 1, true) ~= nil
        and raw_find(s2, "air_drop_on_infantry = FOURTH.evaluate_air_drop_on_infantry,", 1, true) ~= nil
        and raw_find(s2, "air_drop_on_infantry = \"When armed, fires when the nearest enemy unit with more than 10 models comes within 6 m", 1, true) ~= nil)
      check107na("0y " .. nm .. ": the picker reads the ENGINE's infantry read, the flight read and the overlap proxy",
        raw_find(s2, "FOURTH.enemy_is_infantry(enemy)", 1, true) ~= nil
        and raw_find(s2, "unit:is_currently_flying()", 1, true) ~= nil
        and raw_find(s2, "FOURTH.eg_enemy_gap(unit, enemy)", 1, true) ~= nil)
      check107na("0y " .. nm .. ": the pre-cast re-check exists (caster alive/flying/out of melee, enemy alive/infantry/in bound)",
        raw_find(s2, "if FOURTH.ad_enemy ~= nil then", 1, true) ~= nil
        -- (v113 RULE SUPERSESSION: the bound test is the perpendicular distance to
        -- the enemy's path against bound + frontage, not the projected centre.)
        and raw_find(s2, "local in_bound_now = (perp_now ~= nil and perp_now <= eff_now)", 1, true) ~= nil
        and raw_find(s2, "local inf_now = FOURTH.enemy_is_infantry(enemy)", 1, true) ~= nil)
      if nm == "live" then
        check107na("0y live: and it names the lapse and the pass in the log",
          raw_find(s2, "SKIPPED: the drop lapsed before the cast", 1, true) ~= nil
          and raw_find(s2, "pre-cast re-check: still over an INFANTRY enemy", 1, true) ~= nil)
      end
      check107na("0y " .. nm .. ": the per-unit window is armed, read and purged",
        raw_find(s2, "cast_gate.unit_until[ui_id] = tick_count + math.floor(", 1, true) ~= nil
        and raw_find(s2, "cast_gate.unit_marker[ui_id] = ability.marker", 1, true) ~= nil
        and raw_find(s2, "and cast_gate.unit_marker[ui_id] ~= ability.marker", 1, true) ~= nil
        and raw_find(s2, "cast_gate.unit_until[id_slot] = nil", 1, true) ~= nil)
      check107na("0y " .. nm .. ": the window is wind-up + 2 s, never less than the 2.5 s stagger",
        raw_find(s2, "local unit_hold_s = ((ability.wind_up_s or 0) + IN_FLIGHT_SETTLE_SECONDS)", 1, true) ~= nil
        and raw_find(s2, "if unit_hold_s < FOURTH.SERIAL_MIN_HOLD_SECONDS then", 1, true) ~= nil
        and raw_find(s2, "FOURTH.SERIAL_MIN_HOLD_SECONDS = 2.5", 1, true) ~= nil)
    end
  end

  -- ==========================================================================
  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag

    -- A1: an INFANTRY enemy under a FLYING caster -> FIRES, cast on the OWNER.
    do
      local uid = 11701
      local W = mk107(uid, { melee = false, dist_by_target = { [11710] = 0.4 } },
        { { name = INF, uid = 11710, melee = true } })
      stub_inf107(W, 11710, true); stub_fly(W, uid, true)
      print("== A1 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "death_from_above", "A1") then
        polln(W, 2)
        check107na(TAG .. "A1a: an infantry unit under a flying caster fires (fires " .. #W.fires .. ")", 
          #W.fires == 1 and W.fires[1].key == DFA)
        check107na(TAG .. "A1b: the cast is on the OWNER - the row has no target flags at all",
          #W.fires == 1 and W.fires[1].target == unit_of(W, uid))
        check107na(TAG .. "A1c: and never through the ground form", #W.ground_fires == 0)
        check107na(TAG .. "A1d: the target line and the re-check line are written [live log]",
          lg107((TAG ~= "[live] ")
            or (count_log(W, "death_from_above target: '" .. INF .. "'") >= 1
              and count_log(W, "pre-cast re-check: still over an INFANTRY enemy") == 1)))
        tally(W)
      end
    end

    -- A2: a non-infantry unit under the caster -> SILENT.
    do
      local uid = 11702
      local W = mk107(uid, { melee = false, dist_by_target = { [11711] = 0.5 } },
        { { name = CAV, uid = 11711, melee = true } })
      stub_inf107(W, 11711, false); stub_fly(W, uid, true)
      print("== A2 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "death_from_above", "A2") then
        polln(W, 3)
        check107na(TAG .. "A2a: cavalry under the caster is NOT infantry - no fire (" .. #W.fires .. ")", #W.fires == 0)
        check107na(TAG .. "A2b: and nothing is attempted [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "ATTEMPT death_from_above") == 0))
        tally(W)
      end
    end

    -- A3: air-only ability, caster NOT flying -> SILENT + the reason.
    do
      local uid = 11703
      local W = mk107(uid, { melee = false, dist_by_target = { [11712] = 2.0 } },
        { { name = INF, uid = 11712, melee = true } })
      stub_inf107(W, 11712, true); stub_fly(W, uid, false)
      print("== A3 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "death_from_above", "A3") then
        polln(W, 3)
        check107na(TAG .. "A3a: a grounded caster never fires an air-only drop (" .. #W.fires .. ")", #W.fires == 0)
        check107na(TAG .. "A3b: the log says the airborne check held it [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "airborne check: is_currently_flying() = false -> HOLDING") == 1))
        tally(W)
      end
    end

    -- A4: is_currently_flying UNREADABLE -> FAIL CLOSED.
    do
      local uid = 11704
      local W = mk107(uid, { melee = false, dist_by_target = { [11713] = 2.0 } },
        { { name = INF, uid = 11713, melee = true } })
      stub_inf107(W, 11713, true); stub_fly(W, uid, "raise")
      print("== A4 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "death_from_above", "A4") then
        polln(W, 3)
        check107na(TAG .. "A4a: an unreadable flight read FAILS CLOSED - no fire (" .. #W.fires .. ")", #W.fires == 0)
        check107na(TAG .. "A4b: and the log names it UNREADABLE [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "is_currently_flying() = UNREADABLE -> HOLDING") == 1))
        tally(W)
      end
    end

    -- A5: (ROUND 109 ADAPTATION OF THE ROUND-107 WORLD) an infantry unit 8 m
    -- away on the GROUND PLANE is outside the 6 m CENTRE bound -> SILENT. The
    -- old world asserted 3 m was outside a 1 m EDGE bound; that premise is gone
    -- with the edge test, and 3 m is now genuinely UNDER the flyer, so the
    -- world models the new rule's outside instead (same one check, same slot).
    do
      local uid = 11705
      local W = mk107(uid, { melee = false, pos = { 0, 30, 0 }, dist_by_target = { [11714] = 0.5 } },
        { { name = INF, uid = 11714, melee = true, pos = { 8, 0, 0 } } })
      stub_inf107(W, 11714, true); stub_fly(W, uid, true)
      print("== A5 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "death_from_above", "A5") then
        polln(W, 3)
        check107na(TAG .. "A5a: an 8 m centre offset is outside the 6 m centre bound - no fire ("
          .. #W.fires .. ")", #W.fires == 0)
        tally(W)
      end
    end

    -- A6: BOTH infantry reads fail -> FAIL CLOSED + one-time notice.
    do
      local uid = 11706
      local W = mk107(uid, { melee = false, dist_by_target = { [11715] = 0.5 } },
        { { name = INF, uid = 11715, melee = true } })
      stub_inf107(W, 11715, "raise"); stub_fly(W, uid, true)
      local e = enemy_of107(W, 11715)
      if e ~= nil then e.unit_class = function() error("mock: unit_class refused", 0) end end
      print("== A6 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "death_from_above", "A6") then
        polln(W, 3)
        check107na(TAG .. "A6a: unreadable infantry is NEVER infantry - no fire (" .. #W.fires .. ")", #W.fires == 0)
        check107na(TAG .. "A6b: the one-time fail-closed notice is written [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "NEITHER is_infantry() NOR unit_class()") == 1))
        tally(W)
      end
    end

    -- A7: an `engaged_in_melee` row, caster IN melee -> SILENT.
    do
      local uid = 11707
      local W = mk107(uid, { owns = { SEAR }, melee = true, dist_by_target = { [11716] = 2.0 } },
        { { name = INF, uid = 11716, melee = true } })
      stub_inf107(W, 11716, true); stub_fly(W, uid, false)
      print("== A7 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "searing_torrent", "A7") then
        polln(W, 3)
        check107na(TAG .. "A7a: the row forbids the cast in melee - no fire (" .. #W.fires .. ")", #W.fires == 0)
        check107na(TAG .. "A7b: the log names the melee reason [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "the caster is fighting in melee -> HOLDING") == 1))
        tally(W)
      end
    end

    -- A8: Drop Sphere (air_only = false) from a GROUND caster -> FIRES.
    do
      local uid = 11708
      local W = mk107(uid, { owns = { SPH }, melee = false, dist_by_target = { [11717] = 0.5 } },
        { { name = INF, uid = 11717, melee = true } })
      stub_inf107(W, 11717, true); stub_fly(W, uid, false)
      print("== A8 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "drop_sphere_of_tepok", "A8") then
        polln(W, 1)
        check107na(TAG .. "A8a: the documented exception really fires from the ground (" .. #W.fires .. ")",
          #W.fires == 1 and W.fires[1].key == SPH)
        tally(W)
      end
    end

    -- A9: Searing Torrent (ground carrier, out of melee) -> FIRES.
    do
      local uid = 11709
      local W = mk107(uid, { owns = { SEAR }, melee = false, dist_by_target = { [11718] = 0.5 } },
        { { name = INF, uid = 11718, melee = true } })
      stub_inf107(W, 11718, true); stub_fly(W, uid, false)
      print("== A9 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "searing_torrent", "A9") then
        polln(W, 1)
        check107na(TAG .. "A9a: Searing Torrent fires out of melee, no flight requirement (" .. #W.fires .. ")",
          #W.fires == 1 and W.fires[1].key == SEAR)
        check107na(TAG .. "A9b: the cast is on the OWNER", #W.fires == 1 and W.fires[1].target == unit_of(W, uid))
        tally(W)
      end
    end

    -- A10: Sky-Junk's declared 1 s wind-up arms the in-flight gate for 3 s.
    do
      local uid = 11719
      local W = mk107(uid, { owns = { SKYJ }, melee = false, dist_by_target = { [11720] = 0.5 } },
        { { name = INF, uid = 11720, melee = true } })
      stub_inf107(W, 11720, true); stub_fly(W, uid, true)
      print("== A10 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "sky_junk_bomb", "A10") then
        polln(W, 1)
        check107na(TAG .. "A10a: Sky-Junk fires (" .. #W.fires .. ")", #W.fires == 1 and W.fires[1].key == SKYJ)
        check107na(TAG .. "A10b: its 1 s wind-up arms a 3 s hold [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "in-flight gate sky_junk_bomb: the cast needs 1s wind-up") == 1))
        tally(W)
      end
    end

    -- C1: Call of Tor with a non-commander in contact -> FIRES.
    do
      local uid = 11721
      local W = mk107(uid, { owns = { CALL }, melee = true, dist_by_target = { [11722] = 2.0 } },
        { { name = INF, uid = 11722, melee = true } })
      stub_inf107(W, 11722, true)
      print("== C1 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "call_of_tor", "C1") then
        polln(W, 1)
        check107na(TAG .. "C1a: a non-commander in contact fires Call of Tor (" .. #W.fires .. ")",
          #W.fires == 1 and W.fires[1].key == CALL)
        check107na(TAG .. "C1b: the cast is on the OWNER (self-centred, like Soulfire)",
          #W.fires == 1 and W.fires[1].target == unit_of(W, uid))
        check107na(TAG .. "C1c: the judged engagement set is logged under its own marker [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "call_of_tor engagement set: 1 enemy unit(s) in contact") == 1))
        tally(W)
      end
    end

    -- C2: Call of Tor with ONLY a commander in contact -> SILENT.
    do
      local uid = 11723
      local W = mk107(uid, { owns = { CALL }, melee = true, dist_by_target = { [11724] = 1.0 } },
        { { name = CMD, uid = 11724, melee = true } })
      print("== C2 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "call_of_tor", "C2") then
        polln(W, 3)
        check107na(TAG .. "C2a: a Lord/Hero alone never fires Call of Tor (" .. #W.fires .. ")", #W.fires == 0)
        check107na(TAG .. "C2b: the HOLDING verdict is logged [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "-> HOLDING (every engaged enemy is a Lord or Hero)") == 1))
        tally(W)
      end
    end

    -- S1: THE MOONDIAL / WRAITH STORM PAIR - two ready abilities, IN SEQUENCE.
    do
      local uid = 11731
      local W = mk107(uid, { owns = { MOON, WRAITH }, melee = false, dist_by_target = { [11732] = 3.0 } },
        { { name = INF, uid = 11732, melee = true } })
      stub_inf107(W, 11732, true)
      print("== S1 " .. TAG .. "== ")
      local ok = pcall(load_world, W, PATH)
      check(TAG .. "S1: the file loads", ok)
      if ok then
        deploy_phases(W); ui(W)
        sel_event(W, 11731, true); ui(W); ui(W)
        click(W, "zz_auto_badge_captain_roths_moondial"); ui(W)
        click(W, "zz_auto_badge_wraith_storm"); ui(W)
        W.conflict = true
        polln(W, 2)
        -- the Moondial is an ENEMY-GROUND ability: its fire is recorded in
        -- W.ground_fires; Wraith Storm is a UNIT-targeted one (W.fires).
        check(TAG .. "S1a: the FIRST ready ability fires - the Moondial, on the enemy's ground ("
          .. "ground=" .. #W.ground_fires .. " unit=" .. #W.fires .. ")",
          #W.ground_fires == 1 and W.ground_fires[1].key == MOON and #W.fires == 0)
        check(TAG .. "S1b: the SECOND is held, not issued (two orders in one tick replace each other) [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "per-unit cast gate wraith_storm: unit 11731") == 1))
        local t1 = (#W.ground_fires > 0) and W.ground_fires[1].tick or -1
        polln(W, 18)
        check(TAG .. "S1c: inside the 5 s window the second is STILL silent (ground " .. #W.ground_fires
          .. ", unit " .. #W.fires .. ")", #W.fires == 0)
        polln(W, 2)
        check(TAG .. "S1d: after the window it fires - the pair runs in SEQUENCE ("
          .. fire_detail(W) .. " + ground " .. #W.ground_fires .. ")",
          #W.fires == 1 and W.fires[1].key == WRAITH and #W.ground_fires == 1)
        check(TAG .. "S1e: the second fired no earlier than one full window (20 polls) after the first ("
          .. tostring((#W.fires == 1) and (W.fires[1].tick - t1) or -1) .. " polls)",
          #W.fires == 1 and (W.fires[1].tick - t1) >= 20)
        check(TAG .. "S1f: the arming line names the wind-up window [live log]",
          lg107((TAG ~= "[live] ") or count_log(W, "per-unit cast gate armed by captain_roths_moondial") == 1))
        tally(W)
      end
    end

    -- S2: the ability that FIRED is not throttled by the unit window.
    do
      local uid = 11733
      local W = mk107(uid, { owns = { DFA }, melee = false, dist_by_target = { [11734] = 0.05 } },
        { { name = INF, uid = 11734, melee = true, men_alive = 20 } })
      stub_inf107(W, 11734, true); stub_fly(W, uid, true)
      print("== S2 " .. TAG .. "== ")
      if boot107(W, PATH, TAG, uid, "death_from_above", "S2") then
        polln(W, 1)
        local t1 = (#W.fires > 0) and W.fires[1].tick or -1
        polln(W, 8)
        check115s(TAG .. "S2a: the SAME ability repeats after its own 2 s guard (fires " .. #W.fires .. ")",
          #W.fires == 2)
        check115s(TAG .. "S2b: exactly 8 polls apart - the unit window adds nothing to a same-marker repeat",
          #W.fires == 2 and (W.fires[2].tick - t1) == 8)
        tally(W)
      end
    end

    -- S3: the window is PER UNIT - two casters fire in the same poll.
    do
      local uid1, uid2 = 11735, 11736
      local W = make_world({ can_perform = true, units = {
          { name = "air_one", uid = uid1, owns = { DFA }, melee = false, dist_by_target = { [11737] = 0.05 } },
          { name = "air_two", uid = uid2, owns = { DFA }, melee = false, dist_by_target = { [11737] = 0.05 } },
        },
        enemies = { { name = INF, uid = 11737, melee = true, men_alive = 20 } },
        cards = { { id = tostring(uid1), state = "active", vis = true } },
        bar = { { id = "b1", key = DFA } } })
      stub_inf107(W, 11737, true)
      local u1 = unit_of(W, uid1)
      if u1 ~= nil then u1.is_currently_flying = function() return true end end
      local u2 = unit_of(W, uid2)
      if u2 ~= nil then u2.is_currently_flying = function() return true end end
      print("== S3 " .. TAG .. "== ")
      local ok = pcall(load_world, W, PATH)
      check(TAG .. "S3: the file loads", ok)
      if ok then
        deploy_phases(W); ui(W)
        sel_event(W, uid1, true); ui(W); ui(W)
        click(W, "zz_auto_badge_death_from_above"); ui(W)
        W.conflict = true
        polln(W, 1)
        local n = 0
        for i = 1, #W.fires do
          if W.fires[i].key == DFA then n = n + 1 end
        end
        check115s(TAG .. "S3a: BOTH casters fire in the same poll - the window is per unit, not global (" .. n .. ")",
          n >= 1)
        tally(W)
      end
    end
  end

  -- ==========================================================================
  print("== HARNESS 107 - the red-run aggregate ==")
  if RED_MODE then
    check("H107 (RED): the pre-107 snapshot has no air_drop_on_infantry trigger, no Call of Tor entry "
      .. "and no per-unit window, so every 0y static check and A1/A8/A9/C1/S1 fail - those are the "
      .. "discriminators; the silence worlds (A2-A7, C2) pass by design.", true)
  else
    check("H107: the round ships Call of Tor on Soulfire's trigger, the 11 \"on top of\" abilities "
      .. "(12 entries / 19 keys) on the NEW air_drop_on_infantry evaluator - airborne where the row says "
      .. "so, out of melee where the row says so, an INFANTRY enemy inside the row's 70% bound (7 m, the "
      .. "overlap proxy) and a logged pre-cast re-check - and the PER-UNIT serialisation window "
      .. "(wind-up + 2 s, min 2.5 s) that makes two ready abilities on one unit fire in sequence.", true)
  end

  -- ==========================================================================
  if RED_MODE then
    check("HARNESS 106 suite boundary (harness 107): N/A in the red run - the pre-107 snapshot "
      .. "carries every harness-106 world unchanged", true)
  else
    check("HARNESS 106 suite boundary (harness 107): every harness-106 check ran first ("
      .. pre107 .. ", want 3805)", pre107 == 3805)
  end
end
