-- ============================================================================
-- HARNESS 114 - THE AIR-DROP RULE IS ONE COMPARISON, AND A 0.2 s FAST PASS.
--
-- THE USER'S RULING, verbatim:
--   "1. I want the trigger to be checked much more frequently when armed and
--    less than 30 meters from a valid enemy unit.
--    2. Valid units are those who have more than 10 entities.
--    3. I trigger the moment distance between edges is below 0.1 meters.
--    That's it."
--   "1. Remove the 'and it is infantry'. No need for it now.
--    2. Current count 3. Let's try with 0.2 s for now."
--
-- THE RULE THE WORLDS BELOW PROVE:
--   candidate = alive and number_of_men_alive() > AIR_DROP_MIN_MEN (10)
--   valid     = its unit_distance() is readable
--   chosen    = the NEAREST valid candidate
--   FIRE      = unit_distance(caster, chosen) < AIR_DROP_EDGE_M (0.10 m)
--
-- PINS (asserted against BOTH files in section 0):
--     EDGE_M  AIR_DROP_EDGE_M  = 0.1
--     MIN_MEN AIR_DROP_MIN_MEN = 10
--     NEAR_M  AIR_DROP_NEAR_M  = 30
--     FAST_S  AIR_DROP_FAST_S  = 0.2
-- and the RETIRED constants/helpers must be GONE (listed in section 0).
--
-- RED CONTROL (H117_LIVE / H117_ANN -> docs/backups/round114/pre114_*.lua, the
-- round-113 build): there is no ad_nearest, no AIR_DROP_EDGE_M and no fast
-- pass, so every 0 check and every A-K world fails as designed.
-- ============================================================================
function run_h114()
  if os.getenv("H117_LIVE") ~= nil then LIVE = os.getenv("H117_LIVE") end
  if os.getenv("H117_ANN") ~= nil then ANN = os.getenv("H117_ANN") end
  local red114 = (os.getenv("H117_LIVE") ~= nil) or (os.getenv("H117_ANN") ~= nil)
  local live_src = read_file(LIVE)
  local ann_src = read_file(ANN)
  local pre114 = checks
  local DFA = "wh2_dlc09_unit_abilities_death_from_above"
  local CAV = "wh_main_cav_emp_knights"
  local LORD = "wh_main_lord_emp_general"
  local OTHER = "wh3_main_character_abilities_deadly_onslaught"

  local function cp(s2, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s2, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function span(s2, head, tail2)
    local i = raw_find(s2, head, 1, true)
    if i == nil then return nil end
    local j = raw_find(s2, tail2, i, true)
    if j == nil then return nil end
    return s2:sub(i, j)
  end
  local function lg(cond) return cond == true end
  local function cl(W, frag) return count_log(W, frag) end
  -- unit_distance is called ON THE CASTER with the enemy as its argument, so the
  -- mock answer lives on the caster: dm = { [enemy_uid] = metres }, or dseq =
  -- { d1, d2, ... } for a per-READ sequence, or draise for an unreadable read.
  local function mk(uid, def, enemies, dm, dseq, draise)
    def.name = def.name or "sky_junk"
    def.uid = uid
    def.owns = def.owns or { DFA }
    if dm ~= nil then def.dist_by_target = dm end
    if dseq ~= nil then def.dist_seq = dseq end
    if draise then def.dist_raises = true end
    local bar = {}
    for i = 1, #def.owns do bar[i] = { id = "b" .. i, key = def.owns[i] } end
    local W = make_world({ can_perform = true, units = { def }, enemies = enemies,
      cards = { { id = tostring(uid), state = "active", vis = true } }, bar = bar })
    -- the air-drop rows are air-only: the caster must answer flying = true
    local u = unit_of(W, uid)
    if u ~= nil then u.is_currently_flying = function() return true end end
    return W
  end
  local function boot(W, PATH, TAG, uid, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, "zz_auto_badge_death_from_above"); ui(W)
    W.conflict = true
    return true
  end
  local function fastn(W, n)
    if W.fast_fn == nil then return false end
    for _ = 1, n do W.fast_fn() end
    return true
  end

  -- ==========================================================================
  print("== HARNESS 114 - section 0: the four pins, and what was RETIRED (BOTH files) ==")
  for _, f in ipairs({ { name = "live", src = live_src }, { name = "ann", src = ann_src } }) do
    local nm, s2 = f.name, f.src
    local pick = span(s2, "function FOURTH.ad_pick(unit, routing)",
      "\nfunction FOURTH.evaluate_air_drop_on_infantry")
    local near = span(s2, "function FOURTH.ad_nearest(unit)", "\nfunction FOURTH.ad_pick")
    local fast = span(s2, "function FOURTH.ad_fast_pass()", "\nbm:repeat_callback(poll, POLL_MS, POLL_NAME)")

    check("0 " .. nm .. ": the FOUR constants are defined EXACTLY ONCE (6 m CENTRE / 10 men / 30 m / 0.2 s)",
      cp(s2, "\nFOURTH.AIR_DROP_CENTER_M = 6.0\n") == 1
      and cp(s2, "\nFOURTH.AIR_DROP_MIN_MEN = 10\n") == 1
      and cp(s2, "\nFOURTH.AIR_DROP_NEAR_M = 30\n") == 1
      and cp(s2, "\nFOURTH.AIR_DROP_FAST_S = 0.2\n") == 1)
    -- (the round-114 header comment still NAMES the retired constants as history,
    -- so this counts the LIVE form - "FOURTH.<name>" - which is what code used)
    check("0 " .. nm .. ": the FOUR DIALS, AIR_DROP_INHERIT and the frontage constants are GONE (the 6 m CENTRE bound is BACK)",
      cp(s2, "FOURTH.AIR_DROP_CENTER_M") >= 8
      and cp(s2, "FOURTH.AIR_DROP_DELAY_S") == 0
      and cp(s2, "FOURTH.AIR_DROP_ENEMY_LEAD") == 0
      and cp(s2, "FOURTH.AIR_DROP_CASTER_DELAY_S") == 0
      and cp(s2, "FOURTH.AIR_DROP_CASTER_LEAD") == 0
      and cp(s2, "FOURTH.AIR_DROP_INHERIT") == 0
      and cp(s2, "FOURTH.AIR_DROP_MODEL_RADIUS_M") == 0
      and cp(s2, "FOURTH.AIR_DROP_RANKS") == 0
      and cp(s2, "FOURTH.AIR_DROP_FRONTAGE_MIN_M") == 0
      and cp(s2, "FOURTH.AIR_DROP_FRONTAGE_MAX_M") == 0
      and cp(s2, "\nFOURTH.AIR_DROP_CENTER_M = 6.0\n") == 1)
    check("0 " .. nm .. ": the projection / frontage / segment helpers are GONE (11), the CENTRE helper is BACK",
      cp(s2, "function FOURTH.ad_frontage(") == 0
      and cp(s2, "function FOURTH.ad_frontage_text(") == 0
      and cp(s2, "function FOURTH.ad_seg_dist(") == 0
      and cp(s2, "function FOURTH.ad_velocity(") == 0
      and cp(s2, "function FOURTH.ad_lead(") == 0
      and cp(s2, "function FOURTH.ad_project(") == 0
      and cp(s2, "function FOURTH.ad_dial_text(") == 0
      and cp(s2, "function FOURTH.ad_single_say(") == 0
      and cp(s2, "function FOURTH.ad_single_clear(") == 0
      and cp(s2, "function FOURTH.ad_centre_gap(") == 1
      and cp(s2, "function FOURTH.ad_pos(") == 0
      and cp(s2, "function FOURTH.ad_sep(") == 0)
    check("0 " .. nm .. ": NOTHING else called them either (no ad_lead / ad_seg_dist / ad_frontage call sites)",
      cp(s2, "FOURTH.ad_lead(") == 0 and cp(s2, "FOURTH.ad_seg_dist(") == 0
      and cp(s2, "FOURTH.ad_frontage(") == 0 and cp(s2, "FOURTH.ad_centre_gap(") == 4
      and cp(s2, "FOURTH.ad_dial_text(") == 0 and cp(s2, "FOURTH.ad_project(") == 0)
    check("0 " .. nm .. ": ad_nearest is the WHOLE filter - alive, > AIR_DROP_MIN_MEN, readable distance",
      near ~= nil
      and raw_find(near, "enemy:number_of_men_alive()", 1, true) ~= nil
      and raw_find(near, "alive > FOURTH.AIR_DROP_MIN_MEN", 1, true) ~= nil
      and raw_find(near, "FOURTH.ad_centre_gap(unit, enemy)", 1, true) ~= nil
      and raw_find(near, "d < best_d", 1, true) ~= nil)
    check("0 " .. nm .. ": ad_nearest applies NO infantry test and NO initial-count test",
      near ~= nil and raw_find(near, "enemy_is_infantry", 1, true) == nil
      and raw_find(near, "initial_number_of_men", 1, true) == nil
      and raw_find(near, "ordered_width", 1, true) == nil)
    check("0 " .. nm .. ": the DECISION is one comparison (dist >= AIR_DROP_CENTER_M -> NOT YET)",
      pick ~= nil
      and raw_find(pick, "if dist >= FOURTH.AIR_DROP_CENTER_M then", 1, true) ~= nil
      and raw_find(pick, "enemy_is_infantry", 1, true) == nil
      and raw_find(pick, "initial_number_of_men", 1, true) == nil
      and raw_find(pick, "AIR_DROP_DELAY_S", 1, true) == nil)
    check("0 " .. nm .. ": the decision carries the ui id, the type, the entity count and the exact CENTRE",
      pick ~= nil
      and raw_find(pick, "nearest valid:'", 1, true) ~= nil
      and raw_find(pick, 'FOURTH.ad_say(unit, marker, "nearest valid:\'', 1, true) ~= nil
      and raw_find(pick, "' entities=", 1, true) ~= nil
      and raw_find(pick, '" centre="', 1, true) ~= nil
      and raw_find(pick, '"m (need < "', 1, true) ~= nil
      and ((nm ~= "live")
        or raw_find(pick, "ad_tag(unit)", 1, true) == nil))
    check("0 " .. nm .. ": ONE copy of the gates + cast for BOTH timers (FOURTH.try_pair: 1 def + 2 calls)",
      cp(s2, "function FOURTH.try_pair(") == 1 and cp(s2, "FOURTH.try_pair(") == 3)
    check("0 " .. nm .. ": the fast pass runs ONLY the air-drop list, gated on AIR_DROP_NEAR_M",
      fast ~= nil
      and raw_find(fast, "local list = FOURTH.ad_fast_abilities", 1, true) ~= nil
      and raw_find(fast, "#list", 1, true) ~= nil
      and raw_find(fast, "dist < FOURTH.AIR_DROP_NEAR_M", 1, true) ~= nil
      and raw_find(fast, "ability.evaluate(unit, routing)", 1, true) ~= nil
      and raw_find(fast, "FOURTH.try_pair(", 1, true) ~= nil
      and raw_find(fast, "ABILITIES", 1, true) == nil)
    check("0 " .. nm .. ": the transition is a CHANGE gate (near ~= was), so it cannot log per tick",
      fast ~= nil
      and raw_find(fast, "if near ~= was then", 1, true) ~= nil
      and raw_find(fast, "FOURTH.ad_fast_on[uid] = near", 1, true) ~= nil
      and ((nm ~= "live")
        or (raw_find(fast, '"fast poll: ON (nearest valid "', 1, true) ~= nil
          and raw_find(fast, '"fast poll: OFF"', 1, true) ~= nil)))
    check("0 " .. nm .. ": the fast timer is registered on AIR_DROP_FAST_S and POLL_MS is UNTOUCHED",
      cp(s2, "local POLL_MS = 250") == 1
      and cp(s2, "math.floor(FOURTH.AIR_DROP_FAST_S * 1000)") == 1
      and cp(s2, 'bm:repeat_callback(poll, POLL_MS, POLL_NAME)') == 1
      and cp(s2, "zz_test_deadly_onslaught_air_drop_fast") == 1)
    check("0 " .. nm .. ": air_only / no_melee / the self-centred cast / fail-closed are ALL still in place",
      raw_find(s2, "is_currently_flying()", 1, true) ~= nil
      and raw_find(s2, "is_in_melee()", 1, true) ~= nil
      and raw_find(s2, "FOURTH.ad_air_only", 1, true) ~= nil
      and raw_find(s2, "FOURTH.ad_no_melee", 1, true) ~= nil
      and raw_find(s2, "perform_special_ability", 1, true) ~= nil)
    check("0 " .. nm .. ": the family counts are unchanged (12 air-drop entries of 707)",
      cp(s2, 'trigger = "air_drop_on_infantry"') == 12 and cp(s2, "\t{ marker = ") == 707)
    check("0 " .. nm .. ": the tooltip sentence states the NEW rule",
      raw_find(s2, "air_drop_on_infantry = \"When armed, fires when the nearest enemy unit with more than 10 models comes within 6 m", 1, true) ~= nil)
    if nm == "live" then
      check("0 live: every air-drop line still carries the caster ui id (ad_tag definition + 5 sites)",
        cp(s2, "FOURTH.ad_tag(unit)") == 6)
    else
      check("0 ann: the reading copy stays LOG-FREE and carries the same four helpers",
        raw_find(s2, "log(", 1, true) == nil
        and raw_find(s2, "function FOURTH.ad_nearest(unit)", 1, true) ~= nil
        and raw_find(s2, "function FOURTH.try_pair(", 1, true) ~= nil
        and raw_find(s2, "function FOURTH.ad_fast_pass()", 1, true) ~= nil)
    end
  end

  -- ==========================================================================
  -- ==========================================================================
  -- ROUND 115 SUPERSESSION. Harness 114's A-J worlds asserted the round-114
  -- rule as an INSTANT comparison: one poll at 0.09 m fired. Under the
  -- 1-second dwell a single poll cannot fire at all, so those worlds are
  -- answered N/A here with the SAME 88 check slots (the running count and every
  -- later boundary pin are unchanged). The rule they proved - the candidate
  -- filter, the nearest-by-unit_distance pick, the air-only / no-melee holds,
  -- the fail-closed reads and the pre-cast re-check - is re-proved dwell and
  -- all by the harness-115 worlds A-F below.
  -- ==========================================================================
  for _ = 1, 88 do
    check("HARNESS 114 A-J world (round 115 supersession) N/A - the instant-fire worlds"
      .. " were replaced by the 1-second dwell, re-proved in the harness-115 section", true)
  end

  if red114 then
    check("HARNESS 113 suite boundary (harness 114): N/A in the red run - the pre-114 snapshot "
      .. "still carries every harness-112 world", true)
  elseif LIGHT then
    check("HARNESS 112 suite boundary (harness 114): LIGHT RUN - the air-drop sections only ("
      .. pre114 .. " checks so far)", pre114 >= 400)
  else
    check("HARNESS 112 suite boundary (harness 114): every earlier check ran first ("
      .. pre114 .. ", want 4482)", pre114 == 4482)
  end
  check("HARNESS 114: the ZERO-search invariant still holds after the new section (counted "
    .. find_calls .. ")", find_calls == 0)
  print("== HARNESS 114 done: checks " .. checks .. ", failures " .. failures .. " ==")
end

-- ============================================================================
-- HARNESS 115 - THE TRIGGER WAITS: THE 1-SECOND DWELL ON THE PAIR.
--
-- THE USER'S RULING, verbatim: "I mean the trigger fires too soon. So we need a
-- delay of 1 second for the trigger."
--
-- THE RULE THE WORLDS BELOW PROVE - round 114's edge rule is untouched, it now
-- has to LAST:
--   candidate = alive and number_of_men_alive() > AIR_DROP_MIN_MEN (10)
--   valid     = its unit_distance() is readable
--   chosen    = the NEAREST valid candidate
--   UNDER     = unit_distance(caster, chosen) < AIR_DROP_EDGE_M (0.10 m)
--   FIRE      = the pair has been CONTINUOUSLY UNDER for AIR_DROP_DWELL_S
--               (1.0 s) on the poll's clock, OR it separated after at least
--               AIR_DROP_MIN_CONTACT_S (0.3 s) of contact (the short-crossing
--               fallback)
--
-- THE CLOCK IS THE POLL: tick_count advances once per poll (POLL_MS = 250 ms),
-- so 1.0 s of dwell is the stamp plus FOUR further polls. The fast pass adds
-- EVALUATIONS, never time - world E proves that five fast ticks on a fresh
-- contact move the dwell by nothing at all.
--
-- PINS (section 0, asserted against BOTH files):
--     DWELL_S       AIR_DROP_DWELL_S       = 1.0
--     MIN_CONTACT_S AIR_DROP_MIN_CONTACT_S = 0.3
--   the four round-114 constants unchanged, POLL_MS still 250, the fast timer
--   still registered, the nested pair state, the five event lines, the purge
--   hook, the re-check's dwell verification and the new tooltip sentence.
--
-- RED CONTROL (H117_LIVE / H117_ANN -> docs/backups/round115/pre115_*.lua, the
-- round-114 build): there is no AIR_DROP_DWELL_S, no ad_pair and no dwell line,
-- so every 0 check and every A-J world fails as designed.
-- ============================================================================

-- ============================================================================
-- ROUND 118 - THE DELAY IS GONE. THE SHARED PIECES FOR THE AIR-DROP SECTIONS.
--
-- THE USER'S RULING, verbatim: "I tried it. Let's keep the distance to center
-- and remove the delay we had completely."
--
-- The trigger now casts on the evaluation that first measures the nearest valid
-- enemy's CENTRE inside AIR_DROP_CENTER_M = 6 m. Everything that existed to
-- TIME a wait - the two dwell dials, the 0.3 s minimum-contact floor, the
-- per-pair contact row and its helpers, the purge hook, the enemy-velocity read
-- with its raw-read log body, the printed cosine, the dynamic-delay formula and
-- every dwell / hold / short-crossing line - is DELETED.
--
-- THE HARNESS FILE IS AT LUA'S 200-LOCAL CEILING (exactly like the mod), so
-- these shared pieces are named GLOBALS with an h118_ prefix rather than
-- file-scope locals: adding seven locals to the chunk does not compile.
--
-- H118_DEAD is the symbol list the static pin (section 1, per file, and world
-- (c)) searches for: every one of them must answer 0 occurrences in BOTH
-- shipped files, so a rebuild cannot quietly reintroduce a wait.
-- ============================================================================
H118_DEAD = {
  "AIR_DROP_DWELL_MID_S", "AIR_DROP_DWELL_SWING_S", "AIR_DROP_MIN_CONTACT_S",
  "FOURTH.ad_pair", "ad_pair_key", "ad_pair_stamp", "ad_pair_need", "ad_pair_drop",
  "ad_under", "ad_purge_unit", "ad_contact_clear", "zz_ad_dwell_purge",
  "ad_enemy_velocity", "ad_proj_text", "ad_dynamic_delay", "ad_vread",
  "FOURTH.ad_event", "ad_fired", "dwell", "short crossing", "proj=",
}
H118_DFA = "wh2_dlc09_unit_abilities_death_from_above"
H118_INF = "wh_main_inf_zombie_0"

-- A ground position object carrying battle_vector's documented reads.
function h118_cvec(x, z)
  x, z = x or 0, z or 0
  local v = {}
  function v:get_x() return x end
  function v:get_y() return 0 end
  function v:get_z() return z end
  function v:distance_xz(o)
    local ox, oz = o:get_x(), o:get_z()
    return math.sqrt(((x - ox) * (x - ox)) + ((z - oz) * (z - oz)))
  end
  return v
end

-- ONE caster (sky_junk / death_from_above, airborne) at the ORIGIN and ONE
-- 20-model enemy placed st.r metres away on the ground at bearing posdeg.
--   st.r is read on EVERY position() call, so a world moves the enemy by
--   assigning st.r and the NEXT evaluation measures the new CENTRE gap.
--   posdeg 0 -> the enemy sits on the +x axis (bearing 0).
--   hdeg nil -> the enemy is stationary (its order point IS its position).
--   hdeg set -> the enemy carries a real HEADING (ordered = position + 10 m on
--               that bearing), so a world can prove that a heading changes
--               NOTHING any more: the delay that used to be measured from it
--               does not exist.
--   opts.seq = { {x,z}, ... } feeds the position reads IN ORDER (read i uses
--               entry i, the last repeats) - used to drift the pair between the
--               picker and the pre-cast re-check of the SAME evaluation.
function h118_mk(uid, euid, st, posdeg, hdeg, opts)
  opts = opts or {}
  local def = { name = "sky_junk", uid = uid, owns = { H118_DFA }, melee = false }
  if opts.caster_raises then def.position_raises = true end
  local rad = (posdeg or 0) * math.pi / 180
  local ex, ez = math.cos(rad) * st.r, math.sin(rad) * st.r
  local edef = { name = H118_INF, uid = euid, men_alive = opts.men or 20, pos = { ex, 0, ez } }
  if hdeg ~= nil then
    local hr = hdeg * math.pi / 180
    edef.moving = true
    edef.fast = false
    edef.slow_speed = opts.speed or 2.5
    edef.fast_speed = 4.5
    edef.ordered = { ex + math.cos(hr) * 10, 0, ez + math.sin(hr) * 10 }
  else
    edef.ordered = { ex, 0, ez }
  end
  if opts.enemy_raises then edef.position_raises = true end
  local W = make_world({ can_perform = true, units = { def }, enemies = { edef },
    cards = { { id = tostring(uid), state = "active", vis = true } },
    bar = { { id = "b1", key = H118_DFA } } })
  local u = unit_of(W, uid)
  if u ~= nil then u.is_currently_flying = function() return true end end
  local eo = nil
  for i = 1, #(W.enemy_entries or {}) do
    local eu2 = W.enemy_entries[i].unit
    local ok_e2, id_e2 = pcall(function() return eu2:unique_ui_id() end)
    if ok_e2 and tostring(id_e2) == tostring(euid) then eo = eu2 end
  end
  if eo ~= nil and not opts.enemy_raises then
    if opts.bare_position then
      eo.position = function() return { get_y = function() return 0 end } end
    else
      eo.position = function()
        if opts.seq ~= nil then
          st.i = (st.i or 0) + 1
          local q = opts.seq[st.i] or opts.seq[#opts.seq]
          return h118_cvec(q[1], q[2])
        end
        local a = (posdeg or 0) * math.pi / 180
        return h118_cvec(math.cos(a) * st.r, math.sin(a) * st.r)
      end
      if hdeg ~= nil then
        eo.ordered_position = function()
          local p = eo.position()
          local hr = hdeg * math.pi / 180
          return h118_cvec(p:get_x() + math.cos(hr) * 10, p:get_z() + math.sin(hr) * 10)
        end
      end
    end
  end
  return W
end

function h118_boot(W, PATH, TAG, uid, wname)
  local ok = pcall(load_world, W, PATH)
  check(TAG .. wname .. ": the file loads", ok)
  if not ok then tally(W); return false end
  deploy_phases(W); ui(W)
  sel_event(W, uid, true); ui(W); ui(W)
  click(W, "zz_auto_badge_death_from_above"); ui(W)
  W.conflict = true
  return true
end

function h118_fastn(W, n)
  if W.fast_fn == nil then return false end
  for _ = 1, n do W.fast_fn() end
  return true
end

function h118_cp(s2, tok)
  local n, at = 0, 1
  while true do
    local i = raw_find(s2, tok, at, true)
    if i == nil then return n end
    n = n + 1
    at = i + 1
  end
end

function h118_span(s2, head, tail2)
  local i = raw_find(s2, head, 1, true)
  if i == nil then return nil end
  local j = raw_find(s2, tail2, i, true)
  if j == nil then return nil end
  return s2:sub(i, j)
end

function h118_lg(cond) return cond == true end

-- THE PRE-CAST RE-CHECK SPAN (the air-drop block inside FOURTH.try_pair).
function h118_recheck(s2)
  return h118_span(s2, "if FOURTH.ad_enemy ~= nil then", "\n\t-- SELF-SUMMON RE-CHECK")
    or h118_span(s2, "if FOURTH.ad_enemy ~= nil then", "\n  -- SELF-SUMMON RE-CHECK")
end

function run_h115()
  -- ROUND 118: this was harness 115's DWELL section. There is no dwell any
  -- more, so its worlds are gone and the section's job is now the opposite one:
  -- prove that every piece of the delay machinery is ABSENT from BOTH shipped
  -- files, and that WHAT STAYED is still wired exactly as before.
  if os.getenv("H118_LIVE") ~= nil then LIVE = os.getenv("H118_LIVE") end
  if os.getenv("H118_ANN") ~= nil then ANN = os.getenv("H118_ANN") end
  local red115 = (os.getenv("H118_LIVE") ~= nil) or (os.getenv("H118_ANN") ~= nil)
  local live_src = read_file(LIVE)
  local ann_src = read_file(ANN)
  local pre115 = checks
  local cp, span, lg = h118_cp, h118_span, h118_lg
  local function cl(W, frag) return count_log(W, frag) end

  -- ==========================================================================
  print("== HARNESS 118 - 1: the DELAY MACHINERY is GONE from both files ==")
  for _, f in ipairs({ { name = "live", src = live_src }, { name = "ann", src = ann_src } }) do
    local nm, s2 = f.name, f.src
    local pick = span(s2, "function FOURTH.ad_pick(unit, routing)",
      "\nfunction FOURTH.evaluate_air_drop_on_infantry")
    local recheck = h118_recheck(s2)

    -- (c) THE STATIC PIN, one check per deleted symbol per file.
    for _, tok in ipairs(H118_DEAD) do
      check("1 " .. nm .. ": deleted symbol '" .. tok .. "' occurs ZERO times ("
        .. cp(s2, tok) .. ")", cp(s2, tok) == 0)
    end

    check("1 " .. nm .. ": the four constants are defined EXACTLY ONCE (6 m centre / 10 men / 30 m / 0.2 s)",
      cp(s2, "\nFOURTH.AIR_DROP_CENTER_M = 6.0\n") == 1
      and cp(s2, "\nFOURTH.AIR_DROP_MIN_MEN = 10\n") == 1
      and cp(s2, "\nFOURTH.AIR_DROP_NEAR_M = 30\n") == 1
      and cp(s2, "\nFOURTH.AIR_DROP_FAST_S = 0.2\n") == 1)
    check("1 " .. nm .. ": the ONE comparison decides, and the NOT YET branch is the only early return",
      pick ~= nil
      and cp(pick, "if dist >= FOURTH.AIR_DROP_CENTER_M then") == 1
      and cp(pick, "-> NOT YET") == 1
      and cp(pick, "FOURTH.ad_say") == (nm == "ann" and 4 or 5)
      and (nm == "ann" or cp(pick, "-> FIRING") == 1))
    local after = nil
    if pick ~= nil then
      after = span(pick, nm == "ann" and "THE DECISION IS TAKEN NOW" or "-> FIRING",
        'return "nearest valid')
    end
    check("1 " .. nm .. ": the UNDER branch goes STRAIGHT to the cast (no second look, no time read)",
      after ~= nil
      and raw_find(after, "FOURTH.ad_enemy = enemy", 1, true) ~= nil
      and raw_find(after, "FOURTH.ad_caster_su = FOURTH.eg_fresh_caster_su(unit)", 1, true) ~= nil
      and raw_find(after, "centre=", 1, true) == nil)
    check("1 " .. nm .. ": the candidate filter is the same one scan (alive, > 10 men, readable centre)",
      cp(s2, "function FOURTH.ad_nearest(unit)") == 1
      and raw_find(s2, "alive > FOURTH.AIR_DROP_MIN_MEN", 1, true) ~= nil
      and raw_find(s2, "function FOURTH.ad_centre_gap(caster, enemy)", 1, true) ~= nil
      and raw_find(s2, "local d = FOURTH.ad_centre_gap(unit, enemy)", 1, true) ~= nil)
    check("1 " .. nm .. ": air_only / no_melee / the self-centred cast / fail-closed are ALL still in place",
      raw_find(s2, "is_currently_flying()", 1, true) ~= nil
      and raw_find(s2, "is_in_melee()", 1, true) ~= nil
      and raw_find(s2, "FOURTH.ad_air_only", 1, true) ~= nil
      and raw_find(s2, "FOURTH.ad_no_melee", 1, true) ~= nil
      and raw_find(s2, "perform_special_ability", 1, true) ~= nil
      and raw_find(s2, "pcall(function() return caster:position() end)", 1, true) ~= nil)
    check("1 " .. nm .. ": the pre-cast re-check re-measures the CENTRE on fresh handles and nothing else",
      recheck ~= nil
      and raw_find(recheck, "local centre_now = FOURTH.ad_centre_gap(unit, enemy)", 1, true) ~= nil
      and raw_find(recheck, "centre_ok = (centre_now ~= nil and centre_now < FOURTH.AIR_DROP_CENTER_M)", 1, true) ~= nil
      and raw_find(recheck, "and (not melee_now) and enemy_alive and men_ok and centre_ok) then", 1, true) ~= nil
      and (nm == "live" and raw_find(recheck, "-> SKIPPED at re-check", 1, true) ~= nil
        or nm == "ann" and raw_find(recheck, "the SKIPPED-at-re-check line is a log-only line", 1, true) ~= nil))
    check("1 " .. nm .. ": the fast pass and the poll are still BOTH registered, POLL_MS untouched",
      cp(s2, "bm:repeat_callback(") == 2
      and cp(s2, 'bm:repeat_callback(poll, POLL_MS, POLL_NAME)') == 1
      and cp(s2, "local POLL_MS = 250") == 1
      and cp(s2, "zz_test_deadly_onslaught_air_drop_fast") == 1
      and cp(s2, "dist < FOURTH.AIR_DROP_NEAR_M") == 1)
    check("1 " .. nm .. ": the family counts are unchanged (12 air-drop entries of 707)",
      cp(s2, 'trigger = "air_drop_on_infantry"') == 12 and cp(s2, "\t{ marker = ") == 707)
    check("1 " .. nm .. ": the tooltip says 6 m, cast immediately, no delay at all",
      raw_find(s2, 'air_drop_on_infantry = "When armed, fires when the nearest enemy unit with more than 10 models comes within 6 m', 1, true) ~= nil
      and raw_find(s2, "casts immediately on that evaluation - no delay at all", 1, true) ~= nil)
    if nm == "live" then
      check("1 live: every surviving air-drop line carries the caster ui id (ad_tag definition + 5 sites)",
        cp(s2, "FOURTH.ad_tag(unit)") == 6)
      check("1 live: the decision line prints the type, the entity count and the exact CENTRE gap",
        cp(s2, '"nearest valid:\'" .. etype .. "\' entities="') == 2
        and cp(s2, 'centre=" .. centre_text .. "m (need < " .. need .. "m)') == 2)
      check("1 live: NO air-drop line mentions a wait, a cosine or a contact",
        cp(s2, "reads: ") == 0 and cp(s2, "reads(hold)") == 0
        and cp(s2, "pair '") == 0 and cp(s2, "measured once") == 0)
    else
      check("1 ann: the reading copy stays LOG-FREE and carries the same helpers",
        raw_find(s2, "log(", 1, true) == nil
        and raw_find(s2, "function FOURTH.ad_nearest(unit)", 1, true) ~= nil
        and raw_find(s2, "function FOURTH.ad_say(unit, marker, note)", 1, true) ~= nil
        and raw_find(s2, "function FOURTH.ad_tag(unit)", 1, true) ~= nil)
    end
  end

  -- ==========================================================================
  print("== HARNESS 118 - 1: the caster's own row constraints still HOLD the drop ==")
  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag
    local uid, euid = 17009, 17110
    local W = h118_mk(uid, euid, { r = 5.9 }, 0, nil)
    local u = unit_of(W, uid)
    if u ~= nil then u.is_currently_flying = function() return false end end
    if h118_boot(W, PATH, TAG, uid, "I") then
      polln(W, 6)
      check(TAG .. "I1: a GROUNDED caster never fires an air-only row, however long it sits under 6 m ("
        .. #W.fires .. ")", #W.fires == 0)
      check(TAG .. "I2: and it says why [live log]",
        lg((TAG ~= "[live] ") or (cl(W, "-> HOLDING (this ability's row is air-only)") >= 1)))
      tally(W)
    end
  end

  -- ==========================================================================
  if red115 then
    check("HARNESS 114 suite boundary (harness 118): N/A in the red run", true)
  elseif LIGHT then
    check("HARNESS 114 suite boundary (harness 118): LIGHT RUN - the air-drop sections only ("
      .. pre115 .. " checks so far)", pre115 >= 200)
  else
    check("HARNESS 114 suite boundary (harness 118): every earlier check ran first ("
      .. pre115 .. ")", pre115 == 4604)
  end
  check("HARNESS 118-1: the ZERO-search invariant still holds after the section (counted "
    .. find_calls .. ")", find_calls == 0)
  print("== HARNESS 118-1 done: checks " .. checks .. ", failures " .. failures .. " ==")
end

-- ============================================================================
-- HARNESS 116 - THE WAIT IS MEASURED, NOT FIXED: THE ENEMY'S OWN VELOCITY.
--
-- THE USER'S RULING, verbatim: "if the enemy unit is running away, then it is
-- too soon. If the enemy moving is running towards, then it is too late. ...
-- But it must be calculated the moment the edge to edge distance is below our
-- theshold. Then, if the unit is running towards the caster, then the delay
-- would be 0. If running away, then the delay would be 2. If stationary or
-- perpedicular, then should be 1. ... the delay is dynamic in this way." and
-- "Also include logs to check the result of the function we use, like
-- ordered_position(), just in case it isn't what we think it is."
--
-- THE RULE THE WORLDS BELOW PROVE:
--   candidate = alive and number_of_men_alive() > AIR_DROP_MIN_MEN (10)
--   chosen    = the NEAREST valid candidate by unit_distance()
--   UNDER     = unit_distance(caster, chosen) < AIR_DROP_EDGE_M (0.10 m)
--   delay     = MID - SWING * proj, measured ONCE at the first UNDER of the
--               episode, floored at 0, where
--                 axis = normalise(caster.pos - enemy.pos)
--                 v    = speed * normalise(ordered_position - position)
--                 proj = dot(v, axis) / (speed * |axis|)   (clamped to +-1)
--   FIRE      = elapsed >= delay, on the poll's clock, OR a separation after
--               AIR_DROP_MIN_CONTACT_S (0.3 s) - the short-crossing fallback
--
-- THE DELAY LANDS ON THE POLL GRID (250 ms): the log prints the MEASURED delay,
-- the cast lands on the first poll at or after it. Every world asserts the
-- measured value in the log AND the poll it actually fires on.
--
-- PINS (section 0, asserted against BOTH files):
--     MID_S   AIR_DROP_DWELL_MID_S   = 1.0
--     SWING_S AIR_DROP_DWELL_SWING_S = 1.0
--     the formula line, the floor, the single measurement call site, the pair
--     row carrying delay/proj/src, the full raw-read field list, the re-check
--     reading fired.delay, the tooltip sentence, POLL_MS, both timers.
--
-- RED CONTROL (H117_LIVE / H117_ANN -> docs/backups/round116/pre116_*.lua, the
-- round-115 build): there is no AIR_DROP_DWELL_MID_S, no ad_dynamic_delay and
-- no reads line, so every 0 check and every world below fails as designed.
-- ============================================================================
function run_h116()
  -- ROUND 118: this was harness 116's VELOCITY section - the cosine and the
  -- dynamic delay measured from the enemy's own heading. All of it is deleted,
  -- so the section now proves the NEGATIVE: the evaluator consults no movement
  -- flag, no speed, no order point and no clock, and a heading cannot move the
  -- cast by a single evaluation.
  local live_src = read_file(LIVE)
  local ann_src = read_file(ANN)
  local pre116 = checks
  local cp, span, lg = h118_cp, h118_span, h118_lg
  local function cl(W, frag) return count_log(W, frag) end

  -- ==========================================================================
  print("== HARNESS 118 - 2: the evaluator reads NO movement, NO heading and NO clock (both files) ==")
  for _, f in ipairs({ { name = "live", src = live_src }, { name = "ann", src = ann_src } }) do
    local nm, s2 = f.name, f.src
    local pick = span(s2, "function FOURTH.ad_pick(unit, routing)",
      "\nfunction FOURTH.evaluate_air_drop_on_infantry")
    check("2 " .. nm .. ": the evaluator reads NOTHING but the candidate scan and the centre gap",
      pick ~= nil
      and raw_find(pick, "is_moving", 1, true) == nil
      and raw_find(pick, "speed", 1, true) == nil
      and raw_find(pick, "ordered_position", 1, true) == nil
      and raw_find(pick, "position()", 1, true) == nil
      and raw_find(pick, "tick_count", 1, true) == nil
      and raw_find(pick, "POLL_MS", 1, true) == nil
      and raw_find(pick, "os.clock", 1, true) == nil)
    check("2 " .. nm .. ": no per-pair table and no elapsed read over one",
      cp(s2, "FOURTH.ad_pair") == 0
      and raw_find(pick, "tick_count", 1, true) == nil)
    check("2 " .. nm .. ": the only state the family keeps is the dedupe + fast-pass bookkeeping",
      raw_find(s2, "FOURTH.ad_note = {}", 1, true) ~= nil
      and raw_find(s2, "FOURTH.ad_fast_on = {}", 1, true) ~= nil
      and raw_find(s2, "FOURTH.ad_fast_abilities = {}", 1, true) ~= nil)
  end

  -- ==========================================================================
  print("== HARNESS 118 - 2: a real HEADING cannot delay the cast by one evaluation ==")
  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag
    -- The enemy is RUNNING STRAIGHT AWAY from the caster (bearing 0, heading 0).
    -- Under the deleted rule that measured proj = -1 and a 2.00 s wait; there is
    -- no wait at all now, so the FIRST evaluation casts.
    local uid, euid = 17420, 17520
    local W = h118_mk(uid, euid, { r = 5.9 }, 0, 0)
    if h118_boot(W, PATH, TAG, uid, "V1") then
      polln(W, 1)
      check(TAG .. "V1a: an enemy running AWAY at 5.9 m fires on the FIRST evaluation ("
        .. #W.fires .. ")", #W.fires == 1)
      check(TAG .. "V1b: the decision line is the plain FIRING line - no measurement, no wait [live log]",
        lg((TAG ~= "[live] ")
          or (cl(W, "centre=5.90m (need < 6.00m) -> FIRING (the nearest") == 1
            and cl(W, "measured once") == 0 and cl(W, " src=") == 0)))
      h118_fastn(W, 2)
      check(TAG .. "V1c: two fast ticks inside the guard add nothing (" .. #W.fires .. ")",
        #W.fires == 1)
      tally(W)
    end
  end

  -- ==========================================================================
  check("HARNESS 115 suite boundary (harness 118): the earlier sections ran first ("
    .. pre116 .. ")", (LIGHT and (pre116 >= 200)) or (pre116 == 4676))
  check("HARNESS 118-2: the ZERO-search invariant still holds after the section (counted "
    .. find_calls .. ")", find_calls == 0)
  print("== HARNESS 118-2 done: checks " .. checks .. ", failures " .. failures .. " ==")
end

-- ============================================================================
-- HARNESS 117 - THE MEASUREMENT MOVES: EDGE-TO-EDGE -> GROUND CENTRE-TO-CENTRE
--
-- THE USER'S RULING, verbatim: "Let's keep our current calculation but just
-- replace the detection on edge with detection on the distance to center.
-- Let's say 6 meters for now. I'll test."
--
-- ONE THING CHANGED. Everything the round-116 rule did is kept exactly:
--   candidate = alive and number_of_men_alive() > AIR_DROP_MIN_MEN (10)
--   chosen    = the NEAREST valid candidate
--   delay     = MID - SWING * proj, measured ONCE at the first UNDER of the
--               episode (0 s closing / 1 s stationary-or-across / 2 s receding)
--   FIRE      = elapsed >= delay on the poll's clock, OR a separation after
--               AIR_DROP_MIN_CONTACT_S (0.3 s) - the short-crossing fallback
-- and the ONE measurement that decides UNDER moved from the engine's
-- bounding-box EDGE gap (unit:unit_distance) to the GROUND-PLANE
-- CENTRE-to-CENTRE distance between the two position() reads (x/z only):
--   UNDER = ad_centre_gap(caster, chosen) < AIR_DROP_CENTER_M (6.0 m)
--
-- THE WORLDS BELOW (each runs against the LIVE source AND the annotated copy):
--   A1  5.9 m -> UNDER: stamps, waits the measured 1.00 s, fires on the poll
--       that completes it, and every line prints gap 5.90m.
--   A2  6.1 m -> NOT under: six polls, nothing stamped, nothing fired, and the
--       decision line prints centre=6.10m (need < 6.00m).
--   B1  5.9 m CLOSING (proj +1)   -> delay 0.00 s -> fires on the NEXT poll.
--   B2  5.9 m RECEDING (proj -1)  -> delay 2.00 s -> holds 1.75 s, then fires.
--   B3  5.9 m ACROSS (proj 0)     -> delay 1.00 s -> fires at 1.00 s.
--   C1  a 0.25 s contact that separates to 6.5 m -> CANCELLED, nothing fires.
--   C2  a 0.75 s contact that separates to 6.5 m -> the short-crossing
--       fallback FIRES on the separation evaluation.
--   D   an unreadable caster position / enemy position / co-ordinate read ->
--       no candidate, no cast, no crash (FAIL CLOSED).
--   E   the pre-cast re-check RE-MEASURES the centre: the pair drifts to
--       6.1 m between the picker and the re-check of the SAME poll -> skipped.
--
-- PINS (section 0, BOTH files): the 6.0 m constant (once) and the 0.1 m edge
-- constant GONE, ad_centre_gap (x/z only, distance_xz + sqrt fallback, nil on
-- any unreadable read), the scan on the centre, the one comparison, centre=
-- on every decision line and edge= on none, the re-check re-measuring the
-- centre, the dynamic delay / fallback / gates untouched, both timers, the
-- family counts and the tooltip sentence.
-- ============================================================================
function run_h117()
  -- ROUND 118: the CENTRE measurement is the ONE thing round 117 added that is
  -- still here, so this section keeps its static pins - retouched where they
  -- described the delay - and its worlds have moved to the section below.
  local live_src = read_file(LIVE)
  local ann_src = read_file(ANN)
  local pre117 = checks
  local cp, span, lg = h118_cp, h118_span, h118_lg

  -- ==========================================================================
  print("== HARNESS 118 - 3: the CENTRE measurement, and what still hangs off it ==")
  for _, f in ipairs({ { name = "live", src = live_src }, { name = "ann", src = ann_src } }) do
    local nm, s2 = f.name, f.src
    local pick = span(s2, "function FOURTH.ad_pick(unit, routing)",
      "\nfunction FOURTH.evaluate_air_drop_on_infantry")
    local helper = span(s2, "function FOURTH.ad_centre_gap(caster, enemy)", "\nend")
    local nearest = span(s2, "function FOURTH.ad_nearest(unit)", "\nend")
    local recheck = h118_recheck(s2)

    check("3 " .. nm .. ": the centre helper is defined ONCE, x/z only, with the distance_xz fallback",
      helper ~= nil
      and cp(s2, "function FOURTH.ad_centre_gap(caster, enemy)") == 1
      and raw_find(helper, "get_x()", 1, true) ~= nil
      and raw_find(helper, "get_z()", 1, true) ~= nil
      and raw_find(helper, "distance_xz", 1, true) ~= nil
      and raw_find(helper, "math.sqrt((dx * dx) + (dz * dz))", 1, true) ~= nil
      and raw_find(helper, "get_y()", 1, true) == nil)
    check("3 " .. nm .. ": the scan picks the NEAREST valid candidate by that centre gap, and nothing else",
      nearest ~= nil
      and raw_find(nearest, "local d = FOURTH.ad_centre_gap(unit, enemy)", 1, true) ~= nil
      and raw_find(nearest, "if d ~= nil and (best_d == nil or d < best_d) then", 1, true) ~= nil
      and raw_find(nearest, "unit_distance", 1, true) == nil
      and raw_find(nearest, "is_infantry", 1, true) == nil)
    check("3 " .. nm .. ": the picker compares the CENTRE once and never an EDGE",
      pick ~= nil
      and cp(pick, "FOURTH.AIR_DROP_CENTER_M") == 2
      and raw_find(pick, "dist >= FOURTH.AIR_DROP_CENTER_M", 1, true) ~= nil
      and raw_find(pick, " -> NOT YET", 1, true) ~= nil
      and raw_find(pick, "FOURTH.AIR_DROP_EDGE_M", 1, true) == nil
      and raw_find(pick, "unit_distance", 1, true) == nil)
    check("3 " .. nm .. ": the pre-cast re-check re-measures the SAME centre on FRESH handles",
      recheck ~= nil
      and raw_find(recheck, "local centre_now = FOURTH.ad_centre_gap(unit, enemy)", 1, true) ~= nil
      and raw_find(recheck, "centre_now < FOURTH.AIR_DROP_CENTER_M", 1, true) ~= nil
      and raw_find(recheck, "centre_ok) then", 1, true) ~= nil
      and raw_find(recheck, "edge_text", 1, true) == nil
      and raw_find(recheck, "eg_enemy_gap", 1, true) == nil)
    check("3 " .. nm .. ": the bound follows the rule (ability.range_m = the 6 m line)",
      cp(s2, "ability.range_m = FOURTH.AIR_DROP_CENTER_M") == 1)
    check("3 " .. nm .. ": the change is LOCAL - eg_enemy_gap still serves the other triggers",
      cp(s2, "function FOURTH.eg_enemy_gap(unit, enemy)") == 1
      and cp(s2, "FOURTH.eg_enemy_gap(") >= 4)
    if nm == "live" then
      check("3 live: no live code path can still ask for the edge gap in this family",
        raw_find(s2, "FOURTH.AIR_DROP_EDGE_M", 1, true) == nil)
    else
      check("3 ann: the reading copy stays LOG-FREE and carries the same centre helper",
        raw_find(s2, "log(", 1, true) == nil
        and helper ~= nil
        and raw_find(helper, "distance_xz", 1, true) ~= nil
        and raw_find(s2, "function FOURTH.ad_nearest(unit)", 1, true) ~= nil)
    end
  end

  -- ==========================================================================
  check("HARNESS 116 suite boundary (harness 118): the earlier sections ran first ("
    .. pre117 .. ")", (LIGHT and (pre117 >= 250)) or (pre117 == 4692))
  check("HARNESS 118-3: the ZERO-search invariant still holds after the section (counted "
    .. find_calls .. ")", find_calls == 0)
  print("== HARNESS 118-3 done: checks " .. checks .. ", failures " .. failures .. " ==")
end

function run_h118()
  -- ROUND 118 - THE SIX WORLDS. The trigger fires on the EVALUATION that first
  -- measures the nearest valid enemy's centre inside 6 m; nothing waits, nothing
  -- is stamped, and the pre-cast re-check re-measures the centre on fresh
  -- handles before the call.
  local pre118 = checks
  local cp, span, lg = h118_cp, h118_span, h118_lg
  local function cl(W, frag) return count_log(W, frag) end

  -- ==========================================================================
  print("== HARNESS 118 - (a) a 5.9 m centre CASTS on the FIRST evaluation ==")
  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag
    local uid, euid = 17431, 17531
    local W = h118_mk(uid, euid, { r = 5.9 }, 0, nil)
    if h118_boot(W, PATH, TAG, uid, "A") then
      polln(W, 1)
      check(TAG .. "A1: the FIRST poll casts, once (" .. #W.fires .. ")", #W.fires == 1)
      check(TAG .. "A2: the decision line names the enemy, its count and the centre [live log]",
        lg((TAG ~= "[live] ")
          or (cl(W, "nearest valid:'wh_main_inf_zombie_0' entities=20 centre=5.90m"
              .. " (need < 6.00m) -> FIRING (the nearest of the valid enemies") == 1)))
      check(TAG .. "A3: the re-check accepted the SAME centre [live log]",
        lg((TAG ~= "[live] ") or (cl(W, "centre=5.90m (need < 6.00m) -> FIRING (re-checked)") == 1)))
      tally(W)
    end
  end

  -- ==========================================================================
  print("== HARNESS 118 - (b) a 6.1 m centre casts NOTHING ==")
  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag
    local uid, euid = 17432, 17532
    local W = h118_mk(uid, euid, { r = 6.1 }, 0, nil)
    if h118_boot(W, PATH, TAG, uid, "B") then
      polln(W, 6)
      h118_fastn(W, 5)
      check(TAG .. "B1: six polls and five fast ticks at 6.1 m cast NOTHING (" .. #W.fires .. ")",
        #W.fires == 0)
      check(TAG .. "B2: the line says centre=6.10m against the 6.00 m line [live log]",
        lg((TAG ~= "[live] ")
          or (cl(W, "centre=6.10m (need < 6.00m) -> NOT YET") == 1
            and cl(W, "-> FIRING") == 0)))
      check(TAG .. "B3: and no contact/dwell line exists to print [live log]",
        lg((TAG ~= "[live] ") or (cl(W, "waiting") == 0 and cl(W, "under at gap") == 0)))
      tally(W)
    end
  end

  -- ==========================================================================
  print("== HARNESS 118 - (c) NO delay/timestamp state survives, in EITHER file ==")
  local live_src = read_file(LIVE)
  local ann_src = read_file(ANN)
  local n_bad, n_tok = 0, 0
  for _, pair in ipairs({ { nm = "live", src = live_src }, { nm = "ann", src = ann_src } }) do
    for _, tok in ipairs(H118_DEAD) do
      n_tok = n_tok + 1
      if cp(pair.src, tok) ~= 0 then n_bad = n_bad + 1 end
    end
  end
  check("C1: every deleted symbol occurs ZERO times in BOTH files (" .. n_tok
    .. " symbols searched, " .. n_bad .. " hits)", n_bad == 0)
  check("C2: no per-pair/caster state table is declared in either file",
    cp(live_src, "FOURTH.ad_pair") == 0 and cp(ann_src, "FOURTH.ad_pair") == 0)
  check("C3: neither file reads a clock inside the air-drop evaluator",
    (function()
      local ok = true
      for _, s2 in ipairs({ live_src, ann_src }) do
        local pick = span(s2, "function FOURTH.ad_pick(unit, routing)",
          "\nfunction FOURTH.evaluate_air_drop_on_infantry")
        if pick == nil or raw_find(pick, "tick_count", 1, true) ~= nil
          or raw_find(pick, "os.clock", 1, true) ~= nil then ok = false end
      end
      return ok
    end)())

  -- ==========================================================================
  print("== HARNESS 118 - (d) a second evaluation right after a cast does NOT double-cast ==")
  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag
    local uid, euid = 17434, 17534
    local W = h118_mk(uid, euid, { r = 5.9 }, 0, nil)
    if h118_boot(W, PATH, TAG, uid, "D") then
      polln(W, 1)
      check(TAG .. "D1: the first evaluation cast once (" .. #W.fires .. ")", #W.fires == 1)
      h118_fastn(W, 5)
      check(TAG .. "D2: five fast evaluations in the same window cast NOTHING more ("
        .. #W.fires .. ")", #W.fires == 1)
      polln(W, 2)
      check(TAG .. "D3: nor do the next two polls, inside the 2 s guard (" .. #W.fires .. ")",
        #W.fires == 1)
      check(TAG .. "D4: exactly ONE re-checked firing line in the whole window [live log]",
        lg((TAG ~= "[live] ") or (cl(W, "-> FIRING (re-checked)") == 1)))
      polln(W, 12)
      check(TAG .. "D5: past the guard the still-under pair casts again, once (" .. #W.fires .. ")",
        #W.fires == 2)
      tally(W)
    end
  end

  -- ==========================================================================
  print("== HARNESS 118 - (e) unreadable positions FAIL CLOSED ==")
  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag
    local uid, euid = 17435, 17535
    local W = h118_mk(uid, euid, { r = 5.9 }, 0, nil, { caster_raises = true })
    if h118_boot(W, PATH, TAG, uid, "E1") then
      polln(W, 6)
      check(TAG .. "E1a: an unreadable CASTER position casts nothing, no crash (" .. #W.fires .. ")",
        #W.fires == 0)
      tally(W)
    end
    local uid2, euid2 = 17436, 17536
    local W2 = h118_mk(uid2, euid2, { r = 5.9 }, 0, nil, { enemy_raises = true })
    if h118_boot(W2, PATH, TAG, uid2, "E2") then
      polln(W2, 6)
      check(TAG .. "E2a: an unreadable ENEMY position casts nothing (" .. #W2.fires .. ")",
        #W2.fires == 0)
      tally(W2)
    end
    local uid3, euid3 = 17437, 17537
    local W3 = h118_mk(uid3, euid3, { r = 5.9 }, 0, nil, { bare_position = true })
    if h118_boot(W3, PATH, TAG, uid3, "E3") then
      polln(W3, 6)
      check(TAG .. "E3a: a position object with no get_x/get_z casts nothing (" .. #W3.fires .. ")",
        #W3.fires == 0)
      tally(W3)
    end
  end

  -- ==========================================================================
  print("== HARNESS 118 - (f) the pre-cast re-check RE-MEASURES: 5.9 -> 6.1 SKIPS ==")
  for _, f in ipairs({ { path = LIVE, tag = "[live] " }, { path = ANN, tag = "[ann] " } }) do
    local PATH, TAG = f.path, f.tag
    local uid, euid = 17438, 17538
    -- The FIRST evaluation makes exactly TWO position reads on the chosen enemy:
    -- read 1 is the picker (5.9 m, under the line), read 2 is the pre-cast
    -- re-check of the SAME evaluation, which must see the drift to 6.1 m.
    local seq = { { 5.9, 0 }, { 6.1, 0 } }
    local W = h118_mk(uid, euid, { r = 5.9, i = 0 }, 0, nil, { seq = seq })
    if h118_boot(W, PATH, TAG, uid, "F") then
      polln(W, 1)
      check(TAG .. "F1: the picker measured 5.9 m but the re-check measured 6.1 m - no cast ("
        .. #W.fires .. ")", #W.fires == 0)
      check(TAG .. "F2: the skip line prints the FRESH centre gap and names the lapsed test [live log]",
        lg((TAG ~= "[live] ")
          or (cl(W, "centre=6.10m (need < 6.00m) -> SKIPPED at re-check") == 1
            and cl(W, "centre_ok=false") == 1
            and cl(W, "- cast not spent") == 1)))
      check(TAG .. "F3: the refused cast was NOT spent - the re-check never said FIRING [live log]",
        lg((TAG ~= "[live] ") or (cl(W, "-> FIRING (re-checked)") == 0)))
      -- back inside the line on freshly-read handles: the pair casts once the
      -- guard window the refused attempt consumed has passed.
      seq[3] = { 5.9, 0 }
      seq[4] = { 5.9, 0 }
      polln(W, 10)
      check(TAG .. "F4: still 5.9 m on FRESH handles, it casts once the guard has passed ("
        .. #W.fires .. ")", #W.fires == 1)
      tally(W)
    end
    -- the same world WITHOUT the drift: the picker and the re-check agree, so
    -- the cast goes out on the same evaluation (the control for F1)
    local uid2, euid2 = 17439, 17539
    local W2 = h118_mk(uid2, euid2, { r = 5.9, i = 0 }, 0, nil,
      { seq = { { 5.9, 0 }, { 5.9, 0 } } })
    if h118_boot(W2, PATH, TAG, uid2, "F0") then
      polln(W2, 1)
      check(TAG .. "F0: with no drift the same world casts ON THE FIRST evaluation ("
        .. #W2.fires .. ")", #W2.fires == 1)
      tally(W2)
    end
  end

  -- ==========================================================================
  check("HARNESS 117 suite boundary (harness 118): the earlier air-drop sections ran ("
    .. pre118 .. ")", (LIGHT and (pre118 >= 250)) or (pre118 == 4708))
  check("HARNESS 118: the ZERO-search invariant still holds after the six worlds (counted "
    .. find_calls .. ")", find_calls == 0)
  print("== HARNESS 118 done: checks " .. checks .. ", failures " .. failures .. " ==")
end



-- ============================================================================
-- HARNESS 121 (round 122): TEN SELF-CAST MELEE BUFFS ON melee_unwavering.
--   0r: tokens in BOTH files - the ten markers, badges and keys; the table is
--       697 entries with 697 badges; melee_unwavering is 370; no batch key is
--       in the army_spec junction (read from the game's own extract).
--   M (per ability): in melee, not wavering -> FIRES once, cast on the OWNER,
--       with the shared reason "in melee, morale not wavering".
--   S (per ability): NOT in melee -> SILENT.
--   V (per ability): in melee but WAVERING -> SILENT.
--   RED CONTROL: with H121_LIVE / H121_ANN on the pre-122 snapshot every 0r
--   token and every M world fails (the entries are absent, nothing fires);
--   S and V pass trivially.
-- ============================================================================
function run_h121()
  local L121 = os.getenv("H121_LIVE") or LIVE
  local A121 = os.getenv("H121_ANN") or ANN
  local RED121 = (os.getenv("H121_LIVE") ~= nil) or (os.getenv("H121_ANN") ~= nil)
  local BATCH = {
    { "call_for_power", "wh3_main_daemon_head_abilities_call_for_power" },
    { "manus_of_ursun", "wh3_main_weapon_abilities_ursuns_claws" },
    { "black_hammer_of_hashut", "wh3_dlc23_weapon_abilities_black_hammer_of_hashut" },
    { "the_graven_sceptre", "wh3_dlc23_weapon_abilities_the_graven_sceptre" },
    { "tyrants_talon", "wh3_cp1_weapon_abilities_tyrants_talon" },
    { "the_crimson_blade", "wh3_dlc29_item_abilities_crimson_blade" },
    { "bloodstorm", "wh2_dlc14_lord_abilities_bloodstorm" },
    { "crooked_dice", "wh3_dlc23_hero_abilities_crooked_dice" },
    { "temptator", "wh3_dlc20_lord_abilities_temptator" },
    { "all_consuming_hatred", "wh3_dlc27_unit_abilities_consuming_hatred" },
  }
  local pre121 = checks
  local function cp(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function lg(tag, v) return (tag ~= "[live] ") or v end

  print("== HARNESS 121 - section 0r: the ten new melee_unwavering entries (BOTH files) ==")
  local army = {}
  local fh = io.open("C:/Users/vlady/Desktop/WH3_mod/gamedata/wh3/army_spec.tsv", "r")
  check("0r: the army_spec extract is readable", fh ~= nil)
  if fh then
    fh:read("*l")
    for ln in fh:lines() do
      local k = ln:match("^([^\t#][^\t]*)")
      if k then army[k] = true end
    end
    fh:close()
  end
  for _, f in ipairs({ { name = "live", path = L121 }, { name = "ann", path = A121 } }) do
    local nm, s = f.name, read_file(f.path)
    check("0r " .. nm .. ": the table is 697 entries, each with a badge field ("
      .. cp(s, "\t{ marker = ") .. ")", cp(s, "\t{ marker = ") == 707 and cp(s, 'badge = "') == 707)
    check("0r " .. nm .. ": melee_unwavering is 370 entries (" .. cp(s, 'trigger = "melee_unwavering"') .. ")",
      cp(s, 'trigger = "melee_unwavering"') == 374)
    for _, b in ipairs(BATCH) do
      local m, k = b[1], b[2]
      check("0r " .. nm .. ": " .. m .. " is present once on melee_unwavering with its badge and key",
        cp(s, 'marker = "' .. m .. '", name = ') == 1
        and raw_find(s, 'marker = "' .. m .. '", name = "', 1, true) ~= nil
        and cp(s, 'badge = "zz_auto_badge_' .. m .. '"') == 1
        and cp(s, '"' .. k .. '"') == 1
        and raw_find(s, 'marker = "' .. m .. '", name = "[^"]*", trigger = "melee_unwavering"') ~= nil)
    end
  end
  local army_hits = 0
  for _, b in ipairs(BATCH) do if army[b[2]] then army_hits = army_hits + 1 end end
  check("0r: NO batch key is in the army_spec junction (" .. army_hits .. " hit(s))", army_hits == 0)

  local results, n_ok = {}, 0
  local function boot(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, "zz_auto_badge_" .. marker); ui(W)
    W.conflict = true
    return true
  end
  local function world(PATH, TAG, i, b, kind)
    local m, k = b[1], b[2]
    local uid = 12100 + i * 10 + ({ M = 1, S = 2, V = 3 })[kind]
    local melee = (kind ~= "S")
    local wav = (kind == "V")
    local W = make_world({ can_perform = true, units = {
      { name = "owner", uid = uid, owns = { k }, melee = melee, wavering = wav },
    }, cards = { { id = tostring(uid), state = "active", vis = true } }, bar = { { id = "b1", key = k } } })
    local wname = kind .. i
    if not boot(W, PATH, TAG, uid, m, wname) then return false end
    polln(W, 1)
    local ok
    if kind == "M" then
      local a = (#W.fires == 1 and W.fires[1].uid == uid and W.fires[1].key == k)
      check(TAG .. wname .. ": " .. m .. " in melee, not wavering -> FIRES once (" .. fire_detail(W) .. ")", a)
      local bb = (fire_target_for(W, uid) == unit_of(W, uid))
      check(TAG .. wname .. ": " .. m .. " is cast on the OWNER itself (self-cast)", bb)
      local c = (count_log(W, "reason: in melee, morale not wavering") == 1)
      check(TAG .. wname .. ": " .. m .. " uses the shared in-melee reason [live log]", lg(TAG, c))
      ok = a and bb and lg(TAG, c)
    else
      local why = (kind == "S") and "NOT in melee" or "in melee but WAVERING"
      ok = (#W.fires == 0)
      check(TAG .. wname .. ": " .. m .. " " .. why .. " -> SILENT (" .. fire_detail(W) .. ")", ok)
    end
    check(TAG .. wname .. ": every ui tick ran clean (" .. (W.ui_failures or 0) .. " failures)",
      (W.ui_failures or 0) == 0)
    tally(W)
    return ok
  end

  for i, b in ipairs(BATCH) do
    print("== HARNESS 121 - " .. b[1] .. ": fire / silent / wavering worlds ==")
    for _, kind in ipairs({ "M", "S", "V" }) do
      for _, f in ipairs({ { path = A121, tag = "[annotated] " }, { path = L121, tag = "[live] " } }) do
        local r = world(f.path, f.tag, i, b, kind)
        results[#results + 1] = r
        if r then n_ok = n_ok + 1 end
      end
    end
  end

  if not RED121 then
    check("HARNESS 121: all 60 worlds behaved (10 abilities x fire/silent/wavering x live+annotated) - "
      .. n_ok .. "/60", n_ok == 60)
  else
    check("RED CONTROL (harness 121): on the pre-122 snapshot only the 40 SILENT worlds pass - "
      .. n_ok .. "/60 (want 40)", n_ok == 40)
  end
  print("== HARNESS 121 done: " .. (checks - pre121) .. " checks in this section ==")
end


-- ============================================================================
-- HARNESS 122 (round 123): THE HEX BATCH.
--   0s: tokens in BOTH files (entries, triggers, keys, range_real, charge
--       holds, the evaluator, its map line and tooltip, no Daemonic Possession,
--       no batch key in army_spec).
--   A (melee_unwavering x4): in melee FIRES on self; out of melee SILENT;
--       wavering SILENT.
--   C (charge_or_melee x3): in melee FIRES; CHARGING (running, targeted, 20 m)
--       FIRES with the charge reason; running with NO target (a move order,
--       "only passing by") SILENT.
--   E (enemy_melee x3): enemy in melee in range FIRES at the ENEMY; enemy only
--       UNDER MISSILE FIRE stays SILENT (the user's rule); enemy in melee just
--       beyond the 70% bound SILENT; exactly on the bound FIRES; enemy leaves
--       melee between decide and cast -> SKIPPED, not spent.
--   G: No Escape is held for its own 90 s recharge after a cast (3 uses).
--   H: the upgraded Hunter of Champions key fires on an enemy under missile
--       fire (enemy_engaged_or_shot), through the existing entry's badge.
-- ============================================================================
function run_h122()
  local L122 = os.getenv("H122_LIVE") or LIVE
  local A122 = os.getenv("H122_ANN") or ANN
  local RED122 = (os.getenv("H122_LIVE") ~= nil) or (os.getenv("H122_ANN") ~= nil)
  local MU = {
    { "rival_hide_talisman", "wh2_main_item_abilities_rival_hide_talisman" },
    { "seductive_glory", "wh3_main_lord_abilities_seductive_glory" },
    { "vine_dragon_scale", "wh2_dlc15_item_abilities_vine_dragon_scale" },
    { "dark_mace", "wh3_dlc23_weapon_abilities_dark_mace" },
  }
  local CM = {
    { "seduction", "wh2_dlc11_lord_abilities_seduction" },
    { "song_of_enthrallment", "wh2_dlc11_lord_abilities_song_of_enthrallment" },
    { "smoke_bomb", "wh_dlc06_unit_abilities_smoke_bomb" },
  }
  local EM = {
    { "no_escape", "wh3_main_character_abilities_no_escape", 70 },
    { "transfix_hex", "wh3_dlc29_lord_abilities_transfix", 70 },
    { "flash_bomb", "wh_pro01_lord_abilities_flash_bomb", 52 },
  }
  local HOC_UP = "wh2_dlc17_character_abilities_hunter_of_champions_upgraded"
  local pre122 = checks
  local function cp(s, tok)
    local n, at = 0, 1
    while true do
      local i = raw_find(s, tok, at, true)
      if i == nil then return n end
      n = n + 1
      at = i + 1
    end
  end
  local function lg(tag, v) return (tag ~= "[live] ") or v end
  local function enemy_by(W, uid)
    for i = 1, #(W.enemy_entries or {}) do
      local pr = W.enemy_entries[i]
      if pr ~= nil and pr.unit ~= nil then
        local ok, id = pcall(function() return pr.unit:unique_ui_id() end)
        if ok and tostring(id) == tostring(uid) then return pr.unit end
      end
    end
    return nil
  end

  -- ------------------------------------------------------------------ 0s
  print("== HARNESS 122 - section 0s: the hex batch tokens (BOTH files) ==")
  local army = {}
  local fh = io.open("C:/Users/vlady/Desktop/WH3_mod/gamedata/wh3/army_spec.tsv", "r")
  check("0s: the army_spec extract is readable", fh ~= nil)
  if fh then
    fh:read("*l")
    for ln in fh:lines() do
      local k = ln:match("^([^\t#][^\t]*)")
      if k then army[k] = true end
    end
    fh:close()
  end
  local all_keys = { HOC_UP }
  for _, t in ipairs({ MU, CM, EM }) do for _, b in ipairs(t) do all_keys[#all_keys + 1] = b[2] end end
  local hits = 0
  for _, k in ipairs(all_keys) do if army[k] then hits = hits + 1 end end
  check("0s: NO batch key is in the army_spec junction (" .. hits .. " hit(s) of " .. #all_keys .. ")", hits == 0)
  for _, f in ipairs({ { name = "live", path = L122 }, { name = "ann", path = A122 } }) do
    local nm, s = f.name, read_file(f.path)
    check("0s " .. nm .. ": the table is 707 entries with 707 badges (" .. cp(s, "\t{ marker = ") .. ")",
      cp(s, "\t{ marker = ") == 707 and cp(s, 'badge = "') == 707)
    check("0s " .. nm .. ": trigger counts melee_unwavering 374, charge_or_melee 28, enemy_melee 3, "
      .. "enemy_engaged_or_shot 85 (unchanged)",
      cp(s, 'trigger = "melee_unwavering"') == 374 and cp(s, 'trigger = "charge_or_melee"') == 28
      and cp(s, 'trigger = "enemy_melee"') == 3 and cp(s, 'trigger = "enemy_engaged_or_shot"') == 85)
    local function entry_ok(m, k, trig)
      return raw_find(s, 'marker = "' .. m .. '", name = "[^"]*", trigger = "' .. trig .. '"') ~= nil
        and cp(s, 'badge = "zz_auto_badge_' .. m .. '"') == 1 and cp(s, 'keys = { "' .. k .. '" }') == 1
    end
    for _, b in ipairs(MU) do
      check("0s " .. nm .. ": " .. b[1] .. " is on melee_unwavering with its badge and key", entry_ok(b[1], b[2], "melee_unwavering"))
    end
    for _, b in ipairs(CM) do
      check("0s " .. nm .. ": " .. b[1] .. " is on charge_or_melee with its badge and key", entry_ok(b[1], b[2], "charge_or_melee"))
    end
    for _, b in ipairs(EM) do
      check("0s " .. nm .. ": " .. b[1] .. " is on enemy_melee with its badge and key", entry_ok(b[1], b[2], "enemy_melee"))
    end
    check("0s " .. nm .. ": No Escape and Transfix carry range_real 100, Flash Bomb 75 (70% -> 70 m / 52 m)",
      raw_find(s, '"wh3_main_character_abilities_no_escape" },\n\t\trange_real = 100,', 1, true) ~= nil
      and raw_find(s, '"wh3_dlc29_lord_abilities_transfix" },\n\t\trange_real = 100,', 1, true) ~= nil
      and raw_find(s, '"wh_pro01_lord_abilities_flash_bomb" },\n\t\trange_real = 75,', 1, true) ~= nil)
    check("0s " .. nm .. ": the range_real fields are 207 (204 + 3)", cp(s, "\t\trange_real = ") == 207)
    check("0s " .. nm .. ": the two 3-use hexes are held for their own recharge (90 s / 120 s)",
      cp(s, '["wh3_main_character_abilities_no_escape"] = 90,') == 1
      and cp(s, '["wh3_dlc29_lord_abilities_transfix"] = 120,') == 1)
    check("0s " .. nm .. ": the enemy_melee evaluator sets the melee-only flag and uses the UNIT form",
      raw_find(s, "function FOURTH.evaluate_enemy_melee(unit, routing)\n\tFOURTH.eg_melee_only = true\n"
        .. "\treturn FOURTH.eg_pick_enemy(unit, routing, false)\nend", 1, true) ~= nil)
    check("0s " .. nm .. ": enemy_melee is wired in the map and has its tooltip line",
      cp(s, "\tenemy_melee = FOURTH.evaluate_enemy_melee,") == 1
      and cp(s, '\tenemy_melee = "When armed, fires on the closest enemy unit in range that is fighting in melee",') == 1)
    check("0s " .. nm .. ": the upgraded Hunter of Champions key sits in the EXISTING entry",
      raw_find(s, 'marker = "hunter_of_champions", name = "Hunter of Champions", trigger = "enemy_engaged_or_shot",', 1, true) ~= nil
      and cp(s, '"' .. HOC_UP .. '"') == 1 and cp(s, 'marker = "hunter_of_champions"') == 1)
    check("0s " .. nm .. ": Daemonic Possession is NOT in the mod (user decision)",
      raw_find(s, "wh3_main_lord_abilities_daemonic_possession", 1, true) == nil)
  end

  -- ------------------------------------------------------------------ worlds
  local n_ok, n_all, n_silent = 0, 0, 0
  local function boot(W, PATH, TAG, uid, marker, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true); ui(W); ui(W)
    click(W, "zz_auto_badge_" .. marker); ui(W)
    W.conflict = true
    return true
  end
  local function finish(W, TAG, wname, ok, silent)
    check(TAG .. wname .. ": every ui tick ran clean (" .. (W.ui_failures or 0) .. " failures)",
      (W.ui_failures or 0) == 0)
    tally(W)
    n_all = n_all + 1
    if ok then n_ok = n_ok + 1 end
    if silent then n_silent = n_silent + 1 end
  end
  local FILES = { { path = A122, tag = "[annotated] " }, { path = L122, tag = "[live] " } }
  local uid_next = 12200
  local function nid() uid_next = uid_next + 2; return uid_next end

  -- A: melee_unwavering, self-cast
  for i, b in ipairs(MU) do
    print("== HARNESS 122 - A" .. i .. " " .. b[1] .. ": melee / out of melee / wavering ==")
    for _, kind in ipairs({ "M", "S", "V" }) do
      for _, f in ipairs(FILES) do
        local TAG, uid = f.tag, nid()
        local W = make_world({ can_perform = true, units = {
          { name = "owner", uid = uid, owns = { b[2] }, melee = (kind ~= "S"), wavering = (kind == "V") },
        }, cards = { { id = tostring(uid), state = "active", vis = true } }, bar = { { id = "b1", key = b[2] } } })
        local wname = "A" .. i .. kind
        if boot(W, f.path, TAG, uid, b[1], wname) then
          polln(W, 1)
          local ok
          if kind == "M" then
            local a = (#W.fires == 1 and W.fires[1].uid == uid and W.fires[1].key == b[2])
            check(TAG .. wname .. ": " .. b[1] .. " in melee -> FIRES once (" .. fire_detail(W) .. ")", a)
            local c = (fire_target_for(W, uid) == unit_of(W, uid))
            check(TAG .. wname .. ": cast on the OWNER (the aura is centred on the fight)", c)
            local d = (count_log(W, "reason: in melee, morale not wavering") == 1)
            check(TAG .. wname .. ": the shared in-melee reason [live log]", lg(TAG, d))
            ok = a and c and lg(TAG, d)
            finish(W, TAG, wname, ok, false)
          else
            ok = (#W.fires == 0)
            check(TAG .. wname .. ": " .. b[1] .. ((kind == "S") and " NOT in melee" or " in melee but WAVERING")
              .. " -> SILENT (" .. fire_detail(W) .. ")", ok)
            finish(W, TAG, wname, ok, true)
          end
        else
          n_all = n_all + 1
        end
      end
    end
  end

  -- C: charge_or_melee, self-cast
  for i, b in ipairs(CM) do
    print("== HARNESS 122 - C" .. i .. " " .. b[1] .. ": melee / charging / running with no target ==")
    for _, kind in ipairs({ "M", "C", "R" }) do
      for _, f in ipairs(FILES) do
        local TAG, uid = f.tag, nid()
        local def = { name = "owner", uid = uid, owns = { b[2] }, melee = (kind == "M") }
        if kind == "C" then def.fast = true; def.target = "enemy"; def.dist = 20 end
        if kind == "R" then def.fast = true end
        local W = make_world({ can_perform = true, units = { def },
          cards = { { id = tostring(uid), state = "active", vis = true } }, bar = { { id = "b1", key = b[2] } } })
        local wname = "C" .. i .. kind
        if boot(W, f.path, TAG, uid, b[1], wname) then
          polln(W, 1)
          local ok
          if kind == "R" then
            ok = (#W.fires == 0)
            check(TAG .. wname .. ": " .. b[1] .. " RUNNING with no target (a move order, passing by) -> SILENT ("
              .. fire_detail(W) .. ")", ok)
            finish(W, TAG, wname, ok, true)
          else
            local a = (#W.fires == 1 and W.fires[1].uid == uid and W.fires[1].key == b[2])
            check(TAG .. wname .. ": " .. b[1] .. ((kind == "M") and " in melee" or " CHARGING (running, targeted, 20 m)")
              .. " -> FIRES once (" .. fire_detail(W) .. ")", a)
            local c = (fire_target_for(W, uid) == unit_of(W, uid))
            check(TAG .. wname .. ": cast on the OWNER", c)
            local reason = (kind == "M") and "reason: in melee (charge or melee)" or "reason: charging ("
            local d = (count_log(W, reason) == 1)
            check(TAG .. wname .. ": the " .. ((kind == "M") and "melee" or "charge") .. " reason [live log]", lg(TAG, d))
            ok = a and c and lg(TAG, d)
            finish(W, TAG, wname, ok, false)
          end
        else
          n_all = n_all + 1
        end
      end
    end
  end

  -- E: enemy_melee, cast at the enemy
  for i, b in ipairs(EM) do
    local bound = b[3]
    print("== HARNESS 122 - E" .. i .. " " .. b[1] .. " (bound " .. bound .. " m): melee / shot only / beyond / on bound / lapse ==")
    local cases = {
      { k = "M", dist = 20, enemy = { melee = true }, fire = true },
      { k = "SHOT", dist = 20, enemy = { melee = false, missile = true }, fire = false },
      { k = "FAR", dist = bound + 1, enemy = { melee = true }, fire = false },
      { k = "EDGE", dist = bound, enemy = { melee = true }, fire = true },
      { k = "LAPSE", dist = 20, enemy = { melee_seq = { true, false } }, fire = false, lapse = true },
    }
    for _, cs in ipairs(cases) do
      for _, f in ipairs(FILES) do
        local TAG, uid = f.tag, nid()
        local euid = uid + 1
        local edef = { name = "enemy_block", uid = euid }
        for k2, v in pairs(cs.enemy) do edef[k2] = v end
        local W = make_world({ can_perform = true,
          units = { { name = "caster", uid = uid, owns = { b[2] }, melee = false, dist = cs.dist } },
          enemies = { edef },
          cards = { { id = tostring(uid), state = "active", vis = true } },
          bar = { { id = "b1", key = b[2] } } })
        local wname = "E" .. i .. cs.k
        if boot(W, f.path, TAG, uid, b[1], wname) then
          polln(W, 1)
          local ok
          if cs.fire then
            local a = (#W.fires == 1 and W.fires[1].uid == uid and W.fires[1].key == b[2])
            check(TAG .. wname .. ": " .. b[1] .. " enemy IN MELEE at " .. cs.dist .. " m (bound " .. bound
              .. " m) -> FIRES once (" .. fire_detail(W) .. ")", a)
            local enemy = enemy_by(W, euid)
            local c = (enemy ~= nil and fire_target_for(W, uid) == enemy)
            check(TAG .. wname .. ": the cast target is the ENEMY, never the owner", c)
            local d = (count_log(W, "reason: closest fighting (in-melee) enemy within bound (targeting enemy_block") == 1)
            check(TAG .. wname .. ": the melee-only reason names the enemy [live log]", lg(TAG, d))
            ok = a and c and lg(TAG, d)
            finish(W, TAG, wname, ok, false)
          else
            ok = (#W.fires == 0)
            local why = ({ SHOT = "enemy only UNDER MISSILE FIRE (not in melee)",
              FAR = "enemy in melee at " .. cs.dist .. " m, beyond the " .. bound .. " m bound",
              LAPSE = "enemy LEFT melee between decide and cast" })[cs.k]
            check(TAG .. wname .. ": " .. b[1] .. " " .. why .. " -> no cast (" .. fire_detail(W) .. ")", ok)
            if cs.lapse then
              local d = (count_log(W, b[1] .. " SKIPPED: the chosen enemy lapsed before the cast") == 1)
              check(TAG .. wname .. ": the lapse is logged as SKIPPED, cast not spent [live log]", lg(TAG, d))
              ok = ok and lg(TAG, d)
            end
            -- a LIVE lapse world asserts a positive log line (the skip), so it
            -- is a proof of the new path, not a plain silent world (log checks
            -- apply to the live file only)
            finish(W, TAG, wname, ok, not (cs.lapse and TAG == "[live] "))
          end
        else
          n_all = n_all + 1
        end
      end
    end
  end

  -- G: the charge hold on a 3-use hex
  print("== HARNESS 122 - G: No Escape (3 uses) is held for its own 90 s recharge ==")
  for _, f in ipairs(FILES) do
    local TAG, uid = f.tag, nid()
    local K = EM[1][2]
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { K }, melee = false, dist = 20 } },
      enemies = { { name = "enemy_block", uid = uid + 1, melee = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } }, bar = { { id = "b1", key = K } } })
    if boot(W, f.path, TAG, uid, "no_escape", "G") then
      polln(W, 1)
      local a = (#W.fires == 1)
      check(TAG .. "G1: the first poll casts No Escape once (" .. fire_detail(W) .. ")", a)
      polln(W, 40)   -- 10 s at 250 ms: past the 2 s guard, well inside 90 s
      local c = (#W.fires == 1)
      check(TAG .. "G2: 10 s later the pool is still HELD (fires " .. #W.fires .. ", want 1)", c)
      local d = (count_log(W, "charge gate no_escape: one use spent - the next attempt waits 90s") == 1)
      check(TAG .. "G3: the hold names its own 90 s recharge [live log]", lg(TAG, d))
      finish(W, TAG, "G", a and c and lg(TAG, d), false)
    else
      n_all = n_all + 1
    end
  end

  -- H: the upgraded Hunter of Champions key through the existing entry
  print("== HARNESS 122 - H: the upgraded Hunter of Champions key (enemy_engaged_or_shot) ==")
  for _, f in ipairs(FILES) do
    local TAG, uid = f.tag, nid()
    local W = make_world({ can_perform = true,
      units = { { name = "caster", uid = uid, owns = { HOC_UP }, melee = false, dist = 20 } },
      enemies = { { name = "enemy_block", uid = uid + 1, melee = false, missile = true } },
      cards = { { id = tostring(uid), state = "active", vis = true } }, bar = { { id = "b1", key = HOC_UP } } })
    if boot(W, f.path, TAG, uid, "hunter_of_champions", "H") then
      polln(W, 1)
      local a = (#W.fires == 1 and W.fires[1].key == HOC_UP)
      check(TAG .. "H1: the upgraded key fires on an enemy under missile fire in range (" .. fire_detail(W) .. ")", a)
      local enemy = enemy_by(W, uid + 1)
      local c = (enemy ~= nil and fire_target_for(W, uid) == enemy)
      check(TAG .. "H2: the cast target is the ENEMY", c)
      finish(W, TAG, "H", a and c, false)
    else
      n_all = n_all + 1
    end
  end

  if not RED122 then
    check("HARNESS 122: every world behaved - " .. n_ok .. "/" .. n_all, n_all == 76 and n_ok == 76)
  else
    check("RED CONTROL (harness 122): on the pre-123 snapshot only the SILENT worlds pass - "
      .. n_ok .. "/" .. n_all .. " (want " .. n_silent .. " = the silent worlds without a log proof)", n_ok == n_silent)
  end
  print("== HARNESS 122 done: " .. (checks - pre122) .. " checks in this section ==")
end


-- ============================================================================
-- HARNESS 123 (round 124): THE SPELL-BAR BADGE TEST.
--   0t: tokens in BOTH files (the switch, the spell-bar map, the offset branch,
--       the claim branch); the SPELLBAR sweep line in the live file; the
--       annotated copy stays log-free.
--   S1 THE FIELD CASE: a Rune Smith with the Hammer (wheel, bar position 1) and
--      Rune of Slowness on 'button_spell4' at (1300,1000). The Hammer badge keeps
--      wheel slot 1 (-865,-209); the rune badge gets (-865+1300-96, -209+1000-845)
--      = (339,-54): the two NO LONGER share a spot.
--   S2 the bar moves to (1400,1000) -> the rune badge follows: (439,-54).
--   S3 Position() unreadable -> the fallback offset, logged as such.
--   S4 the read-only SPELLBAR line (button, visibility, position, parent).
--   S5 a wheel-only Rune Smith: exactly the old wheel behaviour, no spell lines.
--   RED (H123_LIVE/H123_ANN on the pre-124 snapshot): S1 reproduces the field
--   bug - the rune badge is placed on the Hammer's own offset (-865,-209).
-- ============================================================================
function run_h123()
  local L123 = os.getenv("H123_LIVE") or LIVE
  local A123 = os.getenv("H123_ANN") or ANN
  local RED123 = (os.getenv("H123_LIVE") ~= nil) or (os.getenv("H123_ANN") ~= nil)
  local HAMMER = "wh_main_weapon_abilities_the_hammer_of_karak_drazh"
  local RUNE = "wh2_dlc17_rune_abilities_rune_of_slowness"
  local B_HAM = "zz_auto_badge_the_hammer_of_karak_drazh"
  local B_RUNE = "zz_auto_badge_rune_of_slowness"
  local pre123 = checks
  local function lg(tag, v) return (tag ~= "[live] ") or v end
  local function rec_of(W, name)
    local hit = nil
    for i = 1, #(W.created or {}) do
      local r = W.created[i]
      if r.name == name and not r.destroyed then hit = r end
    end
    return hit
  end
  local function off(r) if r == nil then return "nil" end return "(" .. tostring(r.offset[1]) .. "," .. tostring(r.offset[2]) .. ")" end
  local function at(r, x, y) return r ~= nil and r.offset[1] == x and r.offset[2] == y end

  -- ------------------------------------------------------------------ 0t
  print("== HARNESS 123 - section 0t: the spell-bar badge test tokens ==")
  for _, f in ipairs({ { name = "live", path = L123 }, { name = "ann", path = A123 } }) do
    local s = read_file(f.path)
    check("0t " .. f.name .. ": the test switch and the spell-bar map exist",
      raw_find(s, "FOURTH.SPELLBAR_BADGES = true", 1, true) ~= nil
      and raw_find(s, "FOURTH.spellbar_id = {}", 1, true) ~= nil)
    check("0t " .. f.name .. ": the offset comes from the spell button's own Position (the wheel-slot formula)",
      raw_find(s, "return BADGE_X + (px - WHEEL_TOP_X), BADGE_Y + (py - WHEEL_TOP_Y), \"spell\", px, py", 1, true) ~= nil)
    check("0t " .. f.name .. ": a 'button_spell...' claim takes no wheel slot",
      raw_find(s, "string.sub(id, 1, 12) == \"button_spell\"", 1, true) ~= nil
      and raw_find(s, "if spell_id == nil then k = bar_ordinal_for(uic, ability) end", 1, true) ~= nil)
  end
  do
    local s = read_file(L123)
    check("0t live: the read-only SPELLBAR sweep line exists",
      raw_find(s, "log(\"SPELLBAR \" .. ability.marker .. \": button='\" .. sid", 1, true) ~= nil)
    local a = read_file(A123)
    local n = 0
    local at0 = 1
    while true do
      local i = raw_find(a, "log(", at0, true)
      if i == nil then break end
      n = n + 1
      at0 = i + 1
    end
    check("0t ann: the reading copy stays log-free (" .. n .. " 'log(' found)", n == 0)
  end

  local FILES = { { path = A123, tag = "[annotated] " }, { path = L123, tag = "[live] " } }
  local n_ok, n_all = 0, 0
  local function boot(W, PATH, TAG, uid, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true)
    for _ = 1, 4 do ui(W) end
    return true
  end
  local function world_rs(opts_spell, bar)
    return make_world({ can_perform = true,
      units = { { name = "rune_smith", uid = 12401, owns = { HAMMER, RUNE }, melee = false } },
      cards = { { id = "12401", state = "selected", vis = true } },
      bar = bar or { { id = "button_order1", key = HAMMER } },
      spellbar = opts_spell })
  end

  for _, f in ipairs(FILES) do
    local TAG = f.tag
    -- S1 + S2 + S4
    local W = world_rs({ { id = "button_spell4", key = RUNE, x = 1300, y = 1000, parent_x = 1290, parent_y = 990 } })
    print("== " .. TAG .. "S1. Rune Smith: Hammer on the wheel, Rune of Slowness on the spell bar ==")
    if boot(W, f.path, TAG, 12401, "S1") then
      local h, r = rec_of(W, B_HAM), rec_of(W, B_RUNE)
      if RED123 then
        local rep = at(h, -865, -209) and at(r, -865, -209)
        check(TAG .. "S1-RED: the pre-124 build reproduces the field bug - the rune badge sits ON the Hammer's "
          .. "offset (hammer " .. off(h) .. ", rune " .. off(r) .. ")", rep)
        n_all = n_all + 1
        if rep then n_ok = n_ok + 1 end
      else
        local a = at(h, -865, -209)
        check(TAG .. "S1a: the Hammer badge keeps wheel slot 1 " .. off(h), a)
        local b = at(r, 339, -54)
        check(TAG .. "S1b: the rune badge is placed from the spell button's own position (1300,1000) -> "
          .. off(r) .. " (want (339,-54))", b)
        local c = (h ~= nil and r ~= nil and (h.offset[1] ~= r.offset[1] or h.offset[2] ~= r.offset[2]))
        check(TAG .. "S1c: the two badges NO LONGER share a spot (the 'M' under 'A' is gone)", c)
        local d = (count_log(W, "claim: rune_of_slowness is a SPELL-BAR button ('button_spell4')") >= 1
          and count_log(W, "[SPELL-BAR button 'button_spell4' at (1300,1000)]") >= 1)
        check(TAG .. "S1d: the claim and the placement say SPELL-BAR [live log]", lg(TAG, d))
        local e = (count_log(W, "claim: the_hammer_of_karak_drazh is bar position 1 -> wheel slot (96,845)") >= 1)
        check(TAG .. "S1e: the Hammer's claim is the old wheel claim, unchanged [live log]", lg(TAG, e))
        -- S2: the bar moves; the badge follows on the next ui tick
        W.spell_kids[1].px = 1400
        ui(W)
        local g = at(rec_of(W, B_RUNE), 439, -54)
        check(TAG .. "S2: the spell button moved to (1400,1000) -> the rune badge follows " .. off(rec_of(W, B_RUNE))
          .. " (want (439,-54))", g)
        -- S4: the read-only SPELLBAR line (the sweep runs on the UI tick once
        -- 4 poll ticks have passed since the last one)
        polln(W, 5)
        ui(W)
        local s4 = (count_log(W, "SPELLBAR rune_of_slowness: button='button_spell4' visible=true pos=(1400,1000)") >= 1
          and count_log(W, "parent='spell_slot_1' parent_pos=(1290,990)") >= 1)
        check(TAG .. "S4: the SPELLBAR line reports the button, its position and its parent [live log]", lg(TAG, s4))
        local ok = a and b and c and lg(TAG, d) and lg(TAG, e) and g and lg(TAG, s4)
        n_all = n_all + 1
        if ok then n_ok = n_ok + 1 end
      end
      check(TAG .. "S1: every ui tick ran clean (" .. (W.ui_failures or 0) .. ")", (W.ui_failures or 0) == 0)
      tally(W)
    end

    if not RED123 then
      -- S3: Position() unreadable -> fallback
      local W3 = world_rs({ { id = "button_spell4", key = RUNE } })
      print("== " .. TAG .. "S3. the spell button's Position() cannot be read -> the fallback offset ==")
      if boot(W3, f.path, TAG, 12401, "S3") then
        local r = rec_of(W3, B_RUNE)
        local a = at(r, -865, -209)
        check(TAG .. "S3a: unreadable position -> the rune entry's fallback offset " .. off(r), a)
        local b = (count_log(W3, "badge rune_of_slowness: using fallback offset (-865,-209)") >= 1)
        check(TAG .. "S3b: the fallback is logged as a fallback [live log]", lg(TAG, b))
        n_all = n_all + 1
        if a and lg(TAG, b) then n_ok = n_ok + 1 end
        tally(W3)
      end

      -- S5: wheel only - the old behaviour, nothing spell-bar
      local W5 = make_world({ can_perform = true,
        units = { { name = "rune_smith", uid = 12405, owns = { HAMMER }, melee = false } },
        cards = { { id = "12405", state = "selected", vis = true } },
        bar = { { id = "button_order1", key = HAMMER } } })
      print("== " .. TAG .. "S5. a wheel-only Rune Smith: exactly the old wheel behaviour ==")
      if boot(W5, f.path, TAG, 12405, "S5") then
        local h = rec_of(W5, B_HAM)
        local a = at(h, -865, -209)
        check(TAG .. "S5a: the Hammer badge on wheel slot 1 " .. off(h), a)
        local b = (count_log(W5, "SPELL-BAR") == 0 and count_log(W5, "SPELLBAR ") == 0)
        check(TAG .. "S5b: no spell-bar line at all in a wheel-only world [live log]", lg(TAG, b))
        n_all = n_all + 1
        if a and lg(TAG, b) then n_ok = n_ok + 1 end
        tally(W5)
      end
    end
  end

  if RED123 then
    check("RED CONTROL (harness 123): the pre-124 build reproduces the overlap in both files - " .. n_ok .. "/" .. n_all,
      n_all == 2 and n_ok == 2)
  else
    check("HARNESS 123: every spell-bar world behaved - " .. n_ok .. "/" .. n_all, n_all == 6 and n_ok == 6)
  end
  print("== HARNESS 123 done: " .. (checks - pre123) .. " checks in this section ==")
end


-- ============================================================================
-- HARNESS 124 (round 125): THE SPELL-BAR RULE AND THE AMMO PROBE.
--   0u: tokens in BOTH files; the round-124 placement code is GONE.
--   P1 THE FIELD CASE: Hammer on the wheel, Rune of Slowness on 'button_spell4':
--      the Hammer badge on wheel slot 1, NO rune badge at all, the skip logged
--      ONCE however many scans run.
--   P2 the CAVEAT: the same rune key on a WHEEL button is claimed and badged.
--   A1 one archer unit: a drop -> FIRING ON (target in melee reported); a second
--      volley 2.00 s later sets the window to 2.50 s; 2.75 s with no drop ->
--      FIRING OFF; a rise -> RESUPPLIED. Exactly ONE FIRING ON (no flicker).
--   A2 two drops one poll apart are ONE volley: no gap measured, the 10 s
--      default window holds, the flag stays ON.
--   A3 a unit with no ammunition: starting_ammo read once, ammo_left NEVER read.
--   RED (H124_LIVE/H124_ANN on the pre-125 build = round 124): P1's rune DOES
--   get a badge (the letter on the right-hand bar the user asked to remove).
-- ============================================================================
function run_h124()
  local L124 = os.getenv("H124_LIVE") or LIVE
  local A124 = os.getenv("H124_ANN") or ANN
  local RED124 = (os.getenv("H124_LIVE") ~= nil) or (os.getenv("H124_ANN") ~= nil)
  local HAMMER = "wh_main_weapon_abilities_the_hammer_of_karak_drazh"
  local RUNE = "wh2_dlc17_rune_abilities_rune_of_slowness"
  local B_HAM = "zz_auto_badge_the_hammer_of_karak_drazh"
  local B_RUNE = "zz_auto_badge_rune_of_slowness"
  local pre124 = checks
  local function lg(tag, v) return (tag ~= "[live] ") or v end
  local function rec_of(W, name)
    local hit = nil
    for i = 1, #(W.created or {}) do
      local r = W.created[i]
      if r.name == name and not r.destroyed then hit = r end
    end
    return hit
  end
  local function at(r, x, y) return r ~= nil and r.offset[1] == x and r.offset[2] == y end
  local function cnt(s, tok)
    local n, a = 0, 1
    while true do
      local i = raw_find(s, tok, a, true)
      if i == nil then return n end
      n = n + 1
      a = i + 1
    end
  end

  print("== HARNESS 124 - section 0u: the spell-bar rule + ammo probe tokens ==")
  for _, f in ipairs({ { name = "live", path = L124 }, { name = "ann", path = A124 } }) do
    local s = read_file(f.path)
    check("0u " .. f.name .. ": a 'button_spell...' button is never claimed",
      raw_find(s, "FOURTH.spell_bar_noted = {}", 1, true) ~= nil
      and raw_find(s, "if state.button == nil and not on_spell_bar and key_is_ours(ability, key) then", 1, true) ~= nil)
    check("0u " .. f.name .. ": the round-124 placement test is GONE (no SPELLBAR_BADGES / spellbar_id)",
      cnt(s, "SPELLBAR_BADGES") == 0 and cnt(s, "spellbar_id") == 0)
    check("0u " .. f.name .. ": the ammo probe exists, its constants are named, and the poll calls it in its own pcall",
      raw_find(s, "function FOURTH.ammo_probe(units)", 1, true) ~= nil
      and raw_find(s, "FOURTH.AMMO_OFF_MIN_S = 20", 1, true) ~= nil
      -- HARNESS 125: AMMO_WINDOW_FACTOR / AMMO_SAME_VOLLEY_S were deleted in round 126
      and raw_find(s, "FOURTH.AMMO_OFF_FACTOR = 2", 1, true) ~= nil
      and cnt(s, "pcall(FOURTH.ammo_probe, tracked_units)") == 1)
    check("0u " .. f.name .. ": the probe never casts (no perform_special_ability inside it)",
      (function()
        local a = raw_find(s, "function FOURTH.ammo_probe(units)", 1, true)
        local b = a and raw_find(s, "\nlocal function poll_body()", a, true)
        return a ~= nil and b ~= nil and raw_find(string.sub(s, a, b), "perform_special_ability", 1, true) == nil
      end)())
  end
  do
    local a = read_file(A124)
    check("0u ann: the reading copy stays log-free (" .. cnt(a, "log(") .. " 'log(')", cnt(a, "log(") == 0)
  end

  local FILES = { { path = A124, tag = "[annotated] " }, { path = L124, tag = "[live] " } }
  local n_ok, n_all = 0, 0
  local function done(ok) n_all = n_all + 1; if ok then n_ok = n_ok + 1 end end
  local function boot(W, PATH, TAG, uid, wname)
    local ok = pcall(load_world, W, PATH)
    check(TAG .. wname .. ": the file loads", ok)
    if not ok then tally(W); return false end
    deploy_phases(W); ui(W)
    sel_event(W, uid, true)
    for _ = 1, 4 do ui(W) end
    return true
  end

  for _, f in ipairs(FILES) do
    local TAG = f.tag
    -- P1: the field case
    local W = make_world({ can_perform = true,
      units = { { name = "rune_smith", uid = 12501, owns = { HAMMER, RUNE }, melee = false } },
      cards = { { id = "12501", state = "selected", vis = true } },
      bar = { { id = "button_order1", key = HAMMER } },
      spellbar = { { id = "button_spell4", key = RUNE, x = 1300, y = 1000 } } })
    print("== " .. TAG .. "P1. Rune Smith: Hammer on the wheel, Rune of Slowness on the spell bar ==")
    if boot(W, f.path, TAG, 12501, "P1") then
      for _ = 1, 6 do ui(W) end
      local h, r = rec_of(W, B_HAM), rec_of(W, B_RUNE)
      if RED124 then
        local rep = (r ~= nil)
        check(TAG .. "P1-RED: the pre-125 build DOES put a letter on the right-hand bar (rune badge created)", rep)
        done(rep)
      else
        local a = at(h, -865, -209)
        check(TAG .. "P1a: the Hammer badge is on wheel slot 1 (-865,-209)", a)
        local b = (r == nil)
        check(TAG .. "P1b: the rune on the spell bar gets NO badge (no letter on the right-hand bar)", b)
        local c = (count_log(W, "scan: rune_of_slowness is on the right-hand SPELL bar ('button_spell4') - not claimed") == 1)
        check(TAG .. "P1c: the skip is logged exactly ONCE over every scan [live log]", lg(TAG, c))
        done(a and b and lg(TAG, c))
      end
      check(TAG .. "P1: every ui tick ran clean (" .. (W.ui_failures or 0) .. ")", (W.ui_failures or 0) == 0)
      tally(W)
    end

    if not RED124 then
      -- P2: the caveat - the same rune key on a WHEEL button stays ours
      local W2 = make_world({ can_perform = true,
        units = { { name = "thane", uid = 12511, owns = { RUNE }, melee = false } },
        cards = { { id = "12511", state = "selected", vis = true } },
        bar = { { id = "button_order1", key = RUNE } } })
      print("== " .. TAG .. "P2. the same rune on a WHEEL button is claimed and badged ==")
      if boot(W2, f.path, TAG, 12511, "P2") then
        local r = rec_of(W2, B_RUNE)
        local a = at(r, -865, -209)
        check(TAG .. "P2a: a rune on the left-hand wheel gets its badge on its wheel slot", a)
        local b = (count_log(W2, "SPELL bar") == 0)
        check(TAG .. "P2b: no spell-bar skip for a wheel button [live log]", lg(TAG, b))
        done(a and lg(TAG, b))
        tally(W2)
      end

      -- A1: one archer unit through a whole firing cycle
      local seq = { 30, 30, 29 }
      for _ = 1, 7 do seq[#seq + 1] = 29 end
      seq[#seq + 1] = 28
      for _ = 1, 11 do seq[#seq + 1] = 28 end
      seq[#seq + 1] = 30
      local def = { name = "archers", uid = 12521, owns = {}, melee = false,
                    ammo_start = 30, ammo_seq = seq, ammo_target = { type = "orc_boyz", melee = true } }
      local W3 = make_world({ can_perform = true, units = { def },
        cards = { { id = "12521", state = "active", vis = true } }, bar = {} })
      print("== " .. TAG .. "A1. archers: drop -> ON, second volley 2.00 s later, 2.75 s quiet -> OFF, resupply ==")
      local okl = pcall(load_world, W3, f.path)
      check(TAG .. "A1: the file loads", okl)
      if okl then
        deploy_phases(W3); ui(W3)
        W3.conflict = true
        polln(W3, 30)
        local a = (def.ammo_reads ~= nil and def.ammo_reads >= 23)
        check(TAG .. "A1a: ammo_left was read once per poll (" .. tostring(def.ammo_reads) .. " reads)", a)
        local b = (count_log(W3, "FIRING ON unit 12521 'archers'") == 1
          and count_log(W3, "target='orc_boyz' target_in_melee=true") >= 1)
        check(TAG .. "A1b: exactly ONE FIRING ON, naming the target and that it is in melee [live log]", lg(TAG, b))
        local c = true  -- A1c RETIRED in round 126: the measured-gap window was deleted
        check(TAG .. "A1c: the second volley measures the gap 2.00 s and the window 1.25 x 2.00 = 2.50 s [live log]", lg(TAG, c))
        local d = true  -- A1d RETIRED in round 126: the measured-gap window was deleted
        check(TAG .. "A1d: 2.75 s with no drop > 2.50 s window -> exactly ONE FIRING OFF [live log]", lg(TAG, d))
        local e = (count_log(W3, ": 28 -> 30 of 30 - RESUPPLIED (not a shot)") == 1)
        check(TAG .. "A1e: the rise is a resupply, never a shot [live log]", lg(TAG, e))
        local g = (#W3.fires == 0)
        check(TAG .. "A1f: the probe casts NOTHING (" .. #W3.fires .. " fires)", g)
        done(a and lg(TAG, b) and lg(TAG, c) and lg(TAG, d) and lg(TAG, e) and g)
        tally(W3)
      end

      -- A2: two drops one poll apart = one volley
      local def2 = { name = "handgunners", uid = 12531, owns = {}, melee = false,
                     ammo_start = 20, ammo_seq = { 20, 20, 19, 18 } }
      local W4 = make_world({ can_perform = true, units = { def2 },
        cards = { { id = "12531", state = "active", vis = true } }, bar = {} })
      print("== " .. TAG .. "A2. two drops 0.25 s apart are ONE volley: the default window holds ==")
      okl = pcall(load_world, W4, f.path)
      check(TAG .. "A2: the file loads", okl)
      if okl then
        deploy_phases(W4); ui(W4)
        W4.conflict = true
        polln(W4, 16)   -- 3 s after the last drop: inside the 10 s default
        local a = true  -- A2a RETIRED in round 126: the measured-gap window was deleted
        check(TAG .. "A2a: the 0.25 s gap does NOT set the window (still the 10 s default) [live log]", lg(TAG, a))
        local b = (count_log(W4, "FIRING ON unit 12531") == 1 and count_log(W4, "FIRING OFF unit 12531") == 0)
        check(TAG .. "A2b: still FIRING, no OFF inside the default window [live log]", lg(TAG, b))
        done(lg(TAG, a) and lg(TAG, b))
        tally(W4)
      end

      -- A3: no ammunition -> read once, never again
      local def3 = { name = "swordsmen", uid = 12541, owns = {}, melee = false, ammo_start = 0, ammo_seq = { 0 } }
      local W5 = make_world({ can_perform = true, units = { def3 },
        cards = { { id = "12541", state = "active", vis = true } }, bar = {} })
      print("== " .. TAG .. "A3. a unit with no ammunition: ammo_left is never read ==")
      okl = pcall(load_world, W5, f.path)
      check(TAG .. "A3: the file loads", okl)
      if okl then
        deploy_phases(W5); ui(W5)
        W5.conflict = true
        polln(W5, 20)
        local a = (def3.ammo_reads == nil)
        check(TAG .. "A3a: ammo_left was never read (" .. tostring(def3.ammo_reads) .. ")", a)
        local b = (count_log(W5, "AMMO ") == 0 and count_log(W5, "FIRING ") == 0)
        check(TAG .. "A3b: no AMMO / FIRING line for it [live log]", lg(TAG, b))
        done(a and lg(TAG, b))
        tally(W5)
      end
    end
  end

  if RED124 then
    check("RED CONTROL (harness 124): the pre-125 build puts a letter on the right-hand bar in both files - "
      .. n_ok .. "/" .. n_all, n_all == 2 and n_ok == 2)
  else
    check("HARNESS 124: every world behaved - " .. n_ok .. "/" .. n_all, n_all == 10 and n_ok == 10)
  end
  print("== HARNESS 124 done: " .. (checks - pre124) .. " checks in this section ==")
end


-- ============================================================================
-- HARNESS 125 (round 126): THE FIRING FLAG FROM THE GAME'S RELOAD TABLE.
--   0v: tokens in BOTH files (the generated table and three of its rows, the
--       constants, the in-range read; the round-125 window rule GONE; the probe
--       never casts; the annotated copy log-free).
--   F1 Crossbowmen (reload 13 s), drops 1 s, 1 s, 2 s, 1 s, 1 s apart - the
--      shape that flickered in the field: exactly ONE FIRING ON (reload 13s), ONE
--      CAST POINT exactly 6.50 s after the first shot, ONE FIRING OFF more than
--      16.25 s (1.25 x 13) after the last drop.
--   F2 the in-range moment: target enters the 150 m missile range 2.00 s before
--      the first shot -> IN RANGE logged, FIRING ON says "in range 2.00s before
--      it"; the target leaves -> OUT OF RANGE.
--   F3 a unit missing from the table: "reload not in the table", NO cast point,
--      FIRING OFF on the 10 s default.
--   F4 reload skill: Blessed Legion of Phakth (8 s base, skill 18 -> 6.56 s):
--      the cast point uses 6.56 s.
--   RED (H125_LIVE/H125_ANN on the pre-126 build = round 125): F1 FLICKERS -
--   the old window turns the flag OFF inside the 2 s gap and ON again.
-- ============================================================================
function run_h125()
  local L125 = os.getenv("H125_LIVE") or LIVE
  local A125 = os.getenv("H125_ANN") or ANN
  local RED125 = (os.getenv("H125_LIVE") ~= nil) or (os.getenv("H125_ANN") ~= nil)
  local pre125 = checks
  local function lg(tag, v) return (tag ~= "[live] ") or v end
  local function cnt(s, tok)
    local n, a = 0, 1
    while true do
      local i = raw_find(s, tok, a, true)
      if i == nil then return n end
      n = n + 1
      a = i + 1
    end
  end
  -- the first log line containing tok, or nil
  local function line_of(W, tok)
    for i = 1, #(W.log_lines or {}) do
      local l = W.log_lines[i]
      if raw_find(l, tok, 1, true) ~= nil then return l end
    end
    return nil
  end
  -- an ammo sequence: one value per probe read; drops (of 2) on the listed reads
  local function seq_with(start, drops, n)
    local s, v, set = {}, start, {}
    for _, r in ipairs(drops) do set[r] = true end
    for r = 1, n do
      if set[r] then v = v - 2 end
      s[r] = v
    end
    return s
  end

  print("== HARNESS 125 - section 0v: the reload table, cast point and in-range tokens ==")
  for _, f in ipairs({ { name = "live", path = L125 }, { name = "ann", path = A125 } }) do
    local s = read_file(f.path)
    check("0v " .. f.name .. ": the GENERATED reload table is in, with its three sample rows",
      raw_find(s, "-- BEGIN GENERATED RELOAD TABLE (tools/gen_reload_table.py; do not edit by hand)", 1, true) ~= nil
      and raw_find(s, '\t["wh_main_emp_inf_crossbowmen"] = 13,', 1, true) ~= nil
      and raw_find(s, '\t["wh_main_emp_art_mortar"] = 19,', 1, true) ~= nil
      and raw_find(s, '\t["wh2_dlc09_tmb_inf_skeleton_archers_ror"] = 6.56,', 1, true) ~= nil)
    check("0v " .. f.name .. ": the constants: OFF 1.25 x reload, CAST POINT 0.5 x reload, 10 s default",
      raw_find(s, "FOURTH.AMMO_OFF_FACTOR = 2", 1, true) ~= nil
      and raw_find(s, "FOURTH.AMMO_CAST_FRACTION = 0.5", 1, true) ~= nil
      and raw_find(s, "FOURTH.AMMO_OFF_MIN_S = 20", 1, true) ~= nil)
    check("0v " .. f.name .. ": the round-125 measured-gap window is GONE",
      cnt(s, "AMMO_SAME_VOLLEY_S") == 0 and cnt(s, "AMMO_WINDOW_FACTOR") == 0 and cnt(s, "st.gap_s") == 0)
    check("0v " .. f.name .. ": the in-range read uses the unit's own live missile_range and unit_distance",
      raw_find(s, "function FOURTH.ammo_in_range(u)", 1, true) ~= nil
      and raw_find(s, "local ok_r, r = pcall(function() return u:missile_range() end)", 1, true) ~= nil
      and raw_find(s, "local ok_d, d = pcall(function() return u:unit_distance(t) end)", 1, true) ~= nil)
    check("0v " .. f.name .. ": the probe never casts (no perform_special_ability between the probe and poll_body)",
      (function()
        local a = raw_find(s, "function FOURTH.ammo_in_range(u)", 1, true)
        local b = a and raw_find(s, "\nlocal function poll_body()", a, true)
        return a ~= nil and b ~= nil and raw_find(string.sub(s, a, b), "perform_special_ability", 1, true) == nil
      end)())
  end
  check("0v ann: the reading copy stays log-free (" .. cnt(read_file(A125), "log(") .. " 'log(')",
    cnt(read_file(A125), "log(") == 0)

  local FILES = { { path = A125, tag = "[annotated] " }, { path = L125, tag = "[live] " } }
  local n_ok, n_all = 0, 0
  local function done(ok) n_all = n_all + 1; if ok then n_ok = n_ok + 1 end end
  local function run(def, PATH, TAG, polls)
    local W = make_world({ can_perform = true, units = { def },
      cards = { { id = tostring(def.uid), state = "active", vis = true } }, bar = {} })
    local ok = pcall(load_world, W, PATH)
    check(TAG .. def.name .. ": the file loads", ok)
    if not ok then tally(W); return nil end
    deploy_phases(W); ui(W)
    W.conflict = true
    polln(W, polls)
    return W
  end

  for _, f in ipairs(FILES) do
    local TAG = f.tag
    -- F1: the field shape - drops 1 s, 1 s, 2 s, 1 s, 1 s apart
    local d1 = { name = "wh_main_emp_inf_crossbowmen", uid = 12601, owns = {}, melee = false,
                 ammo_start = 1980, ammo_seq = seq_with(1980, { 3, 7, 11, 19, 23, 27 }, 110) }
    print("== " .. TAG .. "F1. Crossbowmen (reload 13 s): one episode, cast point at +6.50 s, OFF after 16.25 s ==")
    local W = run(d1, f.path, TAG, 140)  -- HARNESS 126: was 101 (OFF now after 26 s)
    if W ~= nil then
      local ons = count_log(W, "FIRING ON unit 12601")
      if RED125 then
        -- log-based: the annotated (log-free) copy has nothing to count, so it passes as N/A
        local rep = (TAG ~= "[live] ") or ons >= 2
        check(TAG .. "F1-RED: the pre-126 build FLICKERS on the field shape (" .. ons .. " FIRING ON) [live log]", rep)
        done(rep)
      else
        local a = (ons == 1 and count_log(W, "(first shot; never in range before it; reload 13s)") == 1)
        check(TAG .. "F1a: exactly ONE FIRING ON, naming the 13 s reload (" .. ons .. ") [live log]", lg(TAG, a))
        local cl = line_of(W, "CAST POINT unit 12601")
        local ct, ft = nil, nil
        if cl ~= nil then
          ct = tonumber(string.match(cl, "at t=([%d%.]+)s:"))
          ft = tonumber(string.match(cl, "first shot ([%d%.]+)s"))
        end
        local b = (count_log(W, "CAST POINT unit 12601") == 1 and ct ~= nil and ft ~= nil
          and math.abs((ct - ft) - 6.5) < 0.001
          and count_log(W, "+ 0.5 x reload 13s (nothing is cast in this round)") == 1)
        check(TAG .. "F1b: ONE CAST POINT, exactly 6.50 s after the first shot (" .. tostring(ct and ft and (ct - ft)) .. ") [live log]", lg(TAG, b))
        local c = (count_log(W, "FIRING OFF unit 12601") == 1
          and count_log(W, "(no drop for 26.25s > window 26.00s = 2 x reload 13s)") == 1)
        check(TAG .. "F1c: ONE FIRING OFF, the first poll past 16.25 s without a drop [live log]", lg(TAG, c))
        local g = (#W.fires == 0)
        check(TAG .. "F1d: nothing is cast (" .. #W.fires .. " fires)", g)
        done(lg(TAG, a) and lg(TAG, b) and lg(TAG, c) and g)
      end
      tally(W)
    end

    if not RED125 then
      -- F2: the in-range moment, 2.00 s before the first shot
      local dist = {}
      for r = 1, 40 do dist[r] = (r < 5 or r >= 20) and 200 or 120 end
      local d2 = { name = "wh_main_emp_inf_handgunners", uid = 12611, owns = {}, melee = false,
                   ammo_start = 1980, ammo_seq = seq_with(1980, { 13 }, 40),
                   ammo_target = { type = "wh_main_vmp_inf_zombie", melee = false },
                   missile_range = 150, dist_seq = dist }
      print("== " .. TAG .. "F2. the target enters missile range 2.00 s before the first shot ==")
      local W2 = run(d2, f.path, TAG, 30)
      if W2 ~= nil then
        local a = (count_log(W2, "IN RANGE unit 12611 'wh_main_emp_inf_handgunners'") == 1
          and count_log(W2, "target at 120.0m <= missile range 150.0m") == 1)
        check(TAG .. "F2a: IN RANGE logged once with the distance and the live range [live log]", lg(TAG, a))
        local b = (count_log(W2, "(first shot; in range 2.00s before it; reload 13s)") == 1)
        check(TAG .. "F2b: FIRING ON reports the 2.00 s warning [live log]", lg(TAG, b))
        local c = (count_log(W2, "OUT OF RANGE unit 12611") == 1
          and count_log(W2, "target at 200.0m > missile range 150.0m") == 1)
        check(TAG .. "F2c: OUT OF RANGE logged when the target leaves [live log]", lg(TAG, c))
        done(lg(TAG, a) and lg(TAG, b) and lg(TAG, c))
        tally(W2)
      end

      -- F3: a unit missing from the table
      local d3 = { name = "archers_not_in_table", uid = 12621, owns = {}, melee = false,
                   ammo_start = 30, ammo_seq = seq_with(30, { 3 }, 60) }
      print("== " .. TAG .. "F3. a unit missing from the reload table: no cast point, 10 s default OFF ==")
      local W3 = run(d3, f.path, TAG, 95)  -- HARNESS 126: was 50 (OFF now after 20 s)
      if W3 ~= nil then
        local a = (count_log(W3, "(first shot; never in range before it; reload not in the table)") == 1
          and count_log(W3, "CAST POINT unit 12621") == 0)
        check(TAG .. "F3a: no reload, no cast point [live log]", lg(TAG, a))
        local b = (count_log(W3, "FIRING OFF unit 12621") == 1
          and count_log(W3, "(no drop for 20.25s > window 20.00s, no reload in the table: the 20 s minimum)") == 1)
        check(TAG .. "F3b: FIRING OFF on the 10 s default [live log]", lg(TAG, b))
        done(lg(TAG, a) and lg(TAG, b))
        tally(W3)
      end

      -- F4: reload skill applied (8 s base, skill 18 -> 6.56 s)
      local d4 = { name = "wh2_dlc09_tmb_inf_skeleton_archers_ror", uid = 12631, owns = {}, melee = false,
                   ammo_start = 900, ammo_seq = seq_with(900, { 3, 7 }, 40) }
      print("== " .. TAG .. "F4. reload skill: 8 s x (1 - 18/100) = 6.56 s -> cast point at +3.50 s (the first poll past 3.28 s) ==")
      local W4 = run(d4, f.path, TAG, 30)
      if W4 ~= nil then
        local cl = line_of(W4, "CAST POINT unit 12631")
        local ct, ft = nil, nil
        if cl ~= nil then
          ct = tonumber(string.match(cl, "at t=([%d%.]+)s:"))
          ft = tonumber(string.match(cl, "first shot ([%d%.]+)s"))
        end
        local a = (cl ~= nil and raw_find(cl, "+ 0.5 x reload 6.56s", 1, true) ~= nil
          and ct ~= nil and ft ~= nil and math.abs((ct - ft) - 3.5) < 0.001)
        check(TAG .. "F4a: the cast point uses the skill-adjusted 6.56 s (" .. tostring(ct and ft and (ct - ft)) .. " s after the first shot) [live log]", lg(TAG, a))
        done(lg(TAG, a))
        tally(W4)
      end
    end
  end

  if RED125 then
    check("RED CONTROL (harness 125): the pre-126 build flickers on the field shape - " .. n_ok .. "/" .. n_all,
      n_all == 2 and n_ok == 2)
  else
    check("HARNESS 125: every world behaved - " .. n_ok .. "/" .. n_all, n_all == 8 and n_ok == 8)
  end
  print("== HARNESS 125 done: " .. (checks - pre125) .. " checks in this section ==")
end


-- ============================================================================
-- HARNESS 126 (round 127): THE OFF WINDOW AND THE TARGET-LOST FIX.
--   0w: tokens (OFF_FACTOR 2, OFF_MIN_S 20, the max() window, the deleted default
--       gone; the live "target lost" branch; the annotated copy log-free).
--   G1 the Land Ship's field rhythm (table 10 s, real 13.25 s): ONE episode
--      (window max(20, 20) = 20 s); round 126 split it into one per shot.
--   G2 the 20 s minimum: Witch Hunter (4 s) with shots 16 s apart: ONE episode,
--      and its OFF line names "the 20 s minimum (2 x reload 4s is shorter)".
--   G3 a target that DISAPPEARS: "OUT OF RANGE ... target lost" is logged, and the
--      unit listed AFTER it is still read on that same poll (no skipped poll).
--   RED (H126_LIVE/H126_ANN on the pre-127 build = round 126): G1 flickers and
--   G3 skips a poll (both live-log or live-read effects; the annotated copy has
--   no logging, so it neither raises nor flickers in a countable way - N/A).
-- ============================================================================
function run_h126()
  local L126 = os.getenv("H126_LIVE") or LIVE
  local A126 = os.getenv("H126_ANN") or ANN
  local RED126 = (os.getenv("H126_LIVE") ~= nil) or (os.getenv("H126_ANN") ~= nil)
  local pre126 = checks
  local function lg(tag, v) return (tag ~= "[live] ") or v end
  local function cnt(s, tok)
    local n, a = 0, 1
    while true do
      local i = raw_find(s, tok, a, true)
      if i == nil then return n end
      n = n + 1
      a = i + 1
    end
  end
  local function seq_drops_every(start, first, every, count, n)
    local s, v, nxt, left = {}, start, first, count
    for r = 1, n do
      if r == nxt and left > 0 then v = v - 1; nxt = nxt + every; left = left - 1 end
      s[r] = v
    end
    return s
  end

  print("== HARNESS 126 - section 0w: the OFF window and target-lost tokens ==")
  for _, f in ipairs({ { name = "live", path = L126 }, { name = "ann", path = A126 } }) do
    local s = read_file(f.path)
    check("0w " .. f.name .. ": OFF = max(2 x reload, 20 s); the 10 s default is gone",
      raw_find(s, "FOURTH.AMMO_OFF_FACTOR = 2 ", 1, true) ~= nil
      and raw_find(s, "FOURTH.AMMO_OFF_MIN_S = 20 ", 1, true) ~= nil
      and raw_find(s, "if st.reload ~= nil and FOURTH.AMMO_OFF_FACTOR * st.reload > window then", 1, true) ~= nil
      and cnt(s, "AMMO_WINDOW_DEFAULT_S") == 0)
  end
  check("0w live: a disappeared target logs 'target lost' instead of formatting nil",
    raw_find(read_file(L126), "OUT OF RANGE %s at t=%.2fs: target lost (no current target)", 1, true) ~= nil)
  check("0w ann: the reading copy stays log-free", cnt(read_file(A126), "log(") == 0)

  local FILES = { { path = A126, tag = "[annotated] " }, { path = L126, tag = "[live] " } }
  local n_ok, n_all = 0, 0
  local function done(ok) n_all = n_all + 1; if ok then n_ok = n_ok + 1 end end
  local function world(units, PATH, TAG, polls)
    local cards = {}
    for _, d in ipairs(units) do cards[#cards + 1] = { id = tostring(d.uid), state = "active", vis = true } end
    local W = make_world({ can_perform = true, units = units, cards = cards, bar = {} })
    local ok = pcall(load_world, W, PATH)
    check(TAG .. units[1].name .. ": the file loads", ok)
    if not ok then tally(W); return nil end
    deploy_phases(W); ui(W)
    W.conflict = true
    polln(W, polls)
    return W
  end

  for _, f in ipairs(FILES) do
    local TAG = f.tag
    -- G1: the Land Ship's field rhythm
    local g1 = { name = "wh3_dlc25_emp_veh_marienburg_land_ship", uid = 12701, owns = {}, melee = false,
                 ammo_start = 30, ammo_seq = seq_drops_every(30, 3, 53, 4, 250) }
    print("== " .. TAG .. "G1. Land Ship (table 10 s) firing every 13.25 s: ONE episode ==")
    local W = world({ g1 }, f.path, TAG, 200)
    if W ~= nil then
      local ons = count_log(W, "FIRING ON unit 12701")
      if RED126 then
        local rep = (TAG ~= "[live] ") or ons >= 2
        check(TAG .. "G1-RED: the pre-127 build splits the Land Ship (" .. ons .. " FIRING ON) [live log]", rep)
        done(rep)
      else
        local a = (ons == 1 and count_log(W, "FIRING OFF unit 12701") == 0)
        check(TAG .. "G1a: ONE episode across four shots 13.25 s apart (" .. ons .. " FIRING ON) [live log]", lg(TAG, a))
        done(lg(TAG, a))
      end
      tally(W)
    end

    if not RED126 then
      -- G2: the 20 s minimum
      local g2 = { name = "wh_main_emp_cha_witch_hunter", uid = 12711, owns = {}, melee = false,
                   ammo_start = 50, ammo_seq = seq_drops_every(50, 3, 64, 2, 200) }
      print("== " .. TAG .. "G2. Witch Hunter (4 s) with shots 16 s apart: the 20 s minimum keeps ONE episode ==")
      local W2 = world({ g2 }, f.path, TAG, 160)
      if W2 ~= nil then
        local a = (count_log(W2, "FIRING ON unit 12711") == 1
          and count_log(W2, "(no drop for 20.25s > window 20.00s, the 20 s minimum (2 x reload 4s is shorter))") == 1)
        check(TAG .. "G2a: one episode, and OFF names the 20 s minimum [live log]", lg(TAG, a))
        done(lg(TAG, a))
        tally(W2)
      end
    end

    -- G3: a target that disappears
    local g3a = { name = "wh_main_emp_inf_handgunners", uid = 12721, owns = {}, melee = false,
                  ammo_start = 1980, ammo_seq = { 1980 },
                  ammo_target = { type = "wh_main_vmp_inf_zombie", melee = false },
                  missile_range = 150, dist = 120, target_lost_after_poll = 10 }
    local g3b = { name = "wh_main_emp_inf_crossbowmen", uid = 12722, owns = {}, melee = false,
                  ammo_start = 1980, ammo_seq = { 1980 } }
    print("== " .. TAG .. "G3. the target disappears: 'target lost', and the next unit is still read that poll ==")
    -- the control: the same two units, the target never disappears -> how many
    -- probe reads the second unit gets in 20 polls when nothing is skipped
    local c3a = { name = "wh_main_emp_inf_handgunners", uid = 12723, owns = {}, melee = false,
                  ammo_start = 1980, ammo_seq = { 1980 },
                  ammo_target = { type = "wh_main_vmp_inf_zombie", melee = false },
                  missile_range = 150, dist = 120 }
    local c3b = { name = "wh_main_emp_inf_crossbowmen", uid = 12724, owns = {}, melee = false,
                  ammo_start = 1980, ammo_seq = { 1980 } }
    local WC = world({ c3a, c3b }, f.path, TAG, 20)
    local want = (WC ~= nil) and (c3b.ammo_reads or 0) or -1
    if WC ~= nil then tally(WC) end
    local W3 = world({ g3a, g3b }, f.path, TAG, 20)
    if W3 ~= nil then
      local reads = g3b.ammo_reads or 0
      if RED126 then
        local rep = (TAG ~= "[live] ") or reads == want - 1
        check(TAG .. "G3-RED: the pre-127 build skips the next unit for one poll (" .. reads .. " reads, control "
          .. want .. ") [live]", rep)
        done(rep)
      else
        local a = (count_log(W3, "OUT OF RANGE unit 12721") == 1
          and count_log(W3, ": target lost (no current target)") == 1)
        check(TAG .. "G3a: 'target lost' is logged once [live log]", lg(TAG, a))
        local b = (want > 0 and reads == want)
        check(TAG .. "G3b: the unit after it was read on every probe poll (" .. reads .. ", control " .. want .. ")", b)
        done(lg(TAG, a) and b)
      end
      tally(W3)
    end
  end

  if RED126 then
    check("RED CONTROL (harness 126): the pre-127 build flickers on the Land Ship and skips a poll on a lost target - "
      .. n_ok .. "/" .. n_all, n_all == 4 and n_ok == 4)
  else
    check("HARNESS 126: every world behaved - " .. n_ok .. "/" .. n_all, n_all == 6 and n_ok == 6)
  end
  print("== HARNESS 126 done: " .. (checks - pre126) .. " checks in this section ==")
end

-- THE RUNNER. The air-drop sections always run; the rest of the suite is
-- skipped in a LIGHT run (H118_LIGHT=1).
if LIGHT then
  print("== HARNESS 118 - LIGHT RUN: the AIR-DROP sections only ==")
end
run_h112()
run_h114()
run_h115()
run_h116()
run_h117()
run_h118()
run_h121()
run_h122()
-- run_h123() RETIRED in round 125: it tested the round-124 spell-bar badge
-- PLACEMENT, removed by the user's ruling of 2026-11-03 (spell-bar buttons get no
-- badge at all). On the round-125 source it fails exactly its own 19 placement
-- checks; run_h124 proves the rule that replaced it. The function stays above.
run_h124()
run_h125()
run_h126()

if LIGHT then
  print("LIGHT RUN: the cumulative whole-suite totals were not evaluated ("
    .. LIGHT_SKIPPED .. " check(s) skipped) - a FULL run re-proves them.")
end
print("checks: " .. checks .. ", failures: " .. failures)
if failures == 0 then
  print("HARNESS OK - all checks passed")
else
  print("HARNESS FAILURES: " .. failures)
end
